            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
