export default Settings;

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { Client, StoreSettings } from '../types';
import { sendSMS, sendEmail } from '../services/notifications';
import { useStore } from './StoreContext';

export type BroadcastChannel = 'SMS' | 'EMAIL' | 'BOTH';

interface BroadcastProgress {
    processed: number;
    total: number;
    successSMS: number;
    successEmail: number;
    currentClientName: string;
}

interface BroadcastContextType {
    isSending: boolean;
    isComplete: boolean;
    progress: BroadcastProgress;
    secondsRemaining: number; 
    estimatedCompletionTime: Date | null; 
    startBroadcast: (
        recipients: Client[], 
        smsBody: string, 
        emailSubject: string, 
        emailBody: string, 
        useSafeMode: boolean,
        channel: BroadcastChannel
    ) => void;
    cancelBroadcast: () => void;
    dismissComplete: () => void;
}

const BroadcastContext = createContext<BroadcastContextType | undefined>(undefined);

export const BroadcastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { storeSettings, checkAndIncrementSms } = useStore(); 

    const [isSending, setIsSending] = useState(false);
    const [isComplete, setIsComplete] = useState(false);
    const [secondsRemaining, setSecondsRemaining] = useState(0); 
    const [estimatedCompletionTime, setEstimatedCompletionTime] = useState<Date | null>(null);

    const [progress, setProgress] = useState<BroadcastProgress>({
        processed: 0, 
        total: 0, 
        successSMS: 0, 
        successEmail: 0,
        currentClientName: ''
    });

    const queueRef = useRef<Client[]>([]);
    const abortControllerRef = useRef<boolean>(false);
    const settingsRef = useRef<StoreSettings>(storeSettings);
    const isProcessRunningRef = useRef<boolean>(false);

    useEffect(() => {
        settingsRef.current = storeSettings;
    }, [storeSettings]);

    useEffect(() => {
        const handleBeforeUnload = (e: BeforeUnloadEvent) => {
            if (isSending) {
                e.preventDefault();
                e.returnValue = '';
            }
        };
        window.addEventListener('beforeunload', handleBeforeUnload);
        return () => window.removeEventListener('beforeunload', handleBeforeUnload);
    }, [isSending]);

    const startBroadcast = (
        recipients: Client[], 
        smsBody: string, 
        emailSubject: string, 
        emailBody: string, 
        useSafeMode: boolean,
        channel: BroadcastChannel
    ) => {
        if (isProcessRunningRef.current) return;

        queueRef.current = recipients;
        abortControllerRef.current = false;
        isProcessRunningRef.current = true;

        // If channel is EMAIL only, we can potentially go faster, 
        // but sticking to user preference 'useSafeMode' for consistency unless forced otherwise.
        // However, if EMAIL ONLY is selected, we technically don't need "SMS Safe Mode" delays.
        // For simplicity, we respect the flag passed in.
        const delayPerItem = useSafeMode ? 125 : 5;
        const totalSeconds = Math.max(0, recipients.length - 1) * delayPerItem;
        const completionDate = new Date(Date.now() + totalSeconds * 1000);

        setEstimatedCompletionTime(completionDate);
        setIsComplete(false);
        setIsSending(true);
        setSecondsRemaining(0);
        setProgress({
            processed: 0,
            total: recipients.length,
            successSMS: 0,
            successEmail: 0,
            currentClientName: 'Initializing...'
        });

        processQueue(smsBody, emailSubject, emailBody, useSafeMode, channel);
    };

    const smartDelay = async (ms: number) => {
        let remainingSeconds = Math.ceil(ms / 1000);
        setSecondsRemaining(remainingSeconds);

        while (remainingSeconds > 0) {
            if (abortControllerRef.current) return;
            await new Promise(r => setTimeout(r, 1000));
            remainingSeconds--;
            setSecondsRemaining(remainingSeconds);
        }
    };

    const processQueue = async (
        smsBody: string, 
        emailSubject: string, 
        emailBody: string, 
        useSafeMode: boolean, 
        channel: BroadcastChannel
    ) => {
        const queue = queueRef.current;
        const SAFE_SMS_DELAY = 125000; 
        const FAST_DELAY = 5000; 

        let smsCount = 0;
        let emailCount = 0;

        const shouldSendSMS = channel === 'SMS' || channel === 'BOTH';
        const shouldSendEmail = channel === 'EMAIL' || channel === 'BOTH';

        try {
            for (let i = 0; i < queue.length; i++) {
                if (abortControllerRef.current) break;

                const client = queue[i];
                let sentSMSThisTurn = false;

                setProgress(prev => ({ ...prev, currentClientName: client.name }));

                // 1. Send SMS (CHECK LIMIT FIRST)
                if (shouldSendSMS && settingsRef.current.smsEnabled && client.contactNumber) {
                    if (checkAndIncrementSms()) {
                        const res = await sendSMS(settingsRef.current, [client.contactNumber], smsBody);
                        if (res.success) {
                            smsCount++;
                            sentSMSThisTurn = true;
                        }
                    } else {
                        console.warn("SMS Limit Reached. Skipping SMS for " + client.name);
                    }
                }

                // 2. Send Email
                if (shouldSendEmail && settingsRef.current.emailEnabled && client.email) {
                    const res = await sendEmail(settingsRef.current, client.email, emailSubject, emailBody, "Special Offer!");
                    if (res.success) emailCount++;
                }

                setProgress({
                    processed: i + 1,
                    total: queue.length,
                    successSMS: smsCount,
                    successEmail: emailCount,
                    currentClientName: client.name
                });

                if (i < queue.length - 1) {
                    const remainingItems = queue.length - 1 - i;

                    // If we only sent Email (or nothing sent), we can use FAST_DELAY regardless of Safe Mode
                    // Safe Mode is primarily for SMS anti-blocking.
                    const isSmsSent = sentSMSThisTurn;
                    const delayToUse = (isSmsSent && useSafeMode) ? SAFE_SMS_DELAY : FAST_DELAY;

                    const estimatedSecondsLeft = (remainingItems * delayToUse) / 1000;
                    setEstimatedCompletionTime(new Date(Date.now() + estimatedSecondsLeft * 1000));

                    if (isSmsSent && useSafeMode) {
                        await smartDelay(SAFE_SMS_DELAY);
                    } else {
                        await smartDelay(FAST_DELAY);
                    }
                }
            }
        } catch (err) {
            console.error("Broadcast interrupted", err);
        } finally {
            isProcessRunningRef.current = false;
            setIsSending(false);
            setSecondsRemaining(0);
            setEstimatedCompletionTime(null);

            if (!abortControllerRef.current) {
                setIsComplete(true);
                setTimeout(() => {
                    setIsComplete(false);
                }, 10000);
            }
        }
    };

    const cancelBroadcast = () => {
        abortControllerRef.current = true;
        isProcessRunningRef.current = false;
        setIsSending(false);
        setIsComplete(false);
        setSecondsRemaining(0);
        setEstimatedCompletionTime(null);
    };

    const dismissComplete = () => {
        setIsComplete(false);
    };

    return (
        <BroadcastContext.Provider value={{ 
            isSending, 
            isComplete, 
            progress, 
            secondsRemaining,
            estimatedCompletionTime,
            startBroadcast, 
            cancelBroadcast,
            dismissComplete
        }}>
            {children}
        </BroadcastContext.Provider>
    );
};

export const useBroadcast = () => {
    const context = useContext(BroadcastContext);
    if (!context) throw new Error('useBroadcast must be used within BroadcastProvider');
    return context;
};

import React, { useState, useMemo } from 'react';
import { Percent, Trash2, Tag, Calendar, Plus, MessageSquare, Search, CheckCircle, Smartphone, Users, Mail, Send, AlertCircle, Check, Clock, ArrowRight } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { useBroadcast, BroadcastChannel } from '../context/BroadcastContext';
import { Discount, DiscountTrigger, Client } from '../types';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';

const Discounts: React.FC = () => {
  const { discounts, addDiscount, toggleDiscount, deleteDiscount, products, clients, storeSettings } = useStore();
  const { startBroadcast, isSending } = useBroadcast();

  // State for Creating/Editing Discount
  const [activeTab, setActiveTab] = useState<'LIST' | 'CREATE'>('LIST');
  const [formData, setFormData] = useState<Partial<Discount>>({
    name: '', type: 'PERCENTAGE', value: 0, 
    triggerType: 'MANUAL', triggerValue: '', 
    isPermanent: true, startDate: '', endDate: ''
  });

  // State for Broadcasting Modal
  const [broadcastModalOpen, setBroadcastModalOpen] = useState(false);
  const [createdDiscount, setCreatedDiscount] = useState<Discount | null>(null);

  // New 3-Step Flow: CHOICE -> SELECT_CLIENTS (Optional) -> CONFIGURE
  const [broadcastStep, setBroadcastStep] = useState<'CHOICE' | 'SELECT_CLIENTS' | 'CONFIGURE'>('CHOICE');

  // Data for Broadcast
  const [selectedClientIds, setSelectedClientIds] = useState<string[]>([]);
  const [clientSearch, setClientSearch] = useState('');
  const [selectedChannel, setSelectedChannel] = useState<BroadcastChannel>('BOTH');

  // SMS Safety Settings - DEFAULT TRUE
  const [useSafeMode, setUseSafeMode] = useState(true);

  // Constants
  const MAX_BATCH_SIZE = 30; 

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Filter products for dropdown
  const productOptions = useMemo(() => products.map(p => ({ id: p.id, name: p.name })), [products]);

  // Filter clients for broadcast (Only show those with contact info)
  const availableClients = useMemo(() => {
      return clients.filter(c => c.contactNumber || c.email);
  }, [clients]);

  // Filter for search in "Select Specific" view
  const filteredClientsForSelection = useMemo(() => {
      return availableClients.filter(c => 
          c.name.toLowerCase().includes(clientSearch.toLowerCase()) ||
          (c.contactNumber && c.contactNumber.includes(clientSearch))
      );
  }, [availableClients, clientSearch]);

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.value) return;

    const newDiscount: Discount = {
      id: Date.now().toString(),
      name: formData.name,
      type: formData.type || 'PERCENTAGE',
      value: Number(formData.value),
      active: true,
      triggerType: formData.triggerType || 'MANUAL',
      triggerValue: formData.triggerValue,
      isPermanent: formData.isPermanent ?? true,
      startDate: formData.startDate,
      endDate: formData.endDate
    };

    addDiscount(newDiscount);

    // Reset Form
    setFormData({
        name: '', type: 'PERCENTAGE', value: 0, 
        triggerType: 'MANUAL', triggerValue: '', 
        isPermanent: true, startDate: '', endDate: ''
    });
    setActiveTab('LIST');

    // Open Broadcast Modal
    handleBroadcastClick(newDiscount);
  };

  const handleDeleteClick = (discount: Discount) => {
      setDeleteConfirmation({ isOpen: true, id: discount.id, name: discount.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteDiscount(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  // --- BROADCAST LOGIC ---

  const handleBroadcastClick = (discount: Discount) => {
      if (isSending) {
          alert("A broadcast is currently in progress. Please wait for it to finish.");
          return;
      }
      setCreatedDiscount(discount);
      setSelectedClientIds([]); // Reset selection
      setClientSearch('');
      setSelectedChannel('BOTH'); // Default
      setBroadcastStep('CHOICE');
      setBroadcastModalOpen(true);
  };

  // Step 1 Actions
  const handleSelectEveryone = () => {
      // Select All Available
      setSelectedClientIds(availableClients.map(c => c.id));
      setBroadcastStep('CONFIGURE');
  };

  const handleSelectSpecific = () => {
      setSelectedClientIds([]);
      setBroadcastStep('SELECT_CLIENTS');
  };

  // Step 2 Actions
  const handleSelectAllFiltered = () => {
      // If none selected, select up to MAX_BATCH_SIZE filtered items
      if (selectedClientIds.length === 0) {
          const toSelect = filteredClientsForSelection.slice(0, MAX_BATCH_SIZE).map(c => c.id);
          setSelectedClientIds(toSelect);
      } else {
          // Deselect All
          setSelectedClientIds([]);
      }
  };

  const handleToggleClient = (id: string) => {
      if (selectedClientIds.includes(id)) {
          setSelectedClientIds(prev => prev.filter(cid => cid !== id));
      } else {
          // Strict Limit Check
          if (selectedClientIds.length >= MAX_BATCH_SIZE) return;
          setSelectedClientIds(prev => [...prev, id]);
      }
  };

  const handleProceedToConfigure = () => {
      setBroadcastStep('CONFIGURE');
  };

  // Template Replacement Logic
  const replacePromoVariables = (template: string, discount: Discount) => {
      let rules = "";
      if (discount.triggerType === 'MIN_SPEND') rules = `Min spend: ₱${discount.triggerValue}.`;
      else if (discount.triggerType === 'ITEM_COUNT') rules = `Buy ${discount.triggerValue} items.`;

      const discountVal = discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`;

      const endDate = !discount.isPermanent && discount.endDate 
          ? new Date(discount.endDate).toLocaleDateString() 
          : "Limited time only";

      const data: Record<string, string> = {
          promoName: discount.name,
          discountValue: discountVal,
          rules: rules,
          endDate: endDate,
          shopName: storeSettings.name,
          address: storeSettings.address
      };

      let result = template;
      for (const key in data) {
          result = result.replace(new RegExp(`{${key}}`, 'g'), data[key]);
      }
      return result;
  };

  // Final Action
  const initiateBroadcast = () => {
      // Filter the actual client objects based on IDs
      const recipients = availableClients.filter(c => selectedClientIds.includes(c.id));

      if (recipients.length === 0 || !createdDiscount) return;

      // Prepare Messages
      const smsMsg = replacePromoVariables(storeSettings.smsTemplatePromo || "Promo: {promoName}", createdDiscount);
      const emailSubject = replacePromoVariables(storeSettings.emailSubjectPromo || "Special Promo", createdDiscount);
      const emailBody = replacePromoVariables(storeSettings.emailBodyPromo || "Check out {promoName}", createdDiscount);

      // Start Global Background Process with Channel Preference
      startBroadcast(recipients, smsMsg, emailSubject, emailBody, useSafeMode, selectedChannel);

      // Close Modal Immediately
      setBroadcastModalOpen(false);
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:ring-2 focus:ring-black focus:outline-none placeholder-zinc-400 text-sm font-medium";
  const labelClass = "text-xs font-bold text-gray-500 uppercase mb-1 block";

  // Calculate estimated time for display in the modal
  const estMinutes = useMemo(() => {
      const count = selectedClientIds.length;
      if (count <= 1) return 0;

      // If Channel is EMAIL ONLY, we assume it's fast regardless of safe mode (BroadcastContext handles this logic too usually, but for ETA display let's mirror it)
      // Actually BroadcastContext logic forces fast delay if safe mode is off OR if SMS wasn't sent.
      // So if channel === 'EMAIL', delay is 5s. If 'SMS'/'BOTH' and SafeMode, delay is 125s.

      const isSmsInvolved = selectedChannel === 'SMS' || selectedChannel === 'BOTH';
      const delay = (isSmsInvolved && useSafeMode) ? 125 : 5;

      const seconds = (count - 1) * delay;
      return Math.ceil(seconds / 60);
  }, [selectedClientIds.length, useSafeMode, selectedChannel]);

  return (
    <div className="space-y-6 h-[calc(100vh-100px)] flex flex-col">

       {/* Header */}
       <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Percent className="w-6 h-6" /> Discounts & Promos
            </h2>
            <p className="text-sm text-gray-500">Manage sales rules and blast notifications.</p>
          </div>
          <div className="flex bg-zinc-100 p-1 rounded-xl">
              <button 
                onClick={() => setActiveTab('LIST')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'LIST' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
              >
                  Active Promos
              </button>
              <button 
                onClick={() => setActiveTab('CREATE')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'CREATE' ? 'bg-black text-white shadow-md' : 'text-gray-500 hover:text-black'}`}
              >
                  <Plus className="w-4 h-4" /> Create New
              </button>
          </div>
       </div>

       {/* CREATE FORM */}
       {activeTab === 'CREATE' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto animate-fade-in">
               <form onSubmit={handleCreateSubmit} className="max-w-2xl mx-auto space-y-8">

                   {/* 1. Basic Info */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">1. Promo Details</h3>
                       <div>
                           <label className={labelClass}>Promo Name</label>
                           <input 
                                required
                                type="text" 
                                placeholder="e.g. Summer Sale, Loyal Customer" 
                                className={inputClass}
                                value={formData.name}
                                onChange={e => setFormData({...formData, name: e.target.value})}
                           />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                           <div>
                               <label className={labelClass}>Discount Type</label>
                               <select 
                                    className={inputClass}
                                    value={formData.type}
                                    onChange={e => setFormData({...formData, type: e.target.value as 'PERCENTAGE' | 'FIXED'})}
                               >
                                   <option value="PERCENTAGE">Percentage (%)</option>
                                   <option value="FIXED">Fixed Amount (₱)</option>
                               </select>
                           </div>
                           <div>
                               <label className={labelClass}>Value</label>
                               <input 
                                    required
                                    type="number" 
                                    placeholder="e.g. 10 or 50" 
                                    className={inputClass}
                                    value={formData.value || ''}
                                    onChange={e => setFormData({...formData, value: Number(e.target.value)})}
                               />
                           </div>
                       </div>
                   </div>

                   {/* 2. Triggers */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">2. Rules & Triggers</h3>
                       <div>
                           <label className={labelClass}>Trigger Condition</label>
                           <select 
                                className={inputClass}
                                value={formData.triggerType}
                                onChange={e => setFormData({...formData, triggerType: e.target.value as DiscountTrigger, triggerValue: ''})}
                           >
                               <option value="MANUAL">Manual Selection (Always Available)</option>
                               <option value="MIN_SPEND">Minimum Spend Amount</option>
                               <option value="ITEM_COUNT">Minimum Item Quantity</option>
                               <option value="SPECIFIC_PRODUCT">Buying a Specific Product</option>
                           </select>
                       </div>

                       {formData.triggerType !== 'MANUAL' && (
                           <div className="animate-fade-in">
                               <label className={labelClass}>
                                   {formData.triggerType === 'MIN_SPEND' ? 'Minimum Amount (₱)' : 
                                    formData.triggerType === 'ITEM_COUNT' ? 'Minimum Quantity' : 
                                    'Select Product'}
                               </label>

                               {formData.triggerType === 'SPECIFIC_PRODUCT' ? (
                                   <select 
                                        className={inputClass}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   >
                                       <option value="">-- Choose Product --</option>
                                       {productOptions.map(p => (
                                           <option key={p.id} value={p.id}>{p.name}</option>
                                       ))}
                                   </select>
                               ) : (
                                   <input 
                                        type="number"
                                        className={inputClass}
                                        placeholder={formData.triggerType === 'MIN_SPEND' ? '500' : '3'}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   />
                               )}
                           </div>
                       )}
                   </div>

                   {/* 3. Duration */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">3. Duration</h3>
                       <div className="flex items-center gap-4">
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: true})}
                                    className="accent-black w-4 h-4"
                               />
                               <span className="text-sm font-bold">Permanent</span>
                           </label>
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={!formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: false})}
                                    className="accent-black w-4 h-4"
                               />
                               <span className="text-sm font-bold">Set Date Range</span>
                           </label>
                       </div>

                       {!formData.isPermanent && (
                           <div className="grid grid-cols-2 gap-4 animate-fade-in">
                               <div>
                                   <label className={labelClass}>Start Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.startDate}
                                        onChange={e => setFormData({...formData, startDate: e.target.value})}
                                   />
                               </div>
                               <div>
                                   <label className={labelClass}>End Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.endDate}
                                        onChange={e => setFormData({...formData, endDate: e.target.value})}
                                   />
                               </div>
                           </div>
                       )}
                   </div>

                   <div className="pt-4 flex gap-3">
                       <Button type="button" variant="ghost" className="flex-1" onClick={() => setActiveTab('LIST')}>Cancel</Button>
                       <Button type="submit" className="flex-1 bg-black text-white shadow-lg">Save & Notify</Button>
                   </div>
               </form>
           </div>
       )}

       {/* LIST VIEW */}
       {activeTab === 'LIST' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto">
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                   {discounts.map(discount => (
                       <div key={discount.id} className="border border-zinc-200 rounded-2xl p-5 flex flex-col justify-between hover:shadow-md transition-shadow relative overflow-hidden group">
                           {/* Status Badge */}
                           <div className="absolute top-4 right-4">
                               <button 
                                    onClick={() => toggleDiscount(discount.id)}
                                    className={`text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${discount.active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}
                               >
                                   {discount.active ? 'Active' : 'Inactive'}
                               </button>
                           </div>

                           <div>
                               <h3 className="font-bold text-lg text-zinc-900 truncate pr-16">{discount.name}</h3>
                               <p className="text-2xl font-bold text-black mt-1">
                                   {discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`}
                                </p>

                               <div className="mt-4 space-y-2">
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Tag className="w-3 h-3" />
                                       <span>
                                           {discount.triggerType === 'MANUAL' && "Manual Apply"}
                                           {discount.triggerType === 'MIN_SPEND' && `Min Spend: ₱${discount.triggerValue}`}
                                           {discount.triggerType === 'ITEM_COUNT' && `Min Items: ${discount.triggerValue}`}
                                           {discount.triggerType === 'SPECIFIC_PRODUCT' && "Specific Product"}
                                       </span>
                                   </div>
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Calendar className="w-3 h-3" />
                                       <span>
                                           {discount.isPermanent ? "Permanent Validity" : 
                                            `${new Date(discount.startDate!).toLocaleDateString()} - ${new Date(discount.endDate!).toLocaleDateString()}`}
                                       </span>
                                   </div>
                               </div>
                           </div>

                           <div className="mt-4 pt-4 border-t border-zinc-100 flex justify-end">
                               <button 
                                    onClick={() => handleBroadcastClick(discount)}
                                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors mr-2"
                                    title="Send/Remind"
                               >
                                   <Send className="w-4 h-4" />
                               </button>
                               <button 
                                    onClick={() => handleDeleteClick(discount)}
                                    className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Delete"
                               >
                                   <Trash2 className="w-4 h-4" />
                                </button>
                           </div>
                       </div>
                   ))}
                   {discounts.length === 0 && (
                       <div className="col-span-full py-20 text-center text-gray-400 flex flex-col items-center justify-center">
                           <Tag className="w-12 h-12 opacity-20 mb-2" />
                           <p>No active promotions.</p>
                       </div>
                   )}
               </div>
           </div>
       )}

       {/* BROADCAST MODAL */}
       <Dialog open={broadcastModalOpen} onClose={() => setBroadcastModalOpen(false)} className="relative z-50">
            <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
            <div className="fixed inset-0 flex items-center justify-center p-4">
                <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl relative flex flex-col max-h-[90vh]">

                    {/* STEP 1: CHOICE */}
                    {broadcastStep === 'CHOICE' && (
                        <div className="text-center">
                            <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4 text-blue-600">
                                <MessageSquare className="w-8 h-8" />
                            </div>
                            <h2 className="text-2xl font-bold text-zinc-900">Broadcast Promo</h2>
                            <p className="text-gray-500 mt-2 mb-6">
                                <strong>{createdDiscount?.name}</strong> is ready. Who would you like to notify?
                            </p>

                            <div className="space-y-3">
                                {/* Option A: Send to Everyone */}
                                <button 
                                    onClick={handleSelectEveryone}
                                    className="w-full p-4 rounded-2xl border-2 border-zinc-100 hover:border-blue-500 hover:bg-blue-50 transition-all flex items-center gap-4 group text-left"
                                >
                                    <div className="w-12 h-12 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                                        <Users className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-zinc-900">Send to Everyone</h3>
                                        <p className="text-xs text-gray-500">Quickly notify all {availableClients.length} clients.</p>
                                    </div>
                                    <ArrowRight className="w-5 h-5 text-gray-300 ml-auto group-hover:text-blue-500" />
                                </button>

                                {/* Option B: Select Specific */}
                                <button 
                                    onClick={handleSelectSpecific}
                                    className="w-full p-4 rounded-2xl border-2 border-zinc-100 hover:border-purple-500 hover:bg-purple-50 transition-all flex items-center gap-4 group text-left"
                                >
                                    <div className="w-12 h-12 rounded-full bg-purple-100 text-purple-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                                        <CheckCircle className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-zinc-900">Select Specific Clients</h3>
                                        <p className="text-xs text-gray-500">Choose from the list manually.</p>
                                    </div>
                                    <ArrowRight className="w-5 h-5 text-gray-300 ml-auto group-hover:text-purple-500" />
                                </button>

                                {/* Option C: Skip */}
                                <button 
                                    onClick={() => setBroadcastModalOpen(false)}
                                    className="w-full p-3 rounded-xl text-sm font-bold text-gray-400 hover:text-gray-600 hover:bg-zinc-50"
                                >
                                    Cancel
                                </button>
                            </div>
                        </div>
                    )}

                    {/* STEP 2: SELECT CLIENTS (Optional) */}
                    {broadcastStep === 'SELECT_CLIENTS' && (
                        <div className="flex flex-col h-[500px]">
                            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                                <Smartphone className="w-5 h-5" /> Select Recipients
                            </h2>

                            <div className="mb-4 flex gap-2">
                                <div className="relative flex-1">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                    <input 
                                        type="text" 
                                        className="w-full pl-9 pr-3 py-2 border border-zinc-200 rounded-xl text-sm focus:ring-1 focus:ring-black outline-none"
                                        placeholder="Search name or number..."
                                        value={clientSearch}
                                        onChange={e => setClientSearch(e.target.value)}
                                    />
                                </div>
                                <Button size="sm" variant="secondary" onClick={handleSelectAllFiltered}>
                                    {selectedClientIds.length > 0 ? 'Deselect All' : `Select Top ${MAX_BATCH_SIZE}`}
                                </Button>
                            </div>

                            {/* Warning Limit Banner */}
                            {selectedClientIds.length >= MAX_BATCH_SIZE ? (
                                <div className="mb-2 bg-red-50 text-red-700 text-xs px-3 py-2 rounded-lg border border-red-100 flex items-center gap-2 font-bold">
                                    <AlertCircle className="w-4 h-4 shrink-0" />
                                    <span>Batch Limit Reached ({MAX_BATCH_SIZE}/{MAX_BATCH_SIZE})</span>
                                </div>
                            ) : (
                                <div className="mb-2 bg-purple-50 text-purple-700 text-xs px-3 py-2 rounded-lg border border-purple-100 flex items-center gap-2 font-bold justify-between">
                                    <span>Selected: {selectedClientIds.length}</span>
                                    <span>Max: {MAX_BATCH_SIZE}</span>
                                </div>
                            )}

                            <div className="flex-1 overflow-y-auto border border-zinc-100 rounded-xl bg-zinc-50 p-2 space-y-1">
                                {filteredClientsForSelection.map(client => {
                                    const isSelected = selectedClientIds.includes(client.id);
                                    // Disable if not selected AND limit reached
                                    const isDisabled = !isSelected && selectedClientIds.length >= MAX_BATCH_SIZE;

                                    return (
                                    <label 
                                        key={client.id} 
                                        className={`flex items-center gap-3 p-3 rounded-lg border transition-all ${
                                            isDisabled ? 'opacity-50 cursor-not-allowed bg-zinc-100 border-zinc-200' 
                                            : isSelected ? 'bg-purple-50 border-purple-200 cursor-pointer' 
                                            : 'bg-white border-zinc-100 hover:border-purple-300 cursor-pointer'
                                        }`}
                                    >
                                        <div className={`w-5 h-5 rounded border flex items-center justify-center shrink-0 ${isSelected ? 'bg-purple-600 border-purple-600' : 'bg-white border-gray-300'}`}>
                                            {isSelected && <Check className="w-3 h-3 text-white" />}
                                        </div>
                                        <input 
                                            type="checkbox" 
                                            className="hidden"
                                            checked={isSelected}
                                            disabled={isDisabled}
                                            onChange={() => handleToggleClient(client.id)}
                                        />
                                        <div className="flex-1 min-w-0">
                                            <p className="font-bold text-sm text-zinc-900 truncate">{client.name}</p>
                                            <div className="flex gap-2 text-[10px] text-gray-500 mt-0.5">
                                                {client.contactNumber && <span className="flex items-center gap-1 truncate"><Smartphone className="w-3 h-3 shrink-0"/> {client.contactNumber}</span>}
                                                {client.email && <span className="flex items-center gap-1 truncate"><Mail className="w-3 h-3 shrink-0"/> {client.email}</span>}
                                            </div>
                                        </div>
                                    </label>
                                    );
                                })}
                                {filteredClientsForSelection.length === 0 && <p className="text-center text-gray-400 py-4 text-xs">No clients found.</p>}
                            </div>

                            <div className="mt-4 flex gap-3">
                                <Button variant="ghost" onClick={() => setBroadcastStep('CHOICE')} className="flex-1">Back</Button>
                                <Button 
                                    className="flex-1 bg-black hover:bg-zinc-800"
                                    disabled={selectedClientIds.length === 0}
                                    onClick={handleProceedToConfigure}
                                >
                                    Configure Send ({selectedClientIds.length})
                                </Button>
                            </div>
                        </div>
                    )}

                    {/* STEP 3: CONFIGURE */}
                    {broadcastStep === 'CONFIGURE' && (
                        <div className="flex flex-col">
                            <h2 className="text-xl font-bold mb-4 text-center">Configure Broadcast</h2>

                            <div className="bg-zinc-50 border border-zinc-100 rounded-xl p-4 mb-6 text-center">
                                <p className="text-xs text-gray-500 uppercase font-bold mb-1">Recipients</p>
                                <p className="text-3xl font-bold text-zinc-900">{selectedClientIds.length}</p>
                                <p className="text-xs text-gray-400 mt-1">Clients selected</p>
                            </div>

                            <p className="text-sm font-bold text-zinc-700 mb-2">Select Channel</p>
                            <div className="grid grid-cols-3 gap-2 mb-6">
                                <button 
                                    onClick={() => setSelectedChannel('SMS')}
                                    className={`p-3 rounded-xl border-2 flex flex-col items-center gap-1 transition-all ${
                                        selectedChannel === 'SMS' 
                                        ? 'border-blue-600 bg-blue-50 text-blue-700' 
                                        : 'border-zinc-100 bg-white text-gray-400 hover:border-zinc-300'
                                    }`}
                                >
                                    <Smartphone className="w-5 h-5" />
                                    <span className="text-xs font-bold">SMS Only</span>
                                </button>
                                <button 
                                    onClick={() => setSelectedChannel('EMAIL')}
                                    className={`p-3 rounded-xl border-2 flex flex-col items-center gap-1 transition-all ${
                                        selectedChannel === 'EMAIL' 
                                        ? 'border-orange-500 bg-orange-50 text-orange-700' 
                                        : 'border-zinc-100 bg-white text-gray-400 hover:border-zinc-300'
                                    }`}
                                >
                                    <Mail className="w-5 h-5" />
                                    <span className="text-xs font-bold">Email Only</span>
                                </button>
                                <button 
                                    onClick={() => setSelectedChannel('BOTH')}
                                    className={`p-3 rounded-xl border-2 flex flex-col items-center gap-1 transition-all ${
                                        selectedChannel === 'BOTH' 
                                        ? 'border-black bg-zinc-900 text-white' 
                                        : 'border-zinc-100 bg-white text-gray-400 hover:border-zinc-300'
                                    }`}
                                >
                                    <div className="flex gap-1">
                                        <Smartphone className="w-4 h-4" />
                                        <Mail className="w-4 h-4" />
                                    </div>
                                    <span className="text-xs font-bold">Both</span>
                                </button>
                            </div>

                            {/* SAFE MODE TOGGLE */}
                            {(selectedChannel === 'SMS' || selectedChannel === 'BOTH') && (
                                <div className="mb-6 bg-yellow-50 p-3 rounded-xl border border-yellow-200 flex items-start gap-3 animate-fade-in">
                                    <AlertCircle className="w-5 h-5 text-yellow-600 shrink-0 mt-0.5" />
                                    <div className="flex-1">
                                        <div className="flex justify-between items-center mb-1">
                                            <label className="text-sm font-bold text-yellow-900 cursor-pointer select-none" htmlFor="safeMode">
                                                Safe Mode (SMS)
                                            </label>
                                            <input 
                                                id="safeMode"
                                                type="checkbox" 
                                                checked={useSafeMode}
                                                onChange={(e) => setUseSafeMode(e.target.checked)}
                                                className="accent-yellow-600 w-4 h-4"
                                            />
                                        </div>
                                        <p className="text-xs text-yellow-700 leading-tight">
                                            {useSafeMode 
                                                ? "Sends SMS slowly (~2 mins each) to prevent SIM blocking." 
                                                : "WARNING: Fast SMS sending may cause your SIM to be blocked."}
                                        </p>
                                    </div>
                                </div>
                            )}

                            {estMinutes > 0 && (
                                <p className="text-center text-xs font-bold text-gray-400 mb-4 flex items-center justify-center gap-1">
                                    <Clock className="w-3 h-3" />
                                    Est. Completion: ~{estMinutes} minutes
                                </p>
                            )}

                            <div className="flex gap-3">
                                <Button variant="ghost" onClick={() => setBroadcastStep('CHOICE')} className="flex-1">Back</Button>
                                <Button 
                                    className="flex-1 bg-green-600 hover:bg-green-700 shadow-green-200 text-white" 
                                    onClick={initiateBroadcast}
                                    disabled={selectedClientIds.length === 0}
                                >
                                    Start Broadcast
                                </Button>
                            </div>
                        </div>
                    )}

                </Dialog.Panel>
            </div>
       </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Promo?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>?
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Discounts;

import React, { useState, useMemo } from 'react';
import { Percent, Trash2, Tag, Calendar, Plus, MessageSquare, Search, CheckCircle, Smartphone, Users, Mail, Send, AlertCircle, Check, Clock, ArrowRight } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { useBroadcast, BroadcastChannel } from '../context/BroadcastContext';
import { Discount, DiscountTrigger, Client } from '../types';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';

const Discounts: React.FC = () => {
  const { discounts, addDiscount, toggleDiscount, deleteDiscount, products, clients, storeSettings } = useStore();
  const { startBroadcast, isSending } = useBroadcast();

  // State for Creating/Editing Discount
  const [activeTab, setActiveTab] = useState<'LIST' | 'CREATE'>('LIST');
  const [formData, setFormData] = useState<Partial<Discount>>({
    name: '', type: 'PERCENTAGE', value: 0, 
    triggerType: 'MANUAL', triggerValue: '', 
    isPermanent: true, startDate: '', endDate: ''
  });

  // State for Broadcasting Modal
  const [broadcastModalOpen, setBroadcastModalOpen] = useState(false);
  const [createdDiscount, setCreatedDiscount] = useState<Discount | null>(null);

  // New 3-Step Flow: CHOICE -> SELECT_CLIENTS (Optional) -> CONFIGURE
  const [broadcastStep, setBroadcastStep] = useState<'CHOICE' | 'SELECT_CLIENTS' | 'CONFIGURE'>('CHOICE');

  // Data for Broadcast
  const [selectedClientIds, setSelectedClientIds] = useState<string[]>([]);
  const [clientSearch, setClientSearch] = useState('');
  const [selectedChannel, setSelectedChannel] = useState<BroadcastChannel>('BOTH');

  // SMS Safety Settings - DEFAULT TRUE
  const [useSafeMode, setUseSafeMode] = useState(true);

  // Constants
  const MAX_BATCH_SIZE = 30; 

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Filter products for dropdown
  const productOptions = useMemo(() => products.map(p => ({ id: p.id, name: p.name })), [products]);

  // Filter clients for broadcast (Only show those with contact info)
  const availableClients = useMemo(() => {
      return clients.filter(c => c.contactNumber || c.email);
  }, [clients]);

  // Filter for search in "Select Specific" view
  const filteredClientsForSelection = useMemo(() => {
      return availableClients.filter(c => 
          c.name.toLowerCase().includes(clientSearch.toLowerCase()) ||
          (c.contactNumber && c.contactNumber.includes(clientSearch))
      );
  }, [availableClients, clientSearch]);

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.value) return;

    const newDiscount: Discount = {
      id: Date.now().toString(),
      name: formData.name,
      type: formData.type || 'PERCENTAGE',
      value: Number(formData.value),
      active: true,
      triggerType: formData.triggerType || 'MANUAL',
      triggerValue: formData.triggerValue,
      isPermanent: formData.isPermanent ?? true,
      startDate: formData.startDate,
      endDate: formData.endDate
    };

    addDiscount(newDiscount);

    // Reset Form
    setFormData({
        name: '', type: 'PERCENTAGE', value: 0, 
        triggerType: 'MANUAL', triggerValue: '', 
        isPermanent: true, startDate: '', endDate: ''
    });
    setActiveTab('LIST');

    // Open Broadcast Modal
    handleBroadcastClick(newDiscount);
  };

  const handleDeleteClick = (discount: Discount) => {
      setDeleteConfirmation({ isOpen: true, id: discount.id, name: discount.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteDiscount(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  // --- BROADCAST LOGIC ---

  const handleBroadcastClick = (discount: Discount) => {
      if (isSending) {
          alert("A broadcast is currently in progress. Please wait for it to finish.");
          return;
      }
      setCreatedDiscount(discount);
      setSelectedClientIds([]); // Reset selection
      setClientSearch('');
      setSelectedChannel('BOTH'); // Default
      setBroadcastStep('CHOICE');
      setBroadcastModalOpen(true);
  };

  // Step 1 Actions
  const handleSelectEveryone = () => {
      // Select All Available
      setSelectedClientIds(availableClients.map(c => c.id));
      setBroadcastStep('CONFIGURE');
  };

  const handleSelectSpecific = () => {
      setSelectedClientIds([]);
      setBroadcastStep('SELECT_CLIENTS');
  };

  // Step 2 Actions
  const handleSelectAllFiltered = () => {
      // If none selected, select up to MAX_BATCH_SIZE filtered items
      if (selectedClientIds.length === 0) {
          const toSelect = filteredClientsForSelection.slice(0, MAX_BATCH_SIZE).map(c => c.id);
          setSelectedClientIds(toSelect);
      } else {
          // Deselect All
          setSelectedClientIds([]);
      }
  };

  const handleToggleClient = (id: string) => {
      if (selectedClientIds.includes(id)) {
          setSelectedClientIds(prev => prev.filter(cid => cid !== id));
      } else {
          // Strict Limit Check
          if (selectedClientIds.length >= MAX_BATCH_SIZE) return;
          setSelectedClientIds(prev => [...prev, id]);
      }
  };

  const handleProceedToConfigure = () => {
      setBroadcastStep('CONFIGURE');
  };

  // Template Replacement Logic
  const replacePromoVariables = (template: string, discount: Discount) => {
      let rules = "";
      if (discount.triggerType === 'MIN_SPEND') rules = `Min spend: ₱${discount.triggerValue}.`;
      else if (discount.triggerType === 'ITEM_COUNT') rules = `Buy ${discount.triggerValue} items.`;

      const discountVal = discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`;

      const endDate = !discount.isPermanent && discount.endDate 
          ? new Date(discount.endDate).toLocaleDateString() 
          : "Limited time only";

      const data: Record<string, string> = {
          promoName: discount.name,
          discountValue: discountVal,
          rules: rules,
          endDate: endDate,
          shopName: storeSettings.name,
          address: storeSettings.address
      };

      let result = template;
      for (const key in data) {
          result = result.replace(new RegExp(`{${key}}`, 'g'), data[key]);
      }
      return result;
  };

  // Final Action
  const initiateBroadcast = () => {
      // Filter the actual client objects based on IDs
      const recipients = availableClients.filter(c => selectedClientIds.includes(c.id));

      if (recipients.length === 0 || !createdDiscount) return;

      // Prepare Messages
      const smsMsg = replacePromoVariables(storeSettings.smsTemplatePromo || "Promo: {promoName}", createdDiscount);
      const emailSubject = replacePromoVariables(storeSettings.emailSubjectPromo || "Special Promo", createdDiscount);
      const emailBody = replacePromoVariables(storeSettings.emailBodyPromo || "Check out {promoName}", createdDiscount);

      // Start Global Background Process with Channel Preference
      startBroadcast(recipients, smsMsg, emailSubject, emailBody, useSafeMode, selectedChannel);

      // Close Modal Immediately
      setBroadcastModalOpen(false);
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:ring-2 focus:ring-black focus:outline-none placeholder-zinc-400 text-sm font-medium";
  const labelClass = "text-xs font-bold text-gray-500 uppercase mb-1 block";

  // Calculate estimated time for display in the modal
  const estMinutes = useMemo(() => {
      const count = selectedClientIds.length;
      if (count <= 1) return 0;

      // If Channel is EMAIL ONLY, we assume it's fast regardless of safe mode (BroadcastContext handles this logic too usually, but for ETA display let's mirror it)
      // Actually BroadcastContext logic forces fast delay if safe mode is off OR if SMS wasn't sent.
      // So if channel === 'EMAIL', delay is 5s. If 'SMS'/'BOTH' and SafeMode, delay is 125s.

      const isSmsInvolved = selectedChannel === 'SMS' || selectedChannel === 'BOTH';
      const delay = (isSmsInvolved && useSafeMode) ? 125 : 5;

      const seconds = (count - 1) * delay;
      return Math.ceil(seconds / 60);
  }, [selectedClientIds.length, useSafeMode, selectedChannel]);

  return (
    <div className="space-y-6 h-[calc(100vh-100px)] flex flex-col">

       {/* Header */}
       <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Percent className="w-6 h-6" /> Discounts & Promos
            </h2>
            <p className="text-sm text-gray-500">Manage sales rules and blast notifications.</p>
          </div>
          <div className="flex bg-zinc-100 p-1 rounded-xl">
              <button 
                onClick={() => setActiveTab('LIST')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'LIST' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
              >
                  Active Promos
              </button>
              <button 
                onClick={() => setActiveTab('CREATE')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'CREATE' ? 'bg-black text-white shadow-md' : 'text-gray-500 hover:text-black'}`}
              >
                  <Plus className="w-4 h-4" /> Create New
              </button>
          </div>
       </div>

       {/* CREATE FORM */}
       {activeTab === 'CREATE' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto animate-fade-in">
               <form onSubmit={handleCreateSubmit} className="max-w-2xl mx-auto space-y-8">

                   {/* 1. Basic Info */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">1. Promo Details</h3>
                       <div>
                           <label className={labelClass}>Promo Name</label>
                           <input 
                                required
                                type="text" 
                                placeholder="e.g. Summer Sale, Loyal Customer" 
                                className={inputClass}
                                value={formData.name}
                                onChange={e => setFormData({...formData, name: e.target.value})}
                           />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                           <div>
                               <label className={labelClass}>Discount Type</label>
                               <select 
                                    className={inputClass}
                                    value={formData.type}
                                    onChange={e => setFormData({...formData, type: e.target.value as 'PERCENTAGE' | 'FIXED'})}
                               >
                                   <option value="PERCENTAGE">Percentage (%)</option>
                                   <option value="FIXED">Fixed Amount (₱)</option>
                               </select>
                           </div>
                           <div>
                               <label className={labelClass}>Value</label>
                               <input 
                                    required
                                    type="number" 
                                    placeholder="e.g. 10 or 50" 
                                    className={inputClass}
                                    value={formData.value || ''}
                                    onChange={e => setFormData({...formData, value: Number(e.target.value)})}
                               />
                           </div>
                       </div>
                   </div>

                   {/* 2. Triggers */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">2. Rules & Triggers</h3>
                       <div>
                           <label className={labelClass}>Trigger Condition</label>
                           <select 
                                className={inputClass}
                                value={formData.triggerType}
                                onChange={e => setFormData({...formData, triggerType: e.target.value as DiscountTrigger, triggerValue: ''})}
                           >
                               <option value="MANUAL">Manual Selection (Always Available)</option>
                               <option value="MIN_SPEND">Minimum Spend Amount</option>
                               <option value="ITEM_COUNT">Minimum Item Quantity</option>
                               <option value="SPECIFIC_PRODUCT">Buying a Specific Product</option>
                           </select>
                       </div>

                       {formData.triggerType !== 'MANUAL' && (
                           <div className="animate-fade-in">
                               <label className={labelClass}>
                                   {formData.triggerType === 'MIN_SPEND' ? 'Minimum Amount (₱)' : 
                                    formData.triggerType === 'ITEM_COUNT' ? 'Minimum Quantity' : 
                                    'Select Product'}
                               </label>

                               {formData.triggerType === 'SPECIFIC_PRODUCT' ? (
                                   <select 
                                        className={inputClass}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   >
                                       <option value="">-- Choose Product --</option>
                                       {productOptions.map(p => (
                                           <option key={p.id} value={p.id}>{p.name}</option>
                                       ))}
                                   </select>
                               ) : (
                                   <input 
                                        type="number"
                                        className={inputClass}
                                        placeholder={formData.triggerType === 'MIN_SPEND' ? '500' : '3'}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   />
                               )}
                           </div>
                       )}
                   </div>

                   {/* 3. Duration */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">3. Duration</h3>
                       <div className="flex items-center gap-4">
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: true})}
                                    className="accent-black w-4 h-4"
                               />
                               <span className="text-sm font-bold">Permanent</span>
                           </label>
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={!formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: false})}
                                    className="accent-black w-4 h-4"
                               />
                               <span className="text-sm font-bold">Set Date Range</span>
                           </label>
                       </div>

                       {!formData.isPermanent && (
                           <div className="grid grid-cols-2 gap-4 animate-fade-in">
                               <div>
                                   <label className={labelClass}>Start Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.startDate}
                                        onChange={e => setFormData({...formData, startDate: e.target.value})}
                                   />
                               </div>
                               <div>
                                   <label className={labelClass}>End Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.endDate}
                                        onChange={e => setFormData({...formData, endDate: e.target.value})}
                                   />
                               </div>
                           </div>
                       )}
                   </div>

                   <div className="pt-4 flex gap-3">
                       <Button type="button" variant="ghost" className="flex-1" onClick={() => setActiveTab('LIST')}>Cancel</Button>
                       <Button type="submit" className="flex-1 bg-black text-white shadow-lg">Save & Notify</Button>
                   </div>
               </form>
           </div>
       )}

       {/* LIST VIEW */}
       {activeTab === 'LIST' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto">
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                   {discounts.map(discount => (
                       <div key={discount.id} className="border border-zinc-200 rounded-2xl p-5 flex flex-col justify-between hover:shadow-md transition-shadow relative overflow-hidden group">
                           {/* Status Badge */}
                           <div className="absolute top-4 right-4">
                               <button 
                                    onClick={() => toggleDiscount(discount.id)}
                                    className={`text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${discount.active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}
                               >
                                   {discount.active ? 'Active' : 'Inactive'}
                               </button>
                           </div>

                           <div>
                               <h3 className="font-bold text-lg text-zinc-900 truncate pr-16">{discount.name}</h3>
                               <p className="text-2xl font-bold text-black mt-1">
                                   {discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`}
                                </p>

                               <div className="mt-4 space-y-2">
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Tag className="w-3 h-3" />
                                       <span>
                                           {discount.triggerType === 'MANUAL' && "Manual Apply"}
                                           {discount.triggerType === 'MIN_SPEND' && `Min Spend: ₱${discount.triggerValue}`}
                                           {discount.triggerType === 'ITEM_COUNT' && `Min Items: ${discount.triggerValue}`}
                                           {discount.triggerType === 'SPECIFIC_PRODUCT' && "Specific Product"}
                                       </span>
                                   </div>
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Calendar className="w-3 h-3" />
                                       <span>
                                           {discount.isPermanent ? "Permanent Validity" : 
                                            `${new Date(discount.startDate!).toLocaleDateString()} - ${new Date(discount.endDate!).toLocaleDateString()}`}
                                       </span>
                                   </div>
                               </div>
                           </div>

                           <div className="mt-4 pt-4 border-t border-zinc-100 flex justify-end">
                               <button 
                                    onClick={() => handleBroadcastClick(discount)}
                                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors mr-2"
                                    title="Send/Remind"
                               >
                                   <Send className="w-4 h-4" />
                               </button>
                               <button 
                                    onClick={() => handleDeleteClick(discount)}
                                    className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Delete"
                               >
                                   <Trash2 className="w-4 h-4" />
                                </button>
                           </div>
                       </div>
                   ))}
                   {discounts.length === 0 && (
                       <div className="col-span-full py-20 text-center text-gray-400 flex flex-col items-center justify-center">
                           <Tag className="w-12 h-12 opacity-20 mb-2" />
                           <p>No active promotions.</p>
                       </div>
                   )}
               </div>
           </div>
       )}

       {/* BROADCAST MODAL */}
       <Dialog open={broadcastModalOpen} onClose={() => setBroadcastModalOpen(false)} className="relative z-50">
            <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
            <div className="fixed inset-0 flex items-center justify-center p-4">
                <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl relative flex flex-col max-h-[90vh]">

                    {/* STEP 1: CHOICE */}
                    {broadcastStep === 'CHOICE' && (
                        <div className="text-center">
                            <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4 text-blue-600">
                                <MessageSquare className="w-8 h-8" />
                            </div>
                            <h2 className="text-2xl font-bold text-zinc-900">Broadcast Promo</h2>
                            <p className="text-gray-500 mt-2 mb-6">
                                <strong>{createdDiscount?.name}</strong> is ready. Who would you like to notify?
                            </p>

                            <div className="space-y-3">
                                {/* Option A: Send to Everyone */}
                                <button 
                                    onClick={handleSelectEveryone}
                                    className="w-full p-4 rounded-2xl border-2 border-zinc-100 hover:border-blue-500 hover:bg-blue-50 transition-all flex items-center gap-4 group text-left"
                                >
                                    <div className="w-12 h-12 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                                        <Users className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-zinc-900">Send to Everyone</h3>
                                        <p className="text-xs text-gray-500">Quickly notify all {availableClients.length} clients.</p>
                                    </div>
                                    <ArrowRight className="w-5 h-5 text-gray-300 ml-auto group-hover:text-blue-500" />
                                </button>

                                {/* Option B: Select Specific */}
                                <button 
                                    onClick={handleSelectSpecific}
                                    className="w-full p-4 rounded-2xl border-2 border-zinc-100 hover:border-purple-500 hover:bg-purple-50 transition-all flex items-center gap-4 group text-left"
                                >
                                    <div className="w-12 h-12 rounded-full bg-purple-100 text-purple-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                                        <CheckCircle className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-zinc-900">Select Specific Clients</h3>
                                        <p className="text-xs text-gray-500">Choose from the list manually.</p>
                                    </div>
                                    <ArrowRight className="w-5 h-5 text-gray-300 ml-auto group-hover:text-purple-500" />
                                </button>

                                {/* Option C: Skip */}
                                <button 
                                    onClick={() => setBroadcastModalOpen(false)}
                                    className="w-full p-3 rounded-xl text-sm font-bold text-gray-400 hover:text-gray-600 hover:bg-zinc-50"
                                >
                                    Cancel
                                </button>
                            </div>
                        </div>
                    )}

                    {/* STEP 2: SELECT CLIENTS (Optional) */}
                    {broadcastStep === 'SELECT_CLIENTS' && (
                        <div className="flex flex-col h-[500px]">
                            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                                <Smartphone className="w-5 h-5" /> Select Recipients
                            </h2>

                            <div className="mb-4 flex gap-2">
                                <div className="relative flex-1">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                    <input 
                                        type="text" 
                                        className="w-full pl-9 pr-3 py-2 border border-zinc-200 rounded-xl text-sm focus:ring-1 focus:ring-black outline-none bg-white text-zinc-900 placeholder-zinc-400"
                                        placeholder="Search name or number..."
                                        value={clientSearch}
                                        onChange={e => setClientSearch(e.target.value)}
                                    />
                                </div>
                                <Button size="sm" variant="secondary" onClick={handleSelectAllFiltered}>
                                    {selectedClientIds.length > 0 ? 'Deselect All' : `Select Top ${MAX_BATCH_SIZE}`}
                                </Button>
                            </div>

                            {/* Warning Limit Banner */}
                            {selectedClientIds.length >= MAX_BATCH_SIZE ? (
                                <div className="mb-2 bg-red-50 text-red-700 text-xs px-3 py-2 rounded-lg border border-red-100 flex items-center gap-2 font-bold">
                                    <AlertCircle className="w-4 h-4 shrink-0" />
                                    <span>Batch Limit Reached ({MAX_BATCH_SIZE}/{MAX_BATCH_SIZE})</span>
                                </div>
                            ) : (
                                <div className="mb-2 bg-purple-50 text-purple-700 text-xs px-3 py-2 rounded-lg border border-purple-100 flex items-center gap-2 font-bold justify-between">
                                    <span>Selected: {selectedClientIds.length}</span>
                                    <span>Max: {MAX_BATCH_SIZE}</span>
                                </div>
                            )}

                            <div className="flex-1 overflow-y-auto border border-zinc-100 rounded-xl bg-zinc-50 p-2 space-y-1">
                                {filteredClientsForSelection.map(client => {
                                    const isSelected = selectedClientIds.includes(client.id);
                                    // Disable if not selected AND limit reached
                                    const isDisabled = !isSelected && selectedClientIds.length >= MAX_BATCH_SIZE;

                                    return (
                                    <label 
                                        key={client.id} 
                                        className={`flex items-center gap-3 p-3 rounded-lg border transition-all ${
                                            isDisabled ? 'opacity-50 cursor-not-allowed bg-zinc-100 border-zinc-200' 
                                            : isSelected ? 'bg-purple-50 border-purple-200 cursor-pointer' 
                                            : 'bg-white border-zinc-100 hover:border-purple-300 cursor-pointer'
                                        }`}
                                    >
                                        <div className={`w-5 h-5 rounded border flex items-center justify-center shrink-0 ${isSelected ? 'bg-purple-600 border-purple-600' : 'bg-white border-gray-300'}`}>
                                            {isSelected && <Check className="w-3 h-3 text-white" />}
                                        </div>
                                        <input 
                                            type="checkbox" 
                                            className="hidden"
                                            checked={isSelected}
                                            disabled={isDisabled}
                                            onChange={() => handleToggleClient(client.id)}
                                        />
                                        <div className="flex-1 min-w-0">
                                            <p className="font-bold text-sm text-zinc-900 truncate">{client.name}</p>
                                            <div className="flex gap-2 text-[10px] text-gray-500 mt-0.5">
                                                {client.contactNumber && <span className="flex items-center gap-1 truncate"><Smartphone className="w-3 h-3 shrink-0"/> {client.contactNumber}</span>}
                                                {client.email && <span className="flex items-center gap-1 truncate"><Mail className="w-3 h-3 shrink-0"/> {client.email}</span>}
                                            </div>
                                        </div>
                                    </label>
                                    );
                                })}
                                {filteredClientsForSelection.length === 0 && <p className="text-center text-gray-400 py-4 text-xs">No clients found.</p>}
                            </div>

                            <div className="mt-4 flex gap-3">
                                <Button variant="ghost" onClick={() => setBroadcastStep('CHOICE')} className="flex-1">Back</Button>
                                <Button 
                                    className="flex-1 bg-black hover:bg-zinc-800"
                                    disabled={selectedClientIds.length === 0}
                                    onClick={handleProceedToConfigure}
                                >
                                    Configure Send ({selectedClientIds.length})
                                </Button>
                            </div>
                        </div>
                    )}

                    {/* STEP 3: CONFIGURE */}
                    {broadcastStep === 'CONFIGURE' && (
                        <div className="flex flex-col">
                            <h2 className="text-xl font-bold mb-4 text-center">Configure Broadcast</h2>

                            <div className="bg-zinc-50 border border-zinc-100 rounded-xl p-4 mb-6 text-center">
                                <p className="text-xs text-gray-500 uppercase font-bold mb-1">Recipients</p>
                                <p className="text-3xl font-bold text-zinc-900">{selectedClientIds.length}</p>
                                <p className="text-xs text-gray-400 mt-1">Clients selected</p>
                            </div>

                            <p className="text-sm font-bold text-zinc-700 mb-2">Select Channel</p>
                            <div className="grid grid-cols-3 gap-2 mb-6">
                                <button 
                                    onClick={() => setSelectedChannel('SMS')}
                                    className={`p-3 rounded-xl border-2 flex flex-col items-center gap-1 transition-all ${
                                        selectedChannel === 'SMS' 
                                        ? 'border-blue-600 bg-blue-50 text-blue-700' 
                                        : 'border-zinc-100 bg-white text-gray-400 hover:border-zinc-300'
                                    }`}
                                >
                                    <Smartphone className="w-5 h-5" />
                                    <span className="text-xs font-bold">SMS Only</span>
                                </button>
                                <button 
                                    onClick={() => setSelectedChannel('EMAIL')}
                                    className={`p-3 rounded-xl border-2 flex flex-col items-center gap-1 transition-all ${
                                        selectedChannel === 'EMAIL' 
                                        ? 'border-orange-500 bg-orange-50 text-orange-700' 
                                        : 'border-zinc-100 bg-white text-gray-400 hover:border-zinc-300'
                                    }`}
                                >
                                    <Mail className="w-5 h-5" />
                                    <span className="text-xs font-bold">Email Only</span>
                                </button>
                                <button 
                                    onClick={() => setSelectedChannel('BOTH')}
                                    className={`p-3 rounded-xl border-2 flex flex-col items-center gap-1 transition-all ${
                                        selectedChannel === 'BOTH' 
                                        ? 'border-black bg-zinc-900 text-white' 
                                        : 'border-zinc-100 bg-white text-gray-400 hover:border-zinc-300'
                                    }`}
                                >
                                    <div className="flex gap-1">
                                        <Smartphone className="w-4 h-4" />
                                        <Mail className="w-4 h-4" />
                                    </div>
                                    <span className="text-xs font-bold">Both</span>
                                </button>
                            </div>

                            {/* SAFE MODE TOGGLE */}
                            {(selectedChannel === 'SMS' || selectedChannel === 'BOTH') && (
                                <div className="mb-6 bg-yellow-50 p-3 rounded-xl border border-yellow-200 flex items-start gap-3 animate-fade-in">
                                    <AlertCircle className="w-5 h-5 text-yellow-600 shrink-0 mt-0.5" />
                                    <div className="flex-1">
                                        <div className="flex justify-between items-center mb-1">
                                            <label className="text-sm font-bold text-yellow-900 cursor-pointer select-none" htmlFor="safeMode">
                                                Safe Mode (SMS)
                                            </label>
                                            <input 
                                                id="safeMode"
                                                type="checkbox" 
                                                checked={useSafeMode}
                                                onChange={(e) => setUseSafeMode(e.target.checked)}
                                                className="accent-yellow-600 w-4 h-4"
                                            />
                                        </div>
                                        <p className="text-xs text-yellow-700 leading-tight">
                                            {useSafeMode 
                                                ? "Sends SMS slowly (~2 mins each) to prevent SIM blocking." 
                                                : "WARNING: Fast SMS sending may cause your SIM to be blocked."}
                                        </p>
                                    </div>
                                </div>
                            )}

                            {estMinutes > 0 && (
                                <p className="text-center text-xs font-bold text-gray-400 mb-4 flex items-center justify-center gap-1">
                                    <Clock className="w-3 h-3" />
                                    Est. Completion: ~{estMinutes} minutes
                                </p>
                            )}

                            <div className="flex gap-3">
                                <Button variant="ghost" onClick={() => setBroadcastStep('CHOICE')} className="flex-1">Back</Button>
                                <Button 
                                    className="flex-1 bg-green-600 hover:bg-green-700 shadow-green-200 text-white" 
                                    onClick={initiateBroadcast}
                                    disabled={selectedClientIds.length === 0}
                                >
                                    Start Broadcast
                                </Button>
                            </div>
                        </div>
                    )}

                </Dialog.Panel>
            </div>
       </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Promo?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>?
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Discounts;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext';
import { GroomingAppointment, Role, Client, Pet } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User, Scissors, History, Clock, CheckCircle, ArrowRight, Pencil, Trash2, Smartphone, Scale, Palette, Check, MessageSquare, Mail, ChevronUp, ChevronDown, Search, X } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import { getNotificationContent, sendSMS, sendEmail } from '../services/notifications';

type GroomingTab = 'UPCOMING' | 'WAITING' | 'ONGOING' | 'COMPLETED';

// Smart Search Helper: Removes non-alphanumeric chars for loose matching
const normalizeText = (text: string) => text.toLowerCase().replace(/[^a-z0-9]/g, '');

const Grooming: React.FC = () => {
  const { appointments, addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, products, users, clients, storeSettings, addLog, checkAndIncrementSms } = useStore();

  const today = new Date().toISOString().split('T')[0];

  // UI States
  const [activeTab, setActiveTab] = useState<GroomingTab>('WAITING');
  const [filterDate, setFilterDate] = useState(today);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 12;
  const scrollRef = useRef<HTMLDivElement>(null);

  // Completion Modal State
  const [completionModal, setCompletionModal] = useState<{isOpen: boolean, apt: GroomingAppointment | null}>({
      isOpen: false, apt: null
  });
  const [isCompleting, setIsCompleting] = useState(false);

  // Delete Confirmation State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, petName: string}>({
    isOpen: false, id: null, petName: ''
  });

  // Autocomplete & Pet Logic States
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [showPetSuggestions, setShowPetSuggestions] = useState(false);

  // Service Autocomplete State
  const [serviceSearch, setServiceSearch] = useState('');
  const [showServiceSuggestions, setShowServiceSuggestions] = useState(false);

  const [filteredClients, setFilteredClients] = useState<Client[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const dropdownRef = useRef<HTMLDivElement>(null);
  const petDropdownRef = useRef<HTMLDivElement>(null);
  const serviceDropdownRef = useRef<HTMLDivElement>(null);

  // Form Data
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<GroomingAppointment>>({
    petName: '', petBreed: '', petColor: '', weightSize: '',
    ownerName: '', contactNumber: '', email: '',
    serviceId: '', hairCut: '',
    date: today, time: '', status: 'SCHEDULED', groomerId: ''
  });

  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');
  const groomingServices = products.filter(p => p.isService);

  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
              setShowSuggestions(false);
          }
          if (petDropdownRef.current && !petDropdownRef.current.contains(event.target as Node)) {
              setShowPetSuggestions(false);
          }
          if (serviceDropdownRef.current && !serviceDropdownRef.current.contains(event.target as Node)) {
              setShowServiceSuggestions(false);
          }
      };
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleOwnerNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setFormData(prev => ({ ...prev, ownerName: val }));

      if (selectedClient && selectedClient.name !== val) {
          setSelectedClient(null);
      }

      if (val.length > 0) {
          const normalizedSearch = normalizeText(val);
          const matches = clients.filter(c => 
              normalizeText(c.name).includes(normalizedSearch) || 
              (c.contactNumber && c.contactNumber.replace(/\D/g,'').includes(normalizedSearch))
          );
          setFilteredClients(matches.slice(0, 5));
          setShowSuggestions(true);
      } else {
          setShowSuggestions(false);
      }
  };

  const selectClient = (client: Client) => {
      setFormData(prev => ({
          ...prev,
          ownerName: client.name,
          contactNumber: client.contactNumber,
          email: client.email || '',
      }));
      setSelectedClient(client);
      setShowSuggestions(false);
  };

  const handlePetNameFocus = () => {
      if (selectedClient && selectedClient.pets && selectedClient.pets.length > 0) {
          setShowPetSuggestions(true);
      }
  };

  const selectPet = (pet: Pet) => {
      setFormData(prev => ({
          ...prev,
          petName: pet.name,
          petBreed: pet.breed || '',
          petColor: pet.color || '',
          weightSize: pet.weightSize || ''
      }));
      setShowPetSuggestions(false);
  };

  const formatTime = (time: string) => {
    if (!time) return '';
    const [hours, minutes] = time.split(':');
    const h = parseInt(hours, 10);
    const ampm = h >= 12 ? 'PM' : 'AM';
    const h12 = h % 12 || 12;
    return `${h12}:${minutes} ${ampm}`;
  };

  const filteredAppointments = useMemo(() => {
    return appointments.filter(apt => {
        if (activeTab === 'UPCOMING') return apt.status === 'SCHEDULED' && apt.date > today;
        if (activeTab === 'WAITING') return apt.status === 'SCHEDULED' && apt.date === today;
        if (activeTab === 'ONGOING') return apt.status === 'ONGOING';
        if (activeTab === 'COMPLETED') return apt.status === 'COMPLETED' && apt.date === filterDate;
        return false;
    }).sort((a, b) => {
        if (a.date !== b.date) return a.date.localeCompare(b.date);
        return a.time.localeCompare(b.time);
    });
  }, [appointments, activeTab, filterDate, today]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredAppointments.length / itemsPerPage);
  const paginatedAppointments = useMemo(() => {
      const start = (currentPage - 1) * itemsPerPage;
      return filteredAppointments.slice(start, start + itemsPerPage);
  }, [filteredAppointments, currentPage]);

  useEffect(() => {
      setCurrentPage(1);
  }, [activeTab, filterDate]);

  const handlePageChange = (newPage: number) => {
      setCurrentPage(newPage);
      if (scrollRef.current) {
          scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  const openAddModal = () => {
    setEditingId(null);
    setSelectedClient(null);
    setServiceSearch('');
    setFormData({
      petName: '', petBreed: '', petColor: '', weightSize: '',
      ownerName: '', contactNumber: '', email: '',
      serviceId: '', hairCut: '',
      date: today, time: '', status: 'SCHEDULED', groomerId: ''
    });
    setIsModalOpen(true);
  };

  const openEditModal = (apt: GroomingAppointment) => {
    setEditingId(apt.id);
    setFormData({ ...apt });
    const client = clients.find(c => c.name === apt.ownerName);
    if(client) setSelectedClient(client);

    // Set service search text
    const service = products.find(p => p.id === apt.serviceId);
    setServiceSearch(service ? service.name : '');

    setIsModalOpen(true);
  };

  const handleCancelClick = (id: string, name: string) => {
    setDeleteConfirmation({ isOpen: true, id, petName: name });
  };

  const confirmDelete = () => {
    if (deleteConfirmation.id) {
        deleteAppointment(deleteConfirmation.id);
        setDeleteConfirmation({ isOpen: false, id: null, petName: '' });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      const updatedApt: GroomingAppointment = { ...formData as GroomingAppointment, id: editingId };
      updateAppointment(updatedApt);
    } else {
      const apt: GroomingAppointment = {
        id: Date.now().toString(),
        petName: formData.petName!,
        petBreed: formData.petBreed,
        petColor: formData.petColor,
        weightSize: formData.weightSize,
        ownerName: formData.ownerName!,
        contactNumber: formData.contactNumber,
        email: formData.email,
        serviceId: formData.serviceId!,
        hairCut: formData.hairCut,
        date: formData.date!,
        time: formData.time!,
        status: 'SCHEDULED',
        groomerId: formData.groomerId!
      };
      addAppointment(apt);
    }
    setIsModalOpen(false);
  };

  // --- OPEN COMPLETION MODAL ---
  const handleOpenCompletionModal = (apt: GroomingAppointment) => {
      setCompletionModal({ isOpen: true, apt });
  };

  // --- FINALIZE COMPLETION ---
  const processCompletion = async (channel: 'SMS' | 'EMAIL' | 'BOTH' | 'NONE') => {
      const apt = completionModal.apt;
      if (!apt) return;

      setIsCompleting(true);

      // 1. Update DB Status
      updateAppointmentStatus(apt.id, 'COMPLETED');

      // 2. Prepare Data
      const service = products.find(p => p.id === apt.serviceId);
      const serviceName = service ? service.name : "Grooming Service";
      const price = service ? service.price : 0;
      const content = getNotificationContent(storeSettings, 'COMPLETED', apt, serviceName, price);

      // 3. Send SMS (If selected and valid)
      if ((channel === 'SMS' || channel === 'BOTH') && storeSettings.smsEnabled && apt.contactNumber) {
          if (checkAndIncrementSms()) {
              await sendSMS(storeSettings, [apt.contactNumber], content.sms);
          } else {
              alert("Hourly SMS limit reached. Notification skipped.");
          }
      }

      // 4. Send Email (If selected and valid)
      if ((channel === 'EMAIL' || channel === 'BOTH') && storeSettings.emailEnabled && apt.email) {
          await sendEmail(storeSettings, apt.email, content.emailSubject, content.emailBody, "Ready for Pickup!");
      }

      setIsCompleting(false);
      setCompletionModal({ isOpen: false, apt: null });
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium text-sm";
  const labelClass = "text-xs font-bold text-gray-500 uppercase";

  const getCount = (tab: GroomingTab) => {
      if (tab === 'UPCOMING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date > today).length;
      if (tab === 'WAITING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date === today).length;
      if (tab === 'ONGOING') return appointments.filter(a => a.status === 'ONGOING').length;
      if (tab === 'COMPLETED') return appointments.filter(a => a.status === 'COMPLETED' && a.date === filterDate).length;
      return 0;
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] gap-6 text-zinc-900">

       <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
         <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
             <div>
                <h1 className="text-xl font-bold text-zinc-900 flex items-center gap-2">
                    <Scissors className="w-6 h-6" /> Grooming Salon
                </h1>
                <p className="text-gray-500 text-sm">Manage appointments and workflow</p>
             </div>
             <Button onClick={openAddModal}>
                 <Plus className="w-4 h-4" /> Book Appointment
             </Button>
         </div>

         <div className="flex flex-col xl:flex-row gap-4 items-center justify-between">
            <div className="flex bg-zinc-100 p-1 rounded-xl w-full xl:w-auto overflow-x-auto no-scrollbar">
                <button onClick={() => setActiveTab('UPCOMING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'UPCOMING' ? 'bg-white text-purple-700 shadow-sm' : 'text-gray-500'}`}>
                    <Calendar className="w-4 h-4" /> Upcoming <span className="bg-purple-100 text-purple-700 px-1.5 rounded text-xs">{getCount('UPCOMING')}</span>
                </button>
                <button onClick={() => setActiveTab('WAITING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'WAITING' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-500'}`}>
                    <Clock className="w-4 h-4" /> Waiting <span className="bg-orange-100 text-orange-600 px-1.5 rounded text-xs">{getCount('WAITING')}</span>
                </button>
                <button onClick={() => setActiveTab('ONGOING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'ONGOING' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>
                    <Scissors className="w-4 h-4" /> Ongoing <span className="bg-blue-100 text-blue-600 px-1.5 rounded text-xs">{getCount('ONGOING')}</span>
                </button>
                <button onClick={() => setActiveTab('COMPLETED')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'COMPLETED' ? 'bg-white text-green-600 shadow-sm' : 'text-gray-500'}`}>
                    <CheckCircle className="w-4 h-4" /> Completed <span className="bg-green-100 text-green-600 px-1.5 rounded text-xs">{getCount('COMPLETED')}</span>
                </button>
            </div>

            {activeTab === 'COMPLETED' ? (
                <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-3 py-1 w-full md:w-auto animate-fade-in">
                    <span className="text-xs font-bold text-gray-400 uppercase mr-1">History Date:</span>
                    <input type="date" className="bg-transparent font-bold text-sm outline-none py-1.5 text-zinc-900" value={filterDate} onChange={(e) => setFilterDate(e.target.value)} />
                </div>
            ) : null}
         </div>
       </div>

       <div className="flex-1 overflow-auto" ref={scrollRef}>
           {paginatedAppointments.length === 0 ? (
               <div className="h-full flex flex-col items-center justify-center text-gray-400 bg-white rounded-3xl border border-dashed border-zinc-200">
                   <Dog className="w-16 h-16 mb-4 opacity-20" />
                   <p className="font-medium">No appointments found.</p>
               </div>
           ) : (
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 pb-4">
                   {paginatedAppointments.map(apt => {
                       const serviceName = groomingServices.find(s => s.id === apt.serviceId)?.name || 'Unknown Service';
                       return (
                           <div key={apt.id} className="bg-white p-5 rounded-3xl shadow-sm border border-zinc-100 flex flex-col relative overflow-hidden group hover:shadow-md transition-shadow">
                               <div className="flex justify-between items-start mb-3 relative z-10">
                                   <div className={`text-xs font-bold px-3 py-1 rounded-full border ${apt.date === today ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-white text-zinc-900 border-zinc-200'}`}>
                                       {apt.date === today ? 'TODAY' : new Date(apt.date).toLocaleDateString()} • {formatTime(apt.time)}
                                   </div>
                                   <div className="flex items-center gap-2">
                                     {apt.status === 'SCHEDULED' && (
                                       <div className="flex items-center bg-zinc-50 rounded-lg p-0.5 border border-zinc-100">
                                          <button onClick={() => openEditModal(apt)} className="p-1.5 text-gray-500 hover:text-black hover:bg-white rounded-md transition-all"><Pencil className="w-3.5 h-3.5" /></button>
                                          <div className="w-px h-3 bg-gray-200 mx-0.5"></div>
                                          <button onClick={() => handleCancelClick(apt.id, apt.petName)} className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-white rounded-md transition-all"><Trash2 className="w-3.5 h-3.5" /></button>
                                       </div>
                                     )}
                                     <span className={`text-xs font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${apt.status === 'SCHEDULED' ? 'bg-orange-100 text-orange-600' : apt.status === 'ONGOING' ? 'bg-blue-100 text-blue-600 animate-pulse' : 'bg-green-100 text-green-600'}`}>{apt.status}</span>
                                   </div>
                               </div>
                               <div className="mb-4 relative z-10">
                                   <h3 className="text-xl font-bold text-zinc-900 leading-tight flex items-center gap-2">{apt.petName} {apt.petBreed && <span className="text-sm font-normal text-gray-500 bg-zinc-50 px-2 py-0.5 rounded-md border border-zinc-100">{apt.petBreed}</span>}</h3>
                                   <p className="text-sm text-gray-500 flex items-center gap-1 font-medium mt-1"><User className="w-3 h-3"/> {apt.ownerName} {apt.contactNumber && <span className="text-gray-400">({apt.contactNumber})</span>}</p>
                                   {apt.hairCut && <div className="mt-2 text-xs bg-yellow-50 text-yellow-800 p-2 rounded-lg border border-yellow-100 italic"><span className="font-bold not-italic">✄ Style:</span> {apt.hairCut}</div>}
                               </div>
                               <div className="space-y-2 mb-6 relative z-10">
                                    <div className="flex justify-between items-center text-sm border-t border-zinc-100 pt-3"><span className="text-gray-400">Service</span><span className="font-bold text-zinc-800 text-right max-w-[60%] truncate">{serviceName}</span></div>
                                    <div className="flex justify-between items-center text-sm"><span className="text-gray-400">Groomer</span><span className="font-bold text-zinc-800">{apt.groomerId}</span></div>
                               </div>
                               <div className="mt-auto relative z-10">
                                   {apt.status === 'SCHEDULED' && (
                                       apt.date === today ? (
                                           <Button className="w-full bg-black hover:bg-zinc-800 flex justify-center items-center gap-2" onClick={() => updateAppointmentStatus(apt.id, 'ONGOING')}>Start Session <ArrowRight className="w-4 h-4" /></Button>
                                       ) : <div className="w-full text-center py-2 text-sm text-gray-400 font-medium bg-zinc-50 rounded-xl border border-zinc-100">Scheduled</div>
                                   )}
                                   {apt.status === 'ONGOING' && (
                                       <Button 
                                            className="w-full bg-green-600 hover:bg-green-700 text-white shadow-green-200" 
                                            onClick={() => handleOpenCompletionModal(apt)}
                                       >
                                           Complete Grooming
                                       </Button>
                                   )}
                                   {apt.status === 'COMPLETED' && <div className="w-full flex items-center justify-center gap-2 py-2 text-sm text-green-700 font-bold bg-green-50 rounded-xl border border-green-100"><CheckCircle className="w-4 h-4" /> Finished</div>}
                               </div>
                           </div>
                       );
                   })}
               </div>
           )}
       </div>

       {/* Pagination Footer */}
       {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-800">{Math.min(filteredAppointments.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(filteredAppointments.length, currentPage * itemsPerPage)}</span> of {filteredAppointments.length} records
              </div>
              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handlePageChange(Math.max(1, currentPage - 1))}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronUp className="w-4 h-4 -rotate-90" />
