                                   {apt.status === 'COMPLETED' && <div className="w-full flex items-center justify-center gap-2 py-2 text-sm text-green-700 font-bold bg-green-50 rounded-xl border border-green-100"><CheckCircle className="w-4 h-4" /> Finished</div>}
                               </div>
                           </div>
                       );
