import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, CartItem, Category, Transaction, StoreSettings, Discount, GroomingAppointment } from '../types';
import Button from '../components/ui/Button';
import { Search, ShoppingBag, Trash2, Plus, Minus, CreditCard, Bone, Dog, Printer, Check, X, Settings, ArrowRight, Scissors, DollarSign } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import ReceiptTemplate from '../components/ReceiptTemplate';
import { useNavigate } from 'react-router-dom';

// Helper for loose search matching
const normalizeText = (text: string) => text.toLowerCase().replace(/[^a-z0-9]/g, '');

// Reusable Cart UI Component
interface CartPanelProps {
    cart: CartItem[];
    updateQuantity: (id: string, delta: number) => void;
    removeFromCart: (id: string) => void;
    discounts: Discount[];
    selectedDiscountId: string;
    setSelectedDiscountId: (id: string) => void;
    subtotal: number;
    discountAmount: number;
    total: number;
    onCheckout: () => void;
    onClose?: () => void; // For mobile modal
}

const CartPanel: React.FC<CartPanelProps> = ({ 
    cart, updateQuantity, removeFromCart, discounts, selectedDiscountId, setSelectedDiscountId,
    subtotal, discountAmount, total, onCheckout, onClose
}) => {

    // Logic to check if discount is applicable
    const isDiscountValid = (d: Discount) => {
        if (!d.active) return false;

        // Date Check
        if (!d.isPermanent && d.startDate && d.endDate) {
            const now = new Date();
            const start = new Date(d.startDate);
            const end = new Date(d.endDate);
            // Include end date by setting it to end of day
            end.setHours(23, 59, 59, 999);
            if (now < start || now > end) return false;
        }

        // Trigger Checks
        if (d.triggerType === 'MIN_SPEND') {
            const min = Number(d.triggerValue);
            if (subtotal < min) return false;
        }

        if (d.triggerType === 'ITEM_COUNT') {
            const minCount = Number(d.triggerValue);
            const totalCount = cart.reduce((acc, item) => acc + item.quantity, 0);
            if (totalCount < minCount) return false;
        }

        if (d.triggerType === 'SPECIFIC_PRODUCT') {
            const hasProduct = cart.some(item => item.id === d.triggerValue);
            if (!hasProduct) return false;
        }

        return true;
    };

    return (
        <div className="flex flex-col h-full bg-white lg:rounded-3xl shadow-xl border border-zinc-100 overflow-hidden">
            <div className="p-5 border-b border-zinc-100 bg-zinc-50 lg:rounded-t-3xl flex justify-between items-center">
                <h2 className="font-bold text-lg flex items-center gap-2 text-zinc-900">
                    <ShoppingBag className="w-5 h-5" />
                    Current Order
                </h2>
                {onClose && (
                    <button onClick={onClose} className="lg:hidden p-2 text-gray-500 hover:bg-zinc-200 rounded-full">
                        <X className="w-5 h-5" />
                    </button>
                )}
            </div>

            <div className="flex-1 overflow-auto p-4 space-y-3">
                {cart.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-gray-400">
                        <ShoppingBag className="w-12 h-12 mb-2 opacity-20" />
                        <p>Cart is empty</p>
                    </div>
                ) : (
                    cart.map(item => {
                        const isMaxStock = !item.isService && item.quantity >= item.stock;
                        return (
                            <div key={item.id} className="flex items-center gap-3 bg-white p-3 rounded-2xl border border-zinc-100 shadow-sm">
                                <div className="flex-1">
                                    <div className="flex items-center gap-2">
                                        <p className="font-semibold text-sm text-zinc-900 line-clamp-1">{item.name}</p>
                                        {isMaxStock && <span className="text-[10px] font-bold bg-red-100 text-red-600 px-1.5 py-0.5 rounded">MAX</span>}
                                    </div>
                                    <p className="text-xs text-gray-500">₱{item.price} each</p>
                                </div>
                                <div className="flex items-center gap-1 bg-zinc-100 rounded-xl p-1">
                                    <button
                                        onClick={() => updateQuantity(item.id, -1)}
                                        className="w-8 h-8 flex items-center justify-center bg-white rounded-lg shadow-sm hover:bg-zinc-50 active:scale-95 transition-all text-zinc-900"
                                    >
                                        <Minus className="w-4 h-4" />
                                    </button>
                                    <span className="text-sm font-bold w-8 text-center text-zinc-900">{item.quantity}</span>
                                    <button
                                        onClick={() => updateQuantity(item.id, 1)}
                                        disabled={isMaxStock}
                                        className={`w-8 h-8 flex items-center justify-center bg-white rounded-lg shadow-sm transition-all text-zinc-900 ${isMaxStock ? 'opacity-50 cursor-not-allowed' : 'hover:bg-zinc-50 active:scale-95'
                                            }`}
                                    >
                                        <Plus className="w-4 h-4" />
                                    </button>
                                </div>
                                <button
                                    onClick={() => removeFromCart(item.id)}
                                    className="w-8 h-8 flex items-center justify-center text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        )
                    })
                )}
            </div>

            <div className="p-5 bg-zinc-900 text-white lg:rounded-b-3xl mt-auto shadow-inner">
                <div className="mb-4">
                    <label className="text-xs text-zinc-400 font-bold uppercase mb-1 block">Apply Discount</label>
                    <select
                        value={selectedDiscountId}
                        onChange={(e) => setSelectedDiscountId(e.target.value)}
                        className="w-full bg-zinc-800 border border-zinc-700 text-white rounded-lg p-2 text-sm focus:outline-none focus:ring-1 focus:ring-white"
                    >
                        <option value="">No Discount</option>
                        {discounts.map(d => {
                            const valid = isDiscountValid(d);
                            // Only show if active, regardless of validity (but show disabled state if invalid)
                            if (!d.active) return null;

                            return (
                                <option key={d.id} value={d.id} disabled={!valid}>
                                    {d.name} {valid ? `(${d.type === 'PERCENTAGE' ? d.value + '%' : '₱'+d.value})` : '(Criteria Not Met)'}
                                </option>
                            );
                        })}
                    </select>
                </div>

                <div className="space-y-2 text-sm mb-4 border-t border-zinc-800 pt-4">
                    <div className="flex justify-between text-gray-400"><span>Subtotal</span><span>₱{subtotal.toFixed(2)}</span></div>
                    <div className="flex justify-between text-gray-400"><span>Discount</span><span>-₱{discountAmount.toFixed(2)}</span></div>
                    <div className="flex justify-between text-white font-bold text-lg pt-2 border-t border-zinc-700">
                        <span>Total</span>
                        <span>₱{total.toFixed(2)}</span>
                    </div>
                </div>
                {/* FIXED: Changed to secondary variant to ensure white background with black text */}
                <Button
                    variant="secondary"
                    className="w-full font-bold text-lg py-3 border-none hover:bg-zinc-200"
                    disabled={cart.length === 0}
                    onClick={onCheckout}
                >
                    Checkout
                </Button>
            </div>
        </div>
    );
}

const POS: React.FC = () => {
  const { products, discounts, addTransaction, addAppointment, currentUser, productCategories, serviceCategories, storeSettings } = useStore();
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');

  const navigate = useNavigate();

  // New: Tab state for splitting Products and Services
  const [activeTab, setActiveTab] = useState<'PRODUCTS' | 'SERVICES'>('PRODUCTS');
  const [activeCategory, setActiveCategory] = useState<string | 'ALL'>('ALL');

  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'GCASH' | 'SPLIT'>('CASH');
  const [gcashRef, setGcashRef] = useState('');
  const [splitCashAmount, setSplitCashAmount] = useState<string>(''); // String to handle inputs better

  // Mobile UI States
  const [isMobileCartOpen, setIsMobileCartOpen] = useState(false);

  // Modal States
  const [receiptSuccessOpen, setReceiptSuccessOpen] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [isQrZoomed, setIsQrZoomed] = useState(false);

  // Printer Settings
  const [paperSize, setPaperSize] = useState<'58mm' | '80mm'>('80mm');

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [selectedDiscountId, setSelectedDiscountId] = useState<string>('');

  // Determine which categories to show based on active tab
  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;

  // Filtering Logic
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      // 1. Filter by Tab (Product vs Service)
      const isService = p.isService;
      if (activeTab === 'PRODUCTS' && isService) return false;
      if (activeTab === 'SERVICES' && !isService) return false;

      // 2. Filter by Search (Normalized)
      const normalizedSearch = normalizeText(search);
      const normalizedName = normalizeText(p.name);
      const matchesSearch = normalizedName.includes(normalizedSearch);

      // 3. Filter by Category
      const matchesCategory = activeCategory === 'ALL' || p.category === activeCategory;

      return matchesSearch && matchesCategory;
    });
  }, [products, search, activeCategory, activeTab]);

  // Cart Logic
  const addToCart = (product: Product) => {
    if (!product.isService && product.stock <= 0) return;

    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (!product.isService && existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          if (newQty < 1) return item;
          // Check stock limit for physical goods
          if (!item.isService && newQty > item.stock) return item;
          return { ...item, quantity: newQty };
        }
        return item;
      });
    });
  };

  // Totals
  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

  const activeDiscount = discounts.find(d => d.id === selectedDiscountId && d.active);
  const discountAmount = activeDiscount 
    ? (activeDiscount.type === 'PERCENTAGE' ? subtotal * (activeDiscount.value / 100) : activeDiscount.value)
    : 0;

  const total = Math.max(0, subtotal - discountAmount);

  // Dynamic VAT Calculation
  const vatRate = storeSettings.vatRate / 100;
  const vatAmount = (total / (1 + vatRate)) * vatRate; 

  const handleCheckout = () => {
    if (paymentMethod === 'GCASH' && !gcashRef) {
      alert('Please enter GCash Reference Number');
      return;
    }

    if (paymentMethod === 'SPLIT') {
        const cash = Number(splitCashAmount);
        if (isNaN(cash) || cash <= 0) {
            alert("Please enter a valid Cash amount");
            return;
        }
        if (cash >= total) {
            alert("Cash amount covers the total. Please switch to 'CASH' payment method.");
            return;
        }
        if (!gcashRef) {
            alert('Please enter GCash Reference Number for the balance');
            return;
        }
    }

    // 1. Create Transaction
    const transaction: Transaction = {
      id: Date.now().toString(),
      items: [...cart],
      subtotal,
      vat: vatAmount,
      total,
      discount: discountAmount,
      paymentMethod,
      gcashRef: (paymentMethod === 'GCASH' || paymentMethod === 'SPLIT') ? gcashRef : undefined,
      cashReceived: paymentMethod === 'SPLIT' ? Number(splitCashAmount) : undefined,
      date: new Date().toISOString(),
      cashierId: currentUser?.id || 'unknown',
    };

    addTransaction(transaction);
    setLastTransaction(transaction);

    // 2. Check for Services and Create Appointments (Auto-Redirect)
    const serviceItems = cart.filter(i => i.isService);
    let hasServices = false;

    if (serviceItems.length > 0) {
        hasServices = true;
        serviceItems.forEach(item => {
            // Create one appointment per quantity count
            for(let i=0; i < item.quantity; i++) {
                const now = new Date();
                const newApt: GroomingAppointment = {
                    id: Date.now().toString() + Math.random().toString().slice(2, 5),
                    petName: "Walk-in Pet", // Placeholder
                    ownerName: "Walk-in Guest",
                    contactNumber: "",
                    serviceId: item.id,
                    hairCut: `Paid at POS (Tx: #${transaction.id.slice(-4)})`,
                    date: now.toLocaleDateString('en-CA', {timeZone: 'Asia/Manila'}),
                    time: now.toLocaleTimeString('en-US', {hour12: false, hour: '2-digit', minute:'2-digit', timeZone: 'Asia/Manila'}),
                    status: 'SCHEDULED', // Add to Waiting list immediately (Scheduled + Today = Waiting)
                    groomerId: 'Unassigned',
                };
                addAppointment(newApt);
            }
        });
    }

    // 3. Cleanup & Navigation
    setCart([]);
    setIsCheckoutOpen(false);
    setIsMobileCartOpen(false); 
    setGcashRef('');
    setSplitCashAmount('');
    setSelectedDiscountId('');

    // If services were bought, redirect to Grooming page immediately
    if (hasServices) {
        // We skip the Receipt Modal in UI but the transaction is saved
        // Maybe show a quick alert or just go?
        // Let's just go, the grooming flow is priority as per user request.
        navigate('/grooming'); 
    } else {
        // If only products, show Receipt Modal
        setReceiptSuccessOpen(true); 
    }
  };

  const handleOpenPreview = () => {
    setReceiptSuccessOpen(false);
    setPreviewOpen(true);
  };

  const handleActualPrint = () => {
    setTimeout(() => {
        window.print();
    }, 500);
  };

  const handleTabChange = (tab: 'PRODUCTS' | 'SERVICES') => {
      setActiveTab(tab);
      setActiveCategory('ALL'); // Reset category filter when switching tabs
  };

