// Helper for loose search matching
const normalizeText = (text: string) => text.toLowerCase().replace(/[^a-z0-9]/g, '');

// Reusable Cart UI Component
interface CartPanelProps {
    cart: CartItem[];
    updateQuantity: (id: string, delta: number) => void;
    removeFromCart: (id: string) => void;
    openDiscountModal: () => void;
    openBreakdownModal: (item: CartItem) => void; // New: Open item specific breakdown
    subtotal: number;
    discountAmount: number;
    total: number;
    onCheckout: () => void;
    onClose?: () => void; // For mobile modal
}

const CartPanel: React.FC<CartPanelProps> = ({ 
    cart, updateQuantity, removeFromCart, openDiscountModal, openBreakdownModal,
    subtotal, discountAmount, total, onCheckout, onClose
}) => {

    return (
        <div className="flex flex-col h-full bg-white lg:rounded-3xl shadow-xl border border-zinc-100 overflow-hidden">
            <div className="p-5 border-b border-zinc-100 bg-zinc-50 lg:rounded-t-3xl flex justify-between items-center">
                <h2 className="font-bold text-lg flex items-center gap-2 text-zinc-900">
                    <ShoppingBag className="w-5 h-5" />
                    Current Order
                </h2>
                {onClose && (
                    <button onClick={onClose} className="lg:hidden p-2 text-gray-500 hover:bg-zinc-200 rounded-full">
                        <X className="w-5 h-5" />
                    </button>
                )}
            </div>

            <div className="flex-1 overflow-auto p-4 space-y-3">
                {cart.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-gray-400">
                        <ShoppingBag className="w-12 h-12 mb-2 opacity-20" />
                        <p>Cart is empty</p>
                    </div>
                ) : (
                    cart.map(item => {
                        const isMaxStock = !item.isService && item.quantity >= item.stock;
                        const discounts = item.appliedDiscounts || [];
                        const hasDiscount = discounts.length > 0;

                        // Calculate display price per unit with discount
                        const originalTotal = item.price * item.quantity;
                        let totalDiscountValue = 0;

                        // Additive Discount Calculation
                        discounts.forEach(d => {
                            if (d.type === 'PERCENTAGE') {
                                totalDiscountValue += originalTotal * (d.value / 100);
                            } else {
                                totalDiscountValue += d.value * item.quantity;
                            }
                        });

                        // Ensure we don't discount more than the price
                        totalDiscountValue = Math.min(totalDiscountValue, originalTotal);

                        // Construct tooltip text
                        const discountTooltip = discounts.map(d => `${d.name} (${d.type === 'PERCENTAGE' ? d.value + '%' : '₱'+d.value})`).join(', ');

                        return (
                            <div key={item.id} className={`flex items-center gap-3 bg-white p-3 rounded-2xl border shadow-sm relative group ${hasDiscount ? 'border-green-200 bg-green-50/30' : 'border-zinc-100'}`}>
                                <div className="flex-1">
                                    <div className="flex items-center gap-2">
                                        <p className="font-semibold text-sm text-zinc-900 line-clamp-1">{item.name}</p>
                                        {isMaxStock && <span className="text-[10px] font-bold bg-red-100 text-red-600 px-1.5 py-0.5 rounded">MAX</span>}

                                        {/* Discount Icon Badge (Clickable) */}
                                        {hasDiscount && (
                                            <button 
                                                onClick={() => openBreakdownModal(item)}
                                                className="flex items-center gap-1 bg-green-100 text-green-700 px-2 py-0.5 rounded-full text-[10px] font-bold hover:bg-green-200 transition-colors"
                                                title={discountTooltip}
                                            >
                                                <Tag className="w-3 h-3" />
                                                <span>{discounts.length > 1 ? `${discounts.length} Promos` : discounts[0].name}</span>
                                            </button>
                                        )}
                                    </div>
                                    <div className="flex gap-2 items-end">
                                        <p className="text-xs text-gray-500">₱{item.price} each</p>
                                        {hasDiscount && (
                                            <p className="text-xs text-green-600 font-bold">(-₱{totalDiscountValue.toFixed(2)})</p>
                                        )}
                                    </div>
                                </div>
                                <div className="flex items-center gap-1 bg-zinc-100 rounded-xl p-1">
                                    <button
                                        onClick={() => updateQuantity(item.id, -1)}
                                        className="w-8 h-8 flex items-center justify-center bg-white rounded-lg shadow-sm hover:bg-zinc-50 active:scale-95 transition-all text-zinc-900"
                                    >
                                        <Minus className="w-4 h-4" />
                                    </button>
                                    <span className="text-sm font-bold w-8 text-center text-zinc-900">{item.quantity}</span>
                                    <button
                                        onClick={() => updateQuantity(item.id, 1)}
                                        disabled={isMaxStock}
                                        className={`w-8 h-8 flex items-center justify-center bg-white rounded-lg shadow-sm transition-all text-zinc-900 ${isMaxStock ? 'opacity-50 cursor-not-allowed' : 'hover:bg-zinc-50 active:scale-95'
                                            }`}
                                    >
                                        <Plus className="w-4 h-4" />
                                    </button>
                                </div>

                                <button
                                    onClick={() => removeFromCart(item.id)}
                                    className="w-8 h-8 flex items-center justify-center text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors ml-1"
                                    title="Remove Item"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        )
                    })
                )}
            </div>

            <div className="p-5 bg-zinc-900 text-white lg:rounded-b-3xl mt-auto shadow-inner">
                <div className="mb-4">
                    <button 
                        onClick={openDiscountModal}
                        className="w-full bg-zinc-800 border border-zinc-700 hover:bg-zinc-700 text-white rounded-xl p-3 text-sm font-bold flex items-center justify-center gap-2 transition-all"
                        disabled={cart.length === 0}
                    >
                        <Percent className="w-4 h-4" /> Apply Discount / Promo
                    </button>
                </div>

                <div className="space-y-2 text-sm mb-4 border-t border-zinc-800 pt-4">
                    <div className="flex justify-between text-gray-400"><span>Subtotal</span><span>₱{subtotal.toFixed(2)}</span></div>
                    <div className="flex justify-between text-gray-400"><span>Total Discount</span><span className="text-green-400">-₱{discountAmount.toFixed(2)}</span></div>
                    <div className="flex justify-between text-white font-bold text-lg pt-2 border-t border-zinc-700">
                        <span>Total</span>
                        <span>₱{total.toFixed(2)}</span>
                    </div>
                </div>

                <Button
                    variant="secondary"
                    className="w-full font-bold text-lg py-3 border-none hover:bg-zinc-200"
                    disabled={cart.length === 0}
                    onClick={onCheckout}
                >
                    Checkout
                </Button>
            </div>
        </div>
    );
}

const POS: React.FC = () => {
  const { products, discounts, addTransaction, addAppointment, currentUser, productCategories, serviceCategories, storeSettings, clients, users } = useStore();
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');

  const navigate = useNavigate();

  // New: Tab state for splitting Products and Services
  const [activeTab, setActiveTab] = useState<'PRODUCTS' | 'SERVICES'>('PRODUCTS');
  const [activeCategory, setActiveCategory] = useState<string | 'ALL'>('ALL');

  // Checkout Modals
  const [showGroomingModal, setShowGroomingModal] = useState(false);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);

  // Discount Management
  const [isDiscountManagerOpen, setIsDiscountManagerOpen] = useState(false);
  const [selectedDiscountToApply, setSelectedDiscountToApply] = useState<Discount | null>(null);
  const [itemSelectionForDiscount, setItemSelectionForDiscount] = useState<string[]>([]); // Array of CartItem IDs

  // Item Specific Discount Breakdown
  const [breakdownItem, setBreakdownItem] = useState<CartItem | null>(null);

  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'GCASH' | 'SPLIT'>('CASH');
  const [gcashRef, setGcashRef] = useState('');
  const [splitCashAmount, setSplitCashAmount] = useState<string>(''); 

  // Mobile UI States
  const [isMobileCartOpen, setIsMobileCartOpen] = useState(false);

  // Modal States
  const [receiptSuccessOpen, setReceiptSuccessOpen] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [isQrZoomed, setIsQrZoomed] = useState(false);

  // Printer Settings
  const [paperSize, setPaperSize] = useState<'58mm' | '80mm'>('80mm');

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);

  // Grooming Details State
  const [groomingFormData, setGroomingFormData] = useState({
      ownerName: '', contactNumber: '', email: '', petName: '', petBreed: '', petColor: '', weightSize: '', groomerId: '', hairCut: ''
  });
  // Client Autocomplete Logic for POS
  const [filteredClients, setFilteredClients] = useState<Client[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [showClientSuggestions, setShowClientSuggestions] = useState(false);
  const clientDropdownRef = useRef<HTMLDivElement>(null);

  // Pet Autocomplete Logic
  const [showPetSuggestions, setShowPetSuggestions] = useState(false);
  const petDropdownRef = useRef<HTMLDivElement>(null);

  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');

  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (clientDropdownRef.current && !clientDropdownRef.current.contains(event.target as Node)) {
              setShowClientSuggestions(false);
          }
          if (petDropdownRef.current && !petDropdownRef.current.contains(event.target as Node)) {
              setShowPetSuggestions(false);
          }
      };
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // --- CLIENT & PET LOGIC (SAME AS BEFORE) ---
  const handleOwnerSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setGroomingFormData(prev => ({...prev, ownerName: val}));
      if(selectedClient && selectedClient.name !== val) setSelectedClient(null);
      if (val.length > 0) {
          const normalizedSearch = normalizeText(val);
          const matches = clients.filter(c => 
              normalizeText(c.name).includes(normalizedSearch) || 
              (c.contactNumber && c.contactNumber.replace(/\D/g,'').includes(normalizedSearch))
          );
          setFilteredClients(matches.slice(0, 5));
          setShowClientSuggestions(true);
      } else {
          setShowClientSuggestions(false);
      }
  };

  const selectClient = (client: Client) => {
      setGroomingFormData(prev => ({
          ...prev,
          ownerName: client.name,
          contactNumber: client.contactNumber,
          email: client.email || '',
          petName: '', petBreed: '', petColor: '', weightSize: ''
      }));
      setSelectedClient(client);
      setShowClientSuggestions(false);
  };

  const handlePetNameFocus = () => {
      if (selectedClient && selectedClient.pets && selectedClient.pets.length > 0) {
          setShowPetSuggestions(true);
      }
  };

  const selectPet = (pet: Pet) => {
      setGroomingFormData(prev => ({
          ...prev,
          petName: pet.name,
          petBreed: pet.breed || '',
          petColor: pet.color || '',
          weightSize: pet.weightSize || ''
      }));
      setShowPetSuggestions(false);
  };

  // Determine which categories to show based on active tab
  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;

  // Filtering Logic
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const isService = p.isService;
      if (activeTab === 'PRODUCTS' && isService) return false;
      if (activeTab === 'SERVICES' && !isService) return false;
      const normalizedSearch = normalizeText(search);
      const normalizedName = normalizeText(p.name);
      const matchesSearch = normalizedName.includes(normalizedSearch);
      const matchesCategory = activeCategory === 'ALL' || p.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [products, search, activeCategory, activeTab]);

  // Cart Logic
  const addToCart = (product: Product) => {
    if (!product.isService && product.stock <= 0) return;

    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (!product.isService && existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1, appliedDiscounts: [] }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          if (newQty < 1) return item;
          if (!item.isService && newQty > item.stock) return item;
          return { ...item, quantity: newQty };
        }
        return item;
      });
    });
  };

  // --- DISCOUNT MANAGEMENT ---

  // Removes a specific discount from a cart item
  const removeSpecificDiscount = (itemId: string, discountId: string) => {
      setCart(prev => prev.map(item => {
          if (item.id === itemId) {
              return { 
                  ...item, 
                  appliedDiscounts: (item.appliedDiscounts || []).filter(d => d.id !== discountId)
              };
          }
          return item;
      }));
      // Also update the breakdown modal view if it's open for this item
      if (breakdownItem && breakdownItem.id === itemId) {
          setBreakdownItem(prev => prev ? {
              ...prev,
              appliedDiscounts: (prev.appliedDiscounts || []).filter(d => d.id !== discountId)
          } : null);
      }
  };

  const handleOpenDiscountManager = () => {
      setSelectedDiscountToApply(null);
      setItemSelectionForDiscount([]);
      setIsDiscountManagerOpen(true);
  };

  const handleToggleItemForDiscount = (itemId: string) => {
      // Toggle logic
      setItemSelectionForDiscount(prev => 
          prev.includes(itemId) ? prev.filter(id => id !== itemId) : [...prev, itemId]
      );
  };

  const handleSelectAllForDiscount = () => {
      // Filter out items that already have this discount to find eligible ones
      const eligibleItems = cart.filter(item => 
          !item.appliedDiscounts?.some(d => d.id === selectedDiscountToApply?.id)
      );

      const eligibleIds = eligibleItems.map(i => i.id);

      // If all eligible are selected, deselect. Else select all eligible.
      const allSelected = eligibleIds.length > 0 && eligibleIds.every(id => itemSelectionForDiscount.includes(id));

      if (allSelected) {
          setItemSelectionForDiscount([]);
      } else {
          setItemSelectionForDiscount(eligibleIds);
      }
  };

  const applySelectedDiscount = () => {
      if (!selectedDiscountToApply) return;

      setCart(prev => prev.map(item => {
          if (itemSelectionForDiscount.includes(item.id)) {
              // Append to existing array, ensure no duplicates (safety check)
              const existing = item.appliedDiscounts || [];
              if (existing.some(d => d.id === selectedDiscountToApply.id)) {
                  return item;
              }
              return { ...item, appliedDiscounts: [...existing, selectedDiscountToApply] };
          }
          return item;
      }));

      setIsDiscountManagerOpen(false);
  };

  // --- TOTALS CALCULATION (Updated for Multiple Discounts) ---
  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

  const discountAmount = cart.reduce((sum, item) => {
      const discounts = item.appliedDiscounts || [];
      if (discounts.length === 0) return sum;

      const originalItemTotal = item.price * item.quantity;
      let itemDiscount = 0;

      discounts.forEach(d => {
          if (d.type === 'PERCENTAGE') {
              itemDiscount += originalItemTotal * (d.value / 100);
          } else {
              itemDiscount += d.value * item.quantity;
          }
      });

      // Cap discount at item total price (can't go below zero)
      return sum + Math.min(itemDiscount, originalItemTotal);
  }, 0);

  const total = Math.max(0, subtotal - discountAmount);
  const vatRate = storeSettings.vatRate / 100;
  const vatAmount = (total / (1 + vatRate)) * vatRate; 

  // --- CHECKOUT HANDLERS ---
  const handleCheckoutClick = () => {
      const hasService = cart.some(item => item.isService);
      if (hasService) {
          setShowGroomingModal(true);
      } else {
          setIsCheckoutOpen(true);
      }
  };

  const handleProceedToPayment = (e: React.FormEvent) => {
      e.preventDefault();
      if (!groomingFormData.ownerName || !groomingFormData.petName || !groomingFormData.groomerId) {
          alert("Please fill in Owner Name, Pet Name, and select a Groomer.");
          return;
      }
      setShowGroomingModal(false);
      setIsCheckoutOpen(true);
  };

  const handleFinalizeTransaction = () => {
    if (paymentMethod === 'GCASH' && !gcashRef) {
      alert('Please enter GCash Reference Number');
      return;
    }
    if (paymentMethod === 'SPLIT') {
        const cash = Number(splitCashAmount);
        if (isNaN(cash) || cash <= 0) { alert("Please enter a valid Cash amount"); return; }
        if (cash >= total) { alert("Cash amount covers the total. Please switch to 'CASH' payment method."); return; }
        if (!gcashRef) { alert('Please enter GCash Reference Number for the balance'); return; }
    }

    // Create Transaction
    const transaction: Transaction = {
      id: Date.now().toString(),
      items: [...cart],
      subtotal,
      vat: vatAmount,
      total,
      discount: discountAmount,
      paymentMethod,
      gcashRef: (paymentMethod === 'GCASH' || paymentMethod === 'SPLIT') ? gcashRef : undefined,
      cashReceived: paymentMethod === 'SPLIT' ? Number(splitCashAmount) : undefined,
      date: new Date().toISOString(),
      cashierId: currentUser?.id || 'unknown',
    };

    addTransaction(transaction);
    setLastTransaction(transaction);

    // Appointments Logic
    const serviceItems = cart.filter(i => i.isService);
    let hasServices = false;

    if (serviceItems.length > 0) {
        hasServices = true;
        serviceItems.forEach(item => {
            for(let i=0; i < item.quantity; i++) {
                const now = new Date();
                const instructions = groomingFormData.hairCut 
                    ? `${groomingFormData.hairCut} (Paid at POS Tx:#${transaction.id.slice(-4)})`
                    : `Paid at POS (Tx: #${transaction.id.slice(-4)})`;

                const newApt: GroomingAppointment = {
                    id: Date.now().toString() + Math.random().toString().slice(2, 5),
                    petName: groomingFormData.petName,
                    petBreed: groomingFormData.petBreed,
                    petColor: groomingFormData.petColor,
                    weightSize: groomingFormData.weightSize,
                    ownerName: groomingFormData.ownerName,
                    contactNumber: groomingFormData.contactNumber,
                    email: groomingFormData.email,
                    groomerId: groomingFormData.groomerId,
                    serviceId: item.id,
                    hairCut: instructions,
                    date: now.toLocaleDateString('en-CA', {timeZone: 'Asia/Manila'}),
                    time: now.toLocaleTimeString('en-US', {hour12: false, hour: '2-digit', minute:'2-digit', timeZone: 'Asia/Manila'}),
                    status: 'SCHEDULED',
                };
                addAppointment(newApt);
            }
        });
    }

    setCart([]);
    setIsCheckoutOpen(false);
    setIsMobileCartOpen(false); 
    setGcashRef('');
    setSplitCashAmount('');
    setGroomingFormData({ ownerName: '', contactNumber: '', email: '', petName: '', petBreed: '', petColor: '', weightSize: '', groomerId: '', hairCut: '' });
    setSelectedClient(null);

    if (hasServices) {
        navigate('/grooming'); 
    } else {
        setReceiptSuccessOpen(true); 
    }
  };

  const handleActualPrint = () => {
    setTimeout(() => { window.print(); }, 500);
  };

  const handleOpenPreview = () => {
      setPreviewOpen(true);
  };

  const handleTabChange = (tab: 'PRODUCTS' | 'SERVICES') => {
      setActiveTab(tab);
      setActiveCategory('ALL');
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium text-sm";
  const labelClass = "text-xs font-bold text-gray-500 uppercase";

  return (
    <>
    <div className="flex flex-col lg:flex-row h-[calc(100vh-80px)] lg:h-[calc(100vh-100px)] gap-6 print:hidden relative">
      {/* Product Grid */}
      <div className="flex-1 flex flex-col bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden h-full">
        {/* Header */}
        <div className="p-4 border-b border-zinc-100 space-y-4">
          <div className="flex gap-4">
             <button onClick={() => handleTabChange('PRODUCTS')} className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${activeTab === 'PRODUCTS' ? 'bg-black text-white shadow-lg' : 'bg-zinc-50 text-gray-500 hover:bg-zinc-100 border border-zinc-200'}`}>
                <Bone className="w-5 h-5" /> Products
             </button>
             <button onClick={() => handleTabChange('SERVICES')} className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${activeTab === 'SERVICES' ? 'bg-black text-white shadow-lg' : 'bg-zinc-50 text-gray-500 hover:bg-zinc-100 border border-zinc-200'}`}>
                <Scissors className="w-5 h-5" /> Services
             </button>
          </div>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input type="text" placeholder={`Search ${activeTab === 'PRODUCTS' ? 'products' : 'services'}...`} className="w-full pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black" value={search} onChange={e => setSearch(e.target.value)} />
          </div>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
            <Button size="sm" variant={activeCategory === 'ALL' ? 'primary' : 'secondary'} onClick={() => setActiveCategory('ALL')}>All</Button>
            {currentCategories.map(cat => (
              <Button key={cat} size="sm" variant={activeCategory === cat ? 'primary' : 'secondary'} onClick={() => setActiveCategory(cat)}>{cat}</Button>
            ))}
          </div>
        </div>

        {/* Grid */}
        <div className="flex-1 overflow-auto p-4 grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 content-start pb-24 lg:pb-4">
          {filteredProducts.map(product => {
            const isOutOfStock = !product.isService && product.stock <= 0;
            return (
            <button key={product.id} onClick={() => !isOutOfStock && addToCart(product)} disabled={isOutOfStock} className={`group flex flex-col items-center text-center p-4 rounded-2xl border transition-all duration-200 ${isOutOfStock ? 'border-zinc-100 bg-zinc-50 opacity-60 cursor-not-allowed' : 'border-zinc-100 hover:border-black hover:shadow-lg bg-zinc-50/50'}`}>
              <div className={`w-16 h-16 bg-white rounded-full flex items-center justify-center mb-3 shadow-sm transition-transform ${!isOutOfStock && 'group-hover:scale-110'}`}>
                {product.isService ? <Scissors className="w-8 h-8 text-black" /> : <Bone className="w-8 h-8 text-black" />}
              </div>
              <h3 className="font-semibold text-sm line-clamp-2 min-h-[40px] text-zinc-900">{product.name}</h3>
              <p className={`text-xs mb-2 ${isOutOfStock ? 'text-red-500 font-bold' : 'text-gray-500'}`}>
                {product.isService ? 'Service' : (isOutOfStock ? 'Out of Stock' : `${product.stock} in stock`)}
              </p>
              <span className={`text-xs font-bold px-2 py-1 rounded-lg ${isOutOfStock ? 'bg-gray-200 text-gray-500' : 'bg-black text-white'}`}>₱{product.price}</span>
            </button>
          )})}
          {filteredProducts.length === 0 && <div className="col-span-full flex flex-col items-center justify-center text-gray-400 py-10"><Bone className="w-10 h-10 mb-2 opacity-20" /><p>No results found</p></div>}
        </div>
      </div>

      {/* Desktop Cart */}
      <div className="hidden lg:block w-96 h-full">
         <CartPanel 
            cart={cart} updateQuantity={updateQuantity} removeFromCart={removeFromCart}
            openDiscountModal={handleOpenDiscountManager} openBreakdownModal={(item) => setBreakdownItem(item)}
            subtotal={subtotal} discountAmount={discountAmount} total={total} onCheckout={handleCheckoutClick}
         />
      </div>

      {/* Mobile Floating Bar */}
      {cart.length > 0 && (
          <div className="lg:hidden fixed bottom-4 left-4 right-4 z-40 animate-slide-up print:hidden">
              <button onClick={() => setIsMobileCartOpen(true)} className="w-full bg-black text-white p-4 rounded-2xl shadow-2xl flex justify-between items-center active:scale-95 transition-transform">
                  <div className="flex items-center gap-3">
                      <div className="bg-white text-black font-bold w-8 h-8 rounded-full flex items-center justify-center text-sm">{totalItems}</div>
                      <span className="font-bold text-sm">View Cart</span>
                  </div>
                  <div className="flex items-center gap-2">
                      <span className="font-bold text-lg">₱{total.toFixed(2)}</span>
                      <ArrowRight className="w-5 h-5" />
                  </div>
              </button>
          </div>
      )}

      {/* Mobile Cart Modal */}
      <Dialog open={isMobileCartOpen} onClose={() => setIsMobileCartOpen(false)} className="relative z-50 lg:hidden print:hidden">
         <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
         <div className="fixed inset-x-0 bottom-0 flex justify-center">
            <Dialog.Panel className="w-full max-w-lg bg-white rounded-t-3xl shadow-2xl h-[85vh] flex flex-col animate-slide-up">
                 <div className="w-full flex justify-center pt-3 pb-1" onClick={() => setIsMobileCartOpen(false)}><div className="w-12 h-1.5 bg-zinc-200 rounded-full"></div></div>
                 <CartPanel 
                    cart={cart} updateQuantity={updateQuantity} removeFromCart={removeFromCart}
                    openDiscountModal={handleOpenDiscountManager} openBreakdownModal={(item) => setBreakdownItem(item)}
                    subtotal={subtotal} discountAmount={discountAmount} total={total}
                    onCheckout={handleCheckoutClick} onClose={() => setIsMobileCartOpen(false)}
                />
            </Dialog.Panel>
         </div>
      </Dialog>

      {/* DISCOUNT MANAGER MODAL */}
      <Dialog open={isDiscountManagerOpen} onClose={() => setIsDiscountManagerOpen(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-2xl bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-slide-up">
            <div className="p-5 border-b border-zinc-100 flex justify-between items-center bg-zinc-50">
                <h3 className="text-xl font-bold text-zinc-900 flex items-center gap-2"><Percent className="w-6 h-6 text-black" /> Apply Discount</h3>
                <button onClick={() => setIsDiscountManagerOpen(false)} className="text-gray-400 hover:text-black"><X className="w-6 h-6" /></button>
            </div>
            <div className="flex flex-col md:flex-row h-full overflow-hidden">
                <div className="w-full md:w-1/3 border-r border-zinc-100 flex flex-col bg-zinc-50">
                    <div className="p-4 border-b border-zinc-100"><p className="text-xs font-bold text-gray-500 uppercase">1. Choose Discount</p></div>
                    <div className="flex-1 overflow-y-auto p-2 space-y-2">
                        {discounts.filter(d => d.active).map(discount => (
                            <button key={discount.id} onClick={() => { setSelectedDiscountToApply(discount); setItemSelectionForDiscount([]); }}
                                className={`w-full text-left p-3 rounded-xl border transition-all ${selectedDiscountToApply?.id === discount.id ? 'bg-black text-white border-black shadow-md' : 'bg-white border-zinc-200 text-zinc-700 hover:border-zinc-400'}`}>
                                <div className="font-bold text-sm">{discount.name}</div>
                                <div className={`text-xs ${selectedDiscountToApply?.id === discount.id ? 'text-zinc-300' : 'text-gray-500'}`}>{discount.type === 'PERCENTAGE' ? `${discount.value}% Off` : `₱${discount.value} Off`}</div>
                            </button>
                        ))}
                    </div>
                </div>
                <div className="flex-1 flex flex-col bg-white">
                    <div className="p-4 border-b border-zinc-100 flex justify-between items-center">
                        <p className="text-xs font-bold text-gray-500 uppercase">2. Select Eligible Items</p>
                        <button onClick={handleSelectAllForDiscount} className="text-xs font-bold text-blue-600 hover:underline">Select All</button>
                    </div>
                    <div className="flex-1 overflow-y-auto p-4 space-y-2">
                        {cart.map(item => {
                            // Check if this specific discount is already applied
                            const alreadyApplied = item.appliedDiscounts?.some(d => d.id === selectedDiscountToApply?.id);

                            // Only show valid items (that don't have it yet) OR show them disabled?
                            // User request: "lalabas nalang doon ung mga hindi pa applied na discount na items"
                            if (alreadyApplied) return null;

                            const isSelected = itemSelectionForDiscount.includes(item.id);
                            return (
                                <div key={item.id} onClick={() => handleToggleItemForDiscount(item.id)} className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${isSelected ? 'border-green-500 bg-green-50' : 'border-zinc-100 hover:border-zinc-300'}`}>
                                    <div className={`w-5 h-5 rounded-full border flex items-center justify-center ${isSelected ? 'bg-green-500 border-green-500' : 'bg-white border-gray-300'}`}>
                                        {isSelected && <Check className="w-3 h-3 text-white" />}
                                    </div>
                                    <div className="flex-1">
                                        <p className="font-bold text-sm text-zinc-900">{item.name}</p>
                                        <div className="flex justify-between items-center mt-1">
                                            <span className="text-xs text-gray-500">Qty: {item.quantity} • ₱{item.price}</span>
                                            {item.appliedDiscounts && item.appliedDiscounts.length > 0 && (
                                                <span className="text-[10px] bg-orange-100 text-orange-700 px-2 py-0.5 rounded font-bold">
                                                    Stacking on: {item.appliedDiscounts.length} Promos
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                        {selectedDiscountToApply && cart.every(i => i.appliedDiscounts?.some(d => d.id === selectedDiscountToApply.id)) && (
                            <div className="text-center p-8 text-gray-400 text-xs">
                                <CheckCircle className="w-8 h-8 mx-auto mb-2 opacity-20"/>
                                This discount is applied to all items!
                            </div>
                        )}
                    </div>
                    <div className="p-4 border-t border-zinc-100 bg-zinc-50">
                        <Button disabled={!selectedDiscountToApply || itemSelectionForDiscount.length === 0} onClick={applySelectedDiscount} className="w-full">
                            Apply {selectedDiscountToApply?.name} ({itemSelectionForDiscount.length})
                        </Button>
                    </div>
                </div>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* ITEM DISCOUNT BREAKDOWN MODAL */}
      <Dialog open={!!breakdownItem} onClose={() => setBreakdownItem(null)} className="relative z-[70]">
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-2xl p-6 shadow-2xl animate-fade-in">
                <div className="flex justify-between items-center mb-4 border-b border-zinc-100 pb-3">
                    <h3 className="font-bold text-lg text-zinc-900">Discount Breakdown</h3>
                    <button onClick={() => setBreakdownItem(null)} className="text-gray-400 hover:text-black"><X className="w-5 h-5"/></button>
                </div>

                <div className="mb-4">
                    <p className="font-bold text-sm text-zinc-800">{breakdownItem?.name}</p>
                    <p className="text-xs text-gray-500">Original Price: ₱{breakdownItem ? (breakdownItem.price * breakdownItem.quantity).toFixed(2) : 0}</p>
                </div>

                <div className="space-y-2 mb-4 max-h-60 overflow-y-auto custom-scrollbar">
                    {breakdownItem?.appliedDiscounts?.map(discount => {
                        const amount = discount.type === 'PERCENTAGE' 
                            ? (breakdownItem.price * breakdownItem.quantity) * (discount.value / 100)
                            : discount.value * breakdownItem.quantity;

                        return (
                            <div key={discount.id} className="flex justify-between items-center bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                                <div>
                                    <p className="font-bold text-sm text-zinc-900">{discount.name}</p>
                                    <p className="text-xs text-green-600 font-bold">
                                        -{discount.type === 'PERCENTAGE' ? discount.value + '%' : '₱' + discount.value} (Save ₱{amount.toFixed(2)})
                                    </p>
                                </div>
                                <button 
                                    onClick={() => removeSpecificDiscount(breakdownItem.id, discount.id)}
                                    className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Remove this discount"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        );
                    })}
                    {(!breakdownItem?.appliedDiscounts || breakdownItem.appliedDiscounts.length === 0) && (
                        <p className="text-center text-xs text-gray-400 italic py-4">No discounts applied to this item.</p>
                    )}
                </div>

                <Button variant="secondary" onClick={() => setBreakdownItem(null)} className="w-full">Done</Button>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* GROOMING MODAL (Same as previous) */}
      <Dialog open={showGroomingModal} onClose={() => setShowGroomingModal(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh] animate-slide-up">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">Walk-in Grooming Details</Dialog.Title>
            <form onSubmit={handleProceedToPayment} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">
              <div className="space-y-3">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><User className="w-3 h-3" /> Owner & Pet</h4>
                  <div className="relative" ref={clientDropdownRef}>
                      <label className={labelClass}>Owner Name</label>
                      <input required className={`${inputClass} pl-9`} value={groomingFormData.ownerName} onChange={handleOwnerSearch} onFocus={(e) => handleOwnerSearch(e)} placeholder="Search or type new..." autoComplete="off"/>
                      <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                      {showClientSuggestions && filteredClients.length > 0 && (
                          <div className="absolute z-50 w-full bg-white mt-2 rounded-2xl shadow-xl border border-zinc-100 overflow-hidden ring-1 ring-black/5 max-h-60 overflow-y-auto custom-scrollbar">
                              {filteredClients.map(client => (
                                  <div key={client.id} onClick={() => selectClient(client)} className="p-3.5 hover:bg-zinc-50 cursor-pointer border-b border-zinc-50 last:border-0 flex justify-between items-center group">
                                      <div><p className="text-sm font-bold text-zinc-900">{client.name}</p><p className="text-xs text-gray-500">{client.contactNumber}</p></div>
                                      <ChevronDown className="-rotate-90 w-4 h-4 text-gray-300" />
                                  </div>
                              ))}
                          </div>
                      )}
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className={labelClass}>Contact #</label><input className={inputClass} value={groomingFormData.contactNumber} onChange={e => setGroomingFormData({...groomingFormData, contactNumber: e.target.value})} placeholder="09XX..." /></div>
                    <div><label className={labelClass}>Email (Optional)</label><input type="email" className={inputClass} value={groomingFormData.email} onChange={e => setGroomingFormData({...groomingFormData, email: e.target.value})} placeholder="email@..." /></div>
                  </div>
                  <div className="grid grid-cols-2 gap-4 pt-2">
                    <div className="relative" ref={petDropdownRef}>
                        <label className={labelClass}>Pet Name</label>
                        <input required className={inputClass} value={groomingFormData.petName} onChange={e => {setGroomingFormData({...groomingFormData, petName: e.target.value}); if (selectedClient && selectedClient.pets?.length) setShowPetSuggestions(true);}} onFocus={handlePetNameFocus} placeholder="Pet's Name" autoComplete="off"/>
                        {showPetSuggestions && selectedClient && selectedClient.pets.length > 0 && (
                            <div className="absolute z-50 w-full bg-white mt-2 rounded-2xl shadow-xl border border-zinc-100 overflow-hidden ring-1 ring-black/5 animate-in fade-in slide-in-from-top-2 duration-200">
                                <div className="p-2.5 bg-zinc-50 text-[10px] text-gray-400 font-bold uppercase tracking-wider border-b border-zinc-100">{selectedClient.name}'s Pets</div>
                                {selectedClient.pets.filter(p => normalizeText(p.name).includes(normalizeText(groomingFormData.petName || ''))).map(pet => (
                                    <div key={pet.id} onClick={() => selectPet(pet)} className="p-3.5 hover:bg-zinc-50 cursor-pointer border-b border-zinc-50 last:border-0 flex justify-between items-center group">
                                        <div><p className="text-sm font-bold text-zinc-900">{pet.name}</p><p className="text-xs text-gray-500">{pet.breed}</p></div><Check className="w-4 h-4 text-green-500 opacity-0 group-hover:opacity-100 transition-opacity" />
                                    </div>
                                ))}
                                <div className="p-3.5 hover:bg-blue-50 cursor-pointer text-blue-600 font-bold text-xs flex items-center gap-2 border-t border-zinc-100 transition-colors" onClick={() => setShowPetSuggestions(false)}><Plus className="w-3 h-3" /> Add New Pet "{groomingFormData.petName}"</div>
                            </div>
                        )}
                    </div>
                    <div><label className={labelClass}>Breed</label><input className={inputClass} value={groomingFormData.petBreed} onChange={e => setGroomingFormData({...groomingFormData, petBreed: e.target.value})} placeholder="Breed" /></div>
                  </div>
              </div>
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Scissors className="w-3 h-3" /> Assignment</h4>
                  <div>
                    <label className={labelClass}>Assign Groomer</label>
                    <select required className={inputClass} value={groomingFormData.groomerId} onChange={e => setGroomingFormData({...groomingFormData, groomerId: e.target.value})} disabled={groomers.length === 0}>
                        <option value="">{groomers.length === 0 ? 'No Groomers Available' : 'Select Groomer'}</option>
                        {groomers.map(g => <option key={g.id} value={g.name}>{g.name}</option>)}
                    </select>
                  </div>
              </div>
              <div className="flex gap-3 pt-4 border-t border-zinc-100">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setShowGroomingModal(false)}>Back to Cart</Button>
                <Button type="submit" className="flex-1" disabled={!groomingFormData.ownerName || !groomingFormData.petName || !groomingFormData.groomerId}>Proceed to Payment</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* CHECKOUT & RECEIPT MODALS (Unchanged logic, just keeping structure) */}
      <Dialog open={isCheckoutOpen} onClose={() => setIsCheckoutOpen(false)} className="relative z-50 print:hidden">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">Order Summary & Payment</Dialog.Title>
            <div className="overflow-y-auto pr-2 custom-scrollbar">
            <div className="bg-zinc-50 rounded-xl p-4 mb-6 space-y-2">
              <div className="flex justify-between text-sm text-zinc-600"><span>Items ({cart.reduce((acc, i) => acc + i.quantity, 0)})</span><span>₱{subtotal.toFixed(2)}</span></div>
              <div className="flex justify-between text-sm text-zinc-600"><span>Discount Applied</span><span className="text-green-500 font-bold">-₱{discountAmount.toFixed(2)}</span></div>
              <div className="flex justify-between text-sm text-zinc-600"><span>VAT ({storeSettings.vatRate}% Included)</span><span>₱{vatAmount.toFixed(2)}</span></div>
              <div className="flex justify-between font-bold text-lg text-zinc-900 border-t border-zinc-200 pt-2 mt-2"><span>TOTAL TO PAY</span><span>₱{total.toFixed(2)}</span></div>
            </div>
            <p className="text-sm font-bold text-gray-700 mb-2">Select Payment Method</p>
            <div className="grid grid-cols-3 gap-3 mb-6">
              <button onClick={() => setPaymentMethod('CASH')} className={`p-3 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${paymentMethod === 'CASH' ? 'border-black bg-zinc-50' : 'border-zinc-100'}`}><div className="w-6 h-6 rounded-full bg-green-100 flex items-center justify-center text-green-600 font-bold text-xs">₱</div><span className="font-semibold text-xs">Cash</span></button>
              <button onClick={() => setPaymentMethod('GCASH')} className={`p-3 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${paymentMethod === 'GCASH' ? 'border-blue-500 bg-blue-50' : 'border-zinc-100'}`}><div className="w-6 h-6 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-xs">G</div><span className="font-semibold text-xs">GCash</span></button>
              <button onClick={() => setPaymentMethod('SPLIT')} className={`p-3 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${paymentMethod === 'SPLIT' ? 'border-purple-500 bg-purple-50' : 'border-zinc-100'}`}><div className="w-6 h-6 rounded-full bg-purple-100 flex items-center justify-center text-purple-600 font-bold text-xs">S</div><span className="font-semibold text-xs">Split</span></button>
            </div>
            {paymentMethod === 'GCASH' && (
               <div className="mb-6 animate-fade-in">
                 {storeSettings.gcashQr ? (
                    <div className="flex flex-col items-center mb-4 p-4 bg-blue-50 rounded-xl border-2 border-dashed border-blue-200">
                        <p className="text-xs font-bold text-blue-600 uppercase mb-2">Scan to Pay</p>
                        <button onClick={() => setIsQrZoomed(true)} className="w-40 h-40 bg-white p-2 rounded-lg shadow-sm cursor-zoom-in hover:scale-105 transition-transform" title="Click to enlarge"><img src={storeSettings.gcashQr} alt="GCash QR" className="w-full h-full object-contain" /></button>
                    </div>
                 ) : (
                    <div className="flex flex-col items-center mb-4 p-4 bg-gray-50 rounded-xl border-2 border-dashed border-gray-200 text-center"><CreditCard className="w-8 h-8 text-gray-400 mb-2" /><p className="text-xs font-bold text-gray-500 uppercase">No QR Code Available</p></div>
                 )}
                 <label className="text-xs font-bold text-gray-500 uppercase">Reference Number</label>
                 <input type="text" className="w-full border-b-2 border-zinc-200 py-2 focus:outline-none focus:border-blue-500 font-mono text-lg bg-white text-zinc-900 placeholder-zinc-300" placeholder="000 000 000" value={gcashRef} onChange={e => setGcashRef(e.target.value)} />
               </div>
            )}
            {paymentMethod === 'SPLIT' && (
                <div className="mb-6 animate-fade-in bg-purple-50 p-4 rounded-xl border border-purple-100">
                    <p className="text-xs font-bold text-purple-700 uppercase mb-3 text-center">Split Breakdown</p>
                    <div className="mb-3"><label className="text-xs font-bold text-gray-500 uppercase block mb-1">Cash</label><div className="relative"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 font-bold">₱</span><input type="number" className="w-full pl-8 pr-4 py-2 border border-zinc-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 font-mono text-lg bg-white text-zinc-900" placeholder="0.00" value={splitCashAmount} onChange={e => setSplitCashAmount(e.target.value)} /></div></div>
                    <div className="mb-3"><label className="text-xs font-bold text-gray-500 uppercase block mb-1">GCash</label><div className="w-full pl-4 pr-4 py-2 bg-purple-100 rounded-lg border border-purple-200 text-purple-800 font-mono text-lg font-bold">₱{Math.max(0, total - Number(splitCashAmount || 0)).toFixed(2)}</div></div>
                    <div><label className="text-xs font-bold text-gray-500 uppercase block mb-1">GCash Reference</label><input type="text" className="w-full py-2 border-b-2 border-zinc-300 bg-transparent focus:outline-none focus:border-purple-500 font-mono text-sm text-zinc-900 placeholder-zinc-400" placeholder="GCash Ref No." value={gcashRef} onChange={e => setGcashRef(e.target.value)} /></div>
                </div>
            )}
            </div>
            <div className="flex gap-3 mt-4 pt-4 border-t border-zinc-100">
              <Button variant="ghost" onClick={() => setIsCheckoutOpen(false)} className="flex-1">Cancel</Button>
              <Button onClick={handleFinalizeTransaction} className="flex-1 bg-black hover:bg-zinc-800">Confirm & Process</Button>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Zoomed QR & Receipt Preview Modals... (Included for completeness) */}
      <Dialog open={isQrZoomed} onClose={() => setIsQrZoomed(false)} className="relative z-[60] print:hidden">
        <div className="fixed inset-0 bg-black/90 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4" onClick={() => setIsQrZoomed(false)}>
            <Dialog.Panel className="relative max-w-lg w-full flex flex-col items-center animate-in fade-in zoom-in duration-200">
                <div className="bg-white p-4 rounded-3xl shadow-2xl w-full aspect-square flex items-center justify-center overflow-hidden">
                    {storeSettings.gcashQr && <img src={storeSettings.gcashQr} alt="GCash QR Full" className="w-full h-full object-contain" />}
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

      <Dialog open={receiptSuccessOpen} onClose={() => setReceiptSuccessOpen(false)} className="relative z-50 print:hidden">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-8 shadow-2xl font-mono text-sm relative text-zinc-900">
             <div className="flex flex-col items-center mb-6"><div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mb-2 animate-bounce"><Check className="w-6 h-6 text-green-600" /></div><h2 className="font-bold text-lg">Payment Successful</h2></div>
             <div className="space-y-4 mb-6">
                 <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-100 text-center"><p className="text-gray-500 text-xs uppercase mb-1">Total Paid</p><p className="text-2xl font-bold text-zinc-900">₱{lastTransaction?.total.toFixed(2)}</p></div>
             </div>
             <div className="flex gap-3">
                <Button onClick={() => setReceiptSuccessOpen(false)} variant="secondary" className="flex-1">Close</Button>
                <Button onClick={handleOpenPreview} className="flex-1 flex items-center gap-2 justify-center"><Printer className="w-4 h-4" /> Print Receipt</Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      <Dialog open={previewOpen} onClose={() => setPreviewOpen(false)} className="relative z-50 print:hidden">
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-zinc-800 rounded-2xl p-4 shadow-2xl relative flex flex-col h-[90vh]">
             <div className="flex justify-between items-center mb-4 text-white"><h3 className="font-bold text-lg flex items-center gap-2"><Printer className="w-5 h-5" /> Print Preview</h3><button onClick={() => setPreviewOpen(false)} className="p-2 hover:bg-zinc-700 rounded-full"><X className="w-5 h-5" /></button></div>
             <div className="bg-zinc-700/50 p-3 rounded-xl mb-4 flex items-center justify-between"><div className="flex items-center gap-2 text-white"><Settings className="w-4 h-4" /><span className="text-sm font-bold">Printer Device / Paper Size</span></div><div className="flex bg-zinc-900 rounded-lg p-1"><button onClick={() => setPaperSize('58mm')} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '58mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}>58mm (Small)</button><button onClick={() => setPaperSize('80mm')} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '80mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}>80mm (Standard)</button></div></div>
             <div className="flex-1 overflow-auto bg-zinc-700/50 rounded-xl p-6 flex justify-center items-start"><div className="shadow-2xl shadow-black/50 transition-all duration-300">{lastTransaction && <ReceiptTemplate transaction={lastTransaction} settings={storeSettings} paperSize={paperSize} isPreview={true} />}</div></div>
             <div className="mt-4 flex gap-3"><Button variant="secondary" className="flex-1 bg-zinc-700 text-white border-zinc-600 hover:bg-zinc-600 hover:text-white" onClick={() => setPreviewOpen(false)}>Close</Button><Button className="flex-1 bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/50" onClick={handleActualPrint}><Printer className="w-4 h-4 mr-2" /> Print Now</Button></div>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>

    {/* HIDDEN PRINT LAYOUT */}
    {lastTransaction && <div id="printable-content" className="hidden print:block fixed inset-0 bg-white z-[9999] p-2"><ReceiptTemplate transaction={lastTransaction} settings={storeSettings} paperSize={paperSize} /></div>}
    </>
  );
};

export default POS;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, CartItem, Category, Transaction, StoreSettings, Discount, GroomingAppointment, Role, Client, Pet } from '../types';
import Button from '../components/ui/Button';
import { Search, ShoppingBag, Trash2, Plus, Minus, CreditCard, Bone, Dog, Printer, Check, X, Settings, ArrowRight, Scissors, DollarSign, User, ChevronDown, Tag, Percent, Info, CheckCircle } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import ReceiptTemplate from '../components/ReceiptTemplate';
import { useNavigate } from 'react-router-dom';

// Helper for loose search matching
const normalizeText = (text: string) => text.toLowerCase().replace(/[^a-z0-9]/g, '');

// Reusable Cart UI Component
interface CartPanelProps {
    cart: CartItem[];
    updateQuantity: (id: string, delta: number) => void;
    removeFromCart: (id: string) => void;
    openDiscountModal: () => void;
    openBreakdownModal: (item: CartItem) => void; // New: Open item specific breakdown
    subtotal: number;
    discountAmount: number;
    total: number;
    onCheckout: () => void;
    onClose?: () => void; // For mobile modal
}

const CartPanel: React.FC<CartPanelProps> = ({ 
    cart, updateQuantity, removeFromCart, openDiscountModal, openBreakdownModal,
    subtotal, discountAmount, total, onCheckout, onClose
}) => {

    return (
        <div className="flex flex-col h-full bg-white lg:rounded-3xl shadow-xl border border-zinc-100 overflow-hidden">
            <div className="p-5 border-b border-zinc-100 bg-zinc-50 lg:rounded-t-3xl flex justify-between items-center">
                <h2 className="font-bold text-lg flex items-center gap-2 text-zinc-900">
                    <ShoppingBag className="w-5 h-5" />
                    Current Order
                </h2>
                {onClose && (
                    <button onClick={onClose} className="lg:hidden p-2 text-gray-500 hover:bg-zinc-200 rounded-full">
                        <X className="w-5 h-5" />
                    </button>
                )}
            </div>

            <div className="flex-1 overflow-auto p-4 space-y-3">
                {cart.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-gray-400">
                        <ShoppingBag className="w-12 h-12 mb-2 opacity-20" />
                        <p>Cart is empty</p>
                    </div>
                ) : (
                    cart.map(item => {
                        const isMaxStock = !item.isService && item.quantity >= item.stock;
                        const discounts = item.appliedDiscounts || [];
                        const hasDiscount = discounts.length > 0;

                        // Calculate display price per unit with discount
                        const originalTotal = item.price * item.quantity;
                        let totalDiscountValue = 0;

                        // Additive Discount Calculation
                        discounts.forEach(d => {
                            if (d.type === 'PERCENTAGE') {
                                totalDiscountValue += originalTotal * (d.value / 100);
                            } else {
                                totalDiscountValue += d.value * item.quantity;
                            }
                        });

                        // Ensure we don't discount more than the price
                        totalDiscountValue = Math.min(totalDiscountValue, originalTotal);

                        // Construct tooltip text
                        const discountTooltip = discounts.map(d => `${d.name} (${d.type === 'PERCENTAGE' ? d.value + '%' : '₱'+d.value})`).join(', ');

                        return (
                            <div key={item.id} className={`flex items-center gap-3 bg-white p-3 rounded-2xl border shadow-sm relative group ${hasDiscount ? 'border-green-200 bg-green-50/30' : 'border-zinc-100'}`}>
                                <div className="flex-1">
                                    <div className="flex items-center gap-2">
                                        <p className="font-semibold text-sm text-zinc-900 line-clamp-1">{item.name}</p>
                                        {isMaxStock && <span className="text-[10px] font-bold bg-red-100 text-red-600 px-1.5 py-0.5 rounded">MAX</span>}

                                        {/* Discount Icon Badge (Clickable) */}
                                        {hasDiscount && (
                                            <button 
                                                onClick={() => openBreakdownModal(item)}
                                                className="flex items-center gap-1 bg-green-100 text-green-700 px-2 py-0.5 rounded-full text-[10px] font-bold hover:bg-green-200 transition-colors"
                                                title={discountTooltip}
                                            >
                                                <Tag className="w-3 h-3" />
                                                <span>{discounts.length > 1 ? `${discounts.length} Promos` : discounts[0].name}</span>
                                            </button>
                                        )}
                                    </div>
                                    <div className="flex gap-2 items-end">
                                        <p className="text-xs text-gray-500">₱{item.price} each</p>
                                        {hasDiscount && (
                                            <p className="text-xs text-green-600 font-bold">(-₱{totalDiscountValue.toFixed(2)})</p>
                                        )}
                                    </div>
                                </div>
                                <div className="flex items-center gap-1 bg-zinc-100 rounded-xl p-1">
                                    <button
                                        onClick={() => updateQuantity(item.id, -1)}
                                        className="w-8 h-8 flex items-center justify-center bg-white rounded-lg shadow-sm hover:bg-zinc-50 active:scale-95 transition-all text-zinc-900"
                                    >
                                        <Minus className="w-4 h-4" />
                                    </button>
                                    <span className="text-sm font-bold w-8 text-center text-zinc-900">{item.quantity}</span>
                                    <button
                                        onClick={() => updateQuantity(item.id, 1)}
                                        disabled={isMaxStock}
                                        className={`w-8 h-8 flex items-center justify-center bg-white rounded-lg shadow-sm transition-all text-zinc-900 ${isMaxStock ? 'opacity-50 cursor-not-allowed' : 'hover:bg-zinc-50 active:scale-95'
                                            }`}
                                    >
                                        <Plus className="w-4 h-4" />
                                    </button>
                                </div>

                                <button
                                    onClick={() => removeFromCart(item.id)}
                                    className="w-8 h-8 flex items-center justify-center text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors ml-1"
                                    title="Remove Item"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        )
                    })
                )}
            </div>

            <div className="p-5 bg-zinc-900 text-white lg:rounded-b-3xl mt-auto shadow-inner">
                <div className="mb-4">
                    <button 
                        onClick={openDiscountModal}
                        className="w-full bg-zinc-800 border border-zinc-700 hover:bg-zinc-700 text-white rounded-xl p-3 text-sm font-bold flex items-center justify-center gap-2 transition-all"
                        disabled={cart.length === 0}
                    >
                        <Percent className="w-4 h-4" /> Apply Discount / Promo
                    </button>
                </div>

                <div className="space-y-2 text-sm mb-4 border-t border-zinc-800 pt-4">
                    <div className="flex justify-between text-gray-400"><span>Subtotal</span><span>₱{subtotal.toFixed(2)}</span></div>
                    <div className="flex justify-between text-gray-400"><span>Total Discount</span><span className="text-green-400">-₱{discountAmount.toFixed(2)}</span></div>
                    <div className="flex justify-between text-white font-bold text-lg pt-2 border-t border-zinc-700">
                        <span>Total</span>
                        <span>₱{total.toFixed(2)}</span>
                    </div>
                </div>

                <Button
                    variant="secondary"
                    className="w-full font-bold text-lg py-3 border-none hover:bg-zinc-200"
                    disabled={cart.length === 0}
                    onClick={onCheckout}
                >
                    Checkout
                </Button>
            </div>
        </div>
    );
}

const POS: React.FC = () => {
  const { products, discounts, addTransaction, addAppointment, currentUser, productCategories, serviceCategories, storeSettings, clients, users } = useStore();
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');

  const navigate = useNavigate();

  // New: Tab state for splitting Products and Services
  const [activeTab, setActiveTab] = useState<'PRODUCTS' | 'SERVICES'>('PRODUCTS');
  const [activeCategory, setActiveCategory] = useState<string | 'ALL'>('ALL');

  // Checkout Modals
  const [showGroomingModal, setShowGroomingModal] = useState(false);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);

  // Discount Management
  const [isDiscountManagerOpen, setIsDiscountManagerOpen] = useState(false);
  const [selectedDiscountToApply, setSelectedDiscountToApply] = useState<Discount | null>(null);
  const [itemSelectionForDiscount, setItemSelectionForDiscount] = useState<string[]>([]); // Array of CartItem IDs

  // Item Specific Discount Breakdown
  const [breakdownItem, setBreakdownItem] = useState<CartItem | null>(null);

  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'GCASH' | 'SPLIT'>('CASH');
  const [gcashRef, setGcashRef] = useState('');
  const [splitCashAmount, setSplitCashAmount] = useState<string>(''); 

  // Mobile UI States
  const [isMobileCartOpen, setIsMobileCartOpen] = useState(false);

  // Modal States
  const [receiptSuccessOpen, setReceiptSuccessOpen] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [isQrZoomed, setIsQrZoomed] = useState(false);

  // Printer Settings
  const [paperSize, setPaperSize] = useState<'58mm' | '80mm'>('80mm');

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);

  // Grooming Details State
  const [groomingFormData, setGroomingFormData] = useState({
      ownerName: '', contactNumber: '', email: '', petName: '', petBreed: '', petColor: '', weightSize: '', groomerId: '', hairCut: ''
  });
  // Client Autocomplete Logic for POS
  const [filteredClients, setFilteredClients] = useState<Client[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [showClientSuggestions, setShowClientSuggestions] = useState(false);
  const clientDropdownRef = useRef<HTMLDivElement>(null);

  // Pet Autocomplete Logic
  const [showPetSuggestions, setShowPetSuggestions] = useState(false);
  const petDropdownRef = useRef<HTMLDivElement>(null);

  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');

  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (clientDropdownRef.current && !clientDropdownRef.current.contains(event.target as Node)) {
              setShowClientSuggestions(false);
          }
          if (petDropdownRef.current && !petDropdownRef.current.contains(event.target as Node)) {
              setShowPetSuggestions(false);
          }
      };
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // --- CLIENT & PET LOGIC (SAME AS BEFORE) ---
  const handleOwnerSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setGroomingFormData(prev => ({...prev, ownerName: val}));
      if(selectedClient && selectedClient.name !== val) setSelectedClient(null);
      if (val.length > 0) {
          const normalizedSearch = normalizeText(val);
          const matches = clients.filter(c => 
              normalizeText(c.name).includes(normalizedSearch) || 
              (c.contactNumber && c.contactNumber.replace(/\D/g,'').includes(normalizedSearch))
          );
          setFilteredClients(matches.slice(0, 5));
          setShowClientSuggestions(true);
      } else {
          setShowClientSuggestions(false);
      }
  };

  const selectClient = (client: Client) => {
      setGroomingFormData(prev => ({
          ...prev,
          ownerName: client.name,
          contactNumber: client.contactNumber,
          email: client.email || '',
          petName: '', petBreed: '', petColor: '', weightSize: ''
      }));
      setSelectedClient(client);
      setShowClientSuggestions(false);
  };

  const handlePetNameFocus = () => {
      if (selectedClient && selectedClient.pets && selectedClient.pets.length > 0) {
          setShowPetSuggestions(true);
      }
  };

  const selectPet = (pet: Pet) => {
      setGroomingFormData(prev => ({
          ...prev,
          petName: pet.name,
          petBreed: pet.breed || '',
          petColor: pet.color || '',
          weightSize: pet.weightSize || ''
      }));
      setShowPetSuggestions(false);
  };

  // Determine which categories to show based on active tab
  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;

  // Filtering Logic
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const isService = p.isService;
      if (activeTab === 'PRODUCTS' && isService) return false;
      if (activeTab === 'SERVICES' && !isService) return false;
      const normalizedSearch = normalizeText(search);
      const normalizedName = normalizeText(p.name);
      const matchesSearch = normalizedName.includes(normalizedSearch);
      const matchesCategory = activeCategory === 'ALL' || p.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [products, search, activeCategory, activeTab]);

  // Cart Logic
  const addToCart = (product: Product) => {
    if (!product.isService && product.stock <= 0) return;

    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (!product.isService && existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1, appliedDiscounts: [] }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          if (newQty < 1) return item;
          if (!item.isService && newQty > item.stock) return item;
          return { ...item, quantity: newQty };
        }
        return item;
      });
    });
  };

  // --- DISCOUNT MANAGEMENT ---

  // Removes a specific discount from a cart item
  const removeSpecificDiscount = (itemId: string, discountId: string) => {
      setCart(prev => prev.map(item => {
          if (item.id === itemId) {
              return { 
                  ...item, 
                  appliedDiscounts: (item.appliedDiscounts || []).filter(d => d.id !== discountId)
              };
          }
          return item;
      }));
      // Also update the breakdown modal view if it's open for this item
      if (breakdownItem && breakdownItem.id === itemId) {
          setBreakdownItem(prev => prev ? {
              ...prev,
              appliedDiscounts: (prev.appliedDiscounts || []).filter(d => d.id !== discountId)
          } : null);
      }
  };

  const handleOpenDiscountManager = () => {
      setSelectedDiscountToApply(null);
      setItemSelectionForDiscount([]);
      setIsDiscountManagerOpen(true);
  };

  const handleToggleItemForDiscount = (itemId: string) => {
      // Toggle logic
      setItemSelectionForDiscount(prev => 
          prev.includes(itemId) ? prev.filter(id => id !== itemId) : [...prev, itemId]
      );
  };

  const handleSelectAllForDiscount = () => {
      // Filter out items that already have this discount to find eligible ones
      const eligibleItems = cart.filter(item => 
          !item.appliedDiscounts?.some(d => d.id === selectedDiscountToApply?.id)
      );

      const eligibleIds = eligibleItems.map(i => i.id);

      // If all eligible are selected, deselect. Else select all eligible.
      const allSelected = eligibleIds.length > 0 && eligibleIds.every(id => itemSelectionForDiscount.includes(id));

      if (allSelected) {
          setItemSelectionForDiscount([]);
      } else {
          setItemSelectionForDiscount(eligibleIds);
      }
  };

  const applySelectedDiscount = () => {
      if (!selectedDiscountToApply) return;

      setCart(prev => prev.map(item => {
          if (itemSelectionForDiscount.includes(item.id)) {
              // Append to existing array, ensure no duplicates (safety check)
              const existing = item.appliedDiscounts || [];
              if (existing.some(d => d.id === selectedDiscountToApply.id)) {
                  return item;
              }
              return { ...item, appliedDiscounts: [...existing, selectedDiscountToApply] };
          }
          return item;
      }));

      setIsDiscountManagerOpen(false);
  };

  // --- TOTALS CALCULATION (Updated for Multiple Discounts) ---
  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

  const discountAmount = cart.reduce((sum, item) => {
      const discounts = item.appliedDiscounts || [];
      if (discounts.length === 0) return sum;

      const originalItemTotal = item.price * item.quantity;
      let itemDiscount = 0;

      discounts.forEach(d => {
          if (d.type === 'PERCENTAGE') {
              itemDiscount += originalItemTotal * (d.value / 100);
          } else {
              itemDiscount += d.value * item.quantity;
          }
      });

      // Cap discount at item total price (can't go below zero)
      return sum + Math.min(itemDiscount, originalItemTotal);
  }, 0);

  const total = Math.max(0, subtotal - discountAmount);
  const vatRate = storeSettings.vatRate / 100;
  const vatAmount = (total / (1 + vatRate)) * vatRate; 

  // --- CHECKOUT HANDLERS ---
  const handleCheckoutClick = () => {
      const hasService = cart.some(item => item.isService);
      if (hasService) {
          setShowGroomingModal(true);
      } else {
          setIsCheckoutOpen(true);
      }
  };

  const handleProceedToPayment = (e: React.FormEvent) => {
      e.preventDefault();
      if (!groomingFormData.ownerName || !groomingFormData.petName || !groomingFormData.groomerId) {
          alert("Please fill in Owner Name, Pet Name, and select a Groomer.");
          return;
      }
      setShowGroomingModal(false);
      setIsCheckoutOpen(true);
  };

  const handleFinalizeTransaction = () => {
    if (paymentMethod === 'GCASH' && !gcashRef) {
      alert('Please enter GCash Reference Number');
      return;
    }
    if (paymentMethod === 'SPLIT') {
        const cash = Number(splitCashAmount);
        if (isNaN(cash) || cash <= 0) { alert("Please enter a valid Cash amount"); return; }
        if (cash >= total) { alert("Cash amount covers the total. Please switch to 'CASH' payment method."); return; }
        if (!gcashRef) { alert('Please enter GCash Reference Number for the balance'); return; }
    }

    // Create Transaction
    const transaction: Transaction = {
      id: Date.now().toString(),
      items: [...cart],
      subtotal,
      vat: vatAmount,
      total,
      discount: discountAmount,
      paymentMethod,
      gcashRef: (paymentMethod === 'GCASH' || paymentMethod === 'SPLIT') ? gcashRef : undefined,
      cashReceived: paymentMethod === 'SPLIT' ? Number(splitCashAmount) : undefined,
      date: new Date().toISOString(),
      cashierId: currentUser?.id || 'unknown',
    };

    addTransaction(transaction);
    setLastTransaction(transaction);

    // Appointments Logic
    const serviceItems = cart.filter(i => i.isService);
    let hasServices = false;

    if (serviceItems.length > 0) {
        hasServices = true;
        serviceItems.forEach(item => {
            for(let i=0; i < item.quantity; i++) {
                const now = new Date();
                const instructions = groomingFormData.hairCut 
                    ? `${groomingFormData.hairCut} (Paid at POS Tx:#${transaction.id.slice(-4)})`
                    : `Paid at POS (Tx: #${transaction.id.slice(-4)})`;

                const newApt: GroomingAppointment = {
                    id: Date.now().toString() + Math.random().toString().slice(2, 5),
                    petName: groomingFormData.petName,
                    petBreed: groomingFormData.petBreed,
                    petColor: groomingFormData.petColor,
                    weightSize: groomingFormData.weightSize,
                    ownerName: groomingFormData.ownerName,
                    contactNumber: groomingFormData.contactNumber,
                    email: groomingFormData.email,
                    groomerId: groomingFormData.groomerId,
                    serviceId: item.id,
                    hairCut: instructions,
                    date: now.toLocaleDateString('en-CA', {timeZone: 'Asia/Manila'}),
                    time: now.toLocaleTimeString('en-US', {hour12: false, hour: '2-digit', minute:'2-digit', timeZone: 'Asia/Manila'}),
                    status: 'SCHEDULED',
                };
                addAppointment(newApt);
            }
        });
    }

    setCart([]);
    setIsCheckoutOpen(false);
    setIsMobileCartOpen(false); 
    setGcashRef('');
    setSplitCashAmount('');
    setGroomingFormData({ ownerName: '', contactNumber: '', email: '', petName: '', petBreed: '', petColor: '', weightSize: '', groomerId: '', hairCut: '' });
    setSelectedClient(null);

    if (hasServices) {
        navigate('/grooming'); 
    } else {
        setReceiptSuccessOpen(true); 
    }
  };

  const handleActualPrint = () => {
    setTimeout(() => { window.print(); }, 500);
  };

  const handleOpenPreview = () => {
      setPreviewOpen(true);
  };

  const handleTabChange = (tab: 'PRODUCTS' | 'SERVICES') => {
      setActiveTab(tab);
      setActiveCategory('ALL');
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium text-sm";
  const labelClass = "text-xs font-bold text-gray-500 uppercase";

  return (
    <>
    <div className="flex flex-col lg:flex-row h-[calc(100vh-80px)] lg:h-[calc(100vh-100px)] gap-6 print:hidden relative">
      {/* Product Grid */}
      <div className="flex-1 flex flex-col bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden h-full">
        {/* Header */}
        <div className="p-4 border-b border-zinc-100 space-y-4">
          <div className="flex gap-4">
             <button onClick={() => handleTabChange('PRODUCTS')} className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${activeTab === 'PRODUCTS' ? 'bg-black text-white shadow-lg' : 'bg-zinc-50 text-gray-500 hover:bg-zinc-100 border border-zinc-200'}`}>
                <Bone className="w-5 h-5" /> Products
             </button>
             <button onClick={() => handleTabChange('SERVICES')} className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${activeTab === 'SERVICES' ? 'bg-black text-white shadow-lg' : 'bg-zinc-50 text-gray-500 hover:bg-zinc-100 border border-zinc-200'}`}>
                <Scissors className="w-5 h-5" /> Services
             </button>
          </div>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input type="text" placeholder={`Search ${activeTab === 'PRODUCTS' ? 'products' : 'services'}...`} className="w-full pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black" value={search} onChange={e => setSearch(e.target.value)} />
          </div>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
            <Button size="sm" variant={activeCategory === 'ALL' ? 'primary' : 'secondary'} onClick={() => setActiveCategory('ALL')}>All</Button>
            {currentCategories.map(cat => (
              <Button key={cat} size="sm" variant={activeCategory === cat ? 'primary' : 'secondary'} onClick={() => setActiveCategory(cat)}>{cat}</Button>
            ))}
          </div>
        </div>

        {/* Grid */}
        <div className="flex-1 overflow-auto p-4 grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 content-start pb-24 lg:pb-4">
          {filteredProducts.map(product => {
            const isOutOfStock = !product.isService && product.stock <= 0;
            return (
            <button key={product.id} onClick={() => !isOutOfStock && addToCart(product)} disabled={isOutOfStock} className={`group flex flex-col items-center text-center p-4 rounded-2xl border transition-all duration-200 ${isOutOfStock ? 'border-zinc-100 bg-zinc-50 opacity-60 cursor-not-allowed' : 'border-zinc-100 hover:border-black hover:shadow-lg bg-zinc-50/50'}`}>
              <div className={`w-16 h-16 bg-white rounded-full flex items-center justify-center mb-3 shadow-sm transition-transform ${!isOutOfStock && 'group-hover:scale-110'}`}>
                {product.isService ? <Scissors className="w-8 h-8 text-black" /> : <Bone className="w-8 h-8 text-black" />}
              </div>
              <h3 className="font-semibold text-sm line-clamp-2 min-h-[40px] text-zinc-900">{product.name}</h3>
              <p className={`text-xs mb-2 ${isOutOfStock ? 'text-red-500 font-bold' : 'text-gray-500'}`}>
                {product.isService ? 'Service' : (isOutOfStock ? 'Out of Stock' : `${product.stock} in stock`)}
              </p>
              <span className={`text-xs font-bold px-2 py-1 rounded-lg ${isOutOfStock ? 'bg-gray-200 text-gray-500' : 'bg-black text-white'}`}>₱{product.price}</span>
            </button>
          )})}
          {filteredProducts.length === 0 && <div className="col-span-full flex flex-col items-center justify-center text-gray-400 py-10"><Bone className="w-10 h-10 mb-2 opacity-20" /><p>No results found</p></div>}
        </div>
      </div>

      {/* Desktop Cart */}
      <div className="hidden lg:block w-96 h-full">
         <CartPanel 
            cart={cart} updateQuantity={updateQuantity} removeFromCart={removeFromCart}
            openDiscountModal={handleOpenDiscountManager} openBreakdownModal={(item) => setBreakdownItem(item)}
            subtotal={subtotal} discountAmount={discountAmount} total={total} onCheckout={handleCheckoutClick}
         />
      </div>

      {/* Mobile Floating Bar */}
      {cart.length > 0 && (
          <div className="lg:hidden fixed bottom-4 left-4 right-4 z-40 animate-slide-up print:hidden">
              <button onClick={() => setIsMobileCartOpen(true)} className="w-full bg-black text-white p-4 rounded-2xl shadow-2xl flex justify-between items-center active:scale-95 transition-transform">
                  <div className="flex items-center gap-3">
                      <div className="bg-white text-black font-bold w-8 h-8 rounded-full flex items-center justify-center text-sm">{totalItems}</div>
                      <span className="font-bold text-sm">View Cart</span>
                  </div>
                  <div className="flex items-center gap-2">
                      <span className="font-bold text-lg">₱{total.toFixed(2)}</span>
                      <ArrowRight className="w-5 h-5" />
                  </div>
              </button>
          </div>
      )}

      {/* Mobile Cart Modal */}
      <Dialog open={isMobileCartOpen} onClose={() => setIsMobileCartOpen(false)} className="relative z-50 lg:hidden print:hidden">
         <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
         <div className="fixed inset-x-0 bottom-0 flex justify-center">
            <Dialog.Panel className="w-full max-w-lg bg-white rounded-t-3xl shadow-2xl h-[85vh] flex flex-col animate-slide-up">
                 <div className="w-full flex justify-center pt-3 pb-1" onClick={() => setIsMobileCartOpen(false)}><div className="w-12 h-1.5 bg-zinc-200 rounded-full"></div></div>
                 <CartPanel 
                    cart={cart} updateQuantity={updateQuantity} removeFromCart={removeFromCart}
                    openDiscountModal={handleOpenDiscountManager} openBreakdownModal={(item) => setBreakdownItem(item)}
                    subtotal={subtotal} discountAmount={discountAmount} total={total}
                    onCheckout={handleCheckoutClick} onClose={() => setIsMobileCartOpen(false)}
                />
            </Dialog.Panel>
         </div>
      </Dialog>

      {/* DISCOUNT MANAGER MODAL */}
      <Dialog open={isDiscountManagerOpen} onClose={() => setIsDiscountManagerOpen(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-2xl bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-slide-up">
            <div className="p-5 border-b border-zinc-100 flex justify-between items-center bg-zinc-50">
                <h3 className="text-xl font-bold text-zinc-900 flex items-center gap-2"><Percent className="w-6 h-6 text-black" /> Apply Discount</h3>
                <button onClick={() => setIsDiscountManagerOpen(false)} className="text-gray-400 hover:text-black"><X className="w-6 h-6" /></button>
            </div>
            <div className="flex flex-col md:flex-row h-full overflow-hidden">
                <div className="w-full md:w-1/3 border-r border-zinc-100 flex flex-col bg-zinc-50">
                    <div className="p-4 border-b border-zinc-100"><p className="text-xs font-bold text-gray-500 uppercase">1. Choose Discount</p></div>
                    <div className="flex-1 overflow-y-auto p-2 space-y-2">
                        {discounts.filter(d => d.active).map(discount => (
                            <button key={discount.id} onClick={() => { setSelectedDiscountToApply(discount); setItemSelectionForDiscount([]); }}
                                className={`w-full text-left p-3 rounded-xl border transition-all ${selectedDiscountToApply?.id === discount.id ? 'bg-black text-white border-black shadow-md' : 'bg-white border-zinc-200 text-zinc-700 hover:border-zinc-400'}`}>
                                <div className="font-bold text-sm">{discount.name}</div>
                                <div className={`text-xs ${selectedDiscountToApply?.id === discount.id ? 'text-zinc-300' : 'text-gray-500'}`}>{discount.type === 'PERCENTAGE' ? `${discount.value}% Off` : `₱${discount.value} Off`}</div>
                            </button>
                        ))}
                    </div>
                </div>
                <div className="flex-1 flex flex-col bg-white">
                    <div className="p-4 border-b border-zinc-100 flex justify-between items-center">
                        <p className="text-xs font-bold text-gray-500 uppercase">2. Select Eligible Items</p>
                        <button onClick={handleSelectAllForDiscount} className="text-xs font-bold text-blue-600 hover:underline">Select All</button>
                    </div>
                    <div className="flex-1 overflow-y-auto p-4 space-y-2">
                        {!selectedDiscountToApply ? (
                            <div className="h-full flex flex-col items-center justify-center text-gray-400">
                                <Tag className="w-12 h-12 mb-3 opacity-20" />
                                <p className="text-sm">Select a discount from the left to view eligible items.</p>
                            </div>
                        ) : (
                            <>
                                {cart.map(item => {
                                    // Check if this specific discount is already applied
                                    const alreadyApplied = item.appliedDiscounts?.some(d => d.id === selectedDiscountToApply.id);

                                    // Only show valid items (that don't have it yet) OR show them disabled?
                                    // User request: "lalabas nalang doon ung mga hindi pa applied na discount na items"
                                    if (alreadyApplied) return null;

                                    const isSelected = itemSelectionForDiscount.includes(item.id);
                                    return (
                                        <div key={item.id} onClick={() => handleToggleItemForDiscount(item.id)} className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${isSelected ? 'border-green-500 bg-green-50' : 'border-zinc-100 hover:border-zinc-300'}`}>
                                            <div className={`w-5 h-5 rounded-full border flex items-center justify-center ${isSelected ? 'bg-green-500 border-green-500' : 'bg-white border-gray-300'}`}>
                                                {isSelected && <Check className="w-3 h-3 text-white" />}
                                            </div>
                                            <div className="flex-1">
                                                <p className="font-bold text-sm text-zinc-900">{item.name}</p>
                                                <div className="flex justify-between items-center mt-1">
                                                    <span className="text-xs text-gray-500">Qty: {item.quantity} • ₱{item.price}</span>
                                                    {item.appliedDiscounts && item.appliedDiscounts.length > 0 && (
                                                        <span className="text-[10px] bg-orange-100 text-orange-700 px-2 py-0.5 rounded font-bold">
                                                            Stacking on: {item.appliedDiscounts.length} Promos
                                                        </span>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}
                                {selectedDiscountToApply && cart.every(i => i.appliedDiscounts?.some(d => d.id === selectedDiscountToApply.id)) && (
                                    <div className="text-center p-8 text-gray-400 text-xs">
                                        <CheckCircle className="w-8 h-8 mx-auto mb-2 opacity-20"/>
                                        This discount is applied to all items!
                                    </div>
                                )}
                            </>
                        )}
                    </div>
                    <div className="p-4 border-t border-zinc-100 bg-zinc-50">
                        <Button disabled={!selectedDiscountToApply || itemSelectionForDiscount.length === 0} onClick={applySelectedDiscount} className="w-full">
                            Apply {selectedDiscountToApply?.name} ({itemSelectionForDiscount.length})
                        </Button>
                    </div>
                </div>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* ITEM DISCOUNT BREAKDOWN MODAL */}
      <Dialog open={!!breakdownItem} onClose={() => setBreakdownItem(null)} className="relative z-[70]">
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-2xl p-6 shadow-2xl animate-fade-in">
                <div className="flex justify-between items-center mb-4 border-b border-zinc-100 pb-3">
                    <h3 className="font-bold text-lg text-zinc-900">Discount Breakdown</h3>
                    <button onClick={() => setBreakdownItem(null)} className="text-gray-400 hover:text-black"><X className="w-5 h-5"/></button>
                </div>

                <div className="mb-4">
                    <p className="font-bold text-sm text-zinc-800">{breakdownItem?.name}</p>
                    <p className="text-xs text-gray-500">Original Price: ₱{breakdownItem ? (breakdownItem.price * breakdownItem.quantity).toFixed(2) : 0}</p>
                </div>

                <div className="space-y-2 mb-4 max-h-60 overflow-y-auto custom-scrollbar">
                    {breakdownItem?.appliedDiscounts?.map(discount => {
                        const amount = discount.type === 'PERCENTAGE' 
                            ? (breakdownItem.price * breakdownItem.quantity) * (discount.value / 100)
                            : discount.value * breakdownItem.quantity;

                        return (
                            <div key={discount.id} className="flex justify-between items-center bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                                <div>
                                    <p className="font-bold text-sm text-zinc-900">{discount.name}</p>
                                    <p className="text-xs text-green-600 font-bold">
                                        -{discount.type === 'PERCENTAGE' ? discount.value + '%' : '₱' + discount.value} (Save ₱{amount.toFixed(2)})
                                    </p>
                                </div>
                                <button 
                                    onClick={() => removeSpecificDiscount(breakdownItem.id, discount.id)}
                                    className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Remove this discount"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        );
                    })}
                    {(!breakdownItem?.appliedDiscounts || breakdownItem.appliedDiscounts.length === 0) && (
                        <p className="text-center text-xs text-gray-400 italic py-4">No discounts applied to this item.</p>
                    )}
                </div>

                <Button variant="secondary" onClick={() => setBreakdownItem(null)} className="w-full">Done</Button>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* GROOMING MODAL (Same as previous) */}
      <Dialog open={showGroomingModal} onClose={() => setShowGroomingModal(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh] animate-slide-up">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">Walk-in Grooming Details</Dialog.Title>
            <form onSubmit={handleProceedToPayment} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">
              <div className="space-y-3">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><User className="w-3 h-3" /> Owner & Pet</h4>
                  <div className="relative" ref={clientDropdownRef}>
                      <label className={labelClass}>Owner Name</label>
                      <input required className={`${inputClass} pl-9`} value={groomingFormData.ownerName} onChange={handleOwnerSearch} onFocus={(e) => handleOwnerSearch(e)} placeholder="Search or type new..." autoComplete="off"/>
                      <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                      {showClientSuggestions && filteredClients.length > 0 && (
                          <div className="absolute z-50 w-full bg-white mt-2 rounded-2xl shadow-xl border border-zinc-100 overflow-hidden ring-1 ring-black/5 max-h-60 overflow-y-auto custom-scrollbar">
                              {filteredClients.map(client => (
                                  <div key={client.id} onClick={() => selectClient(client)} className="p-3.5 hover:bg-zinc-50 cursor-pointer border-b border-zinc-50 last:border-0 flex justify-between items-center group">
                                      <div><p className="text-sm font-bold text-zinc-900">{client.name}</p><p className="text-xs text-gray-500">{client.contactNumber}</p></div>
                                      <ChevronDown className="-rotate-90 w-4 h-4 text-gray-300" />
                                  </div>
                              ))}
                          </div>
                      )}
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div><label className={labelClass}>Contact #</label><input className={inputClass} value={groomingFormData.contactNumber} onChange={e => setGroomingFormData({...groomingFormData, contactNumber: e.target.value})} placeholder="09XX..." /></div>
                    <div><label className={labelClass}>Email (Optional)</label><input type="email" className={inputClass} value={groomingFormData.email} onChange={e => setGroomingFormData({...groomingFormData, email: e.target.value})} placeholder="email@..." /></div>
                  </div>
                  <div className="grid grid-cols-2 gap-4 pt-2">
                    <div className="relative" ref={petDropdownRef}>
                        <label className={labelClass}>Pet Name</label>
                        <input required className={inputClass} value={groomingFormData.petName} onChange={e => {setGroomingFormData({...groomingFormData, petName: e.target.value}); if (selectedClient && selectedClient.pets?.length) setShowPetSuggestions(true);}} onFocus={handlePetNameFocus} placeholder="Pet's Name" autoComplete="off"/>
                        {showPetSuggestions && selectedClient && selectedClient.pets.length > 0 && (
                            <div className="absolute z-50 w-full bg-white mt-2 rounded-2xl shadow-xl border border-zinc-100 overflow-hidden ring-1 ring-black/5 animate-in fade-in slide-in-from-top-2 duration-200">
                                <div className="p-2.5 bg-zinc-50 text-[10px] text-gray-400 font-bold uppercase tracking-wider border-b border-zinc-100">{selectedClient.name}'s Pets</div>
                                {selectedClient.pets.filter(p => normalizeText(p.name).includes(normalizeText(groomingFormData.petName || ''))).map(pet => (
                                    <div key={pet.id} onClick={() => selectPet(pet)} className="p-3.5 hover:bg-zinc-50 cursor-pointer border-b border-zinc-50 last:border-0 flex justify-between items-center group">
                                        <div><p className="text-sm font-bold text-zinc-900">{pet.name}</p><p className="text-xs text-gray-500">{pet.breed}</p></div><Check className="w-4 h-4 text-green-500 opacity-0 group-hover:opacity-100 transition-opacity" />
                                    </div>
                                ))}
                                <div className="p-3.5 hover:bg-blue-50 cursor-pointer text-blue-600 font-bold text-xs flex items-center gap-2 border-t border-zinc-100 transition-colors" onClick={() => setShowPetSuggestions(false)}><Plus className="w-3 h-3" /> Add New Pet "{groomingFormData.petName}"</div>
                            </div>
                        )}
                    </div>
                    <div><label className={labelClass}>Breed</label><input className={inputClass} value={groomingFormData.petBreed} onChange={e => setGroomingFormData({...groomingFormData, petBreed: e.target.value})} placeholder="Breed" /></div>
                  </div>
              </div>
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Scissors className="w-3 h-3" /> Assignment</h4>
                  <div>
                    <label className={labelClass}>Assign Groomer</label>
                    <select required className={inputClass} value={groomingFormData.groomerId} onChange={e => setGroomingFormData({...groomingFormData, groomerId: e.target.value})} disabled={groomers.length === 0}>
                        <option value="">{groomers.length === 0 ? 'No Groomers Available' : 'Select Groomer'}</option>
                        {groomers.map(g => <option key={g.id} value={g.name}>{g.name}</option>)}
                    </select>
                  </div>
              </div>
              <div className="flex gap-3 pt-4 border-t border-zinc-100">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setShowGroomingModal(false)}>Back to Cart</Button>
                <Button type="submit" className="flex-1" disabled={!groomingFormData.ownerName || !groomingFormData.petName || !groomingFormData.groomerId}>Proceed to Payment</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* CHECKOUT & RECEIPT MODALS (Unchanged logic, just keeping structure) */}
      <Dialog open={isCheckoutOpen} onClose={() => setIsCheckoutOpen(false)} className="relative z-50 print:hidden">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
