            <div className="bg-zinc-50 rounded-xl p-4 mb-6 space-y-2">
              <div className="flex justify-between text-sm text-zinc-600"><span>Items ({cart.reduce((acc, i) => acc + i.quantity, 0)})</span><span>₱{subtotal.toFixed(2)}</span></div>
              <div className="flex justify-between text-sm text-zinc-600"><span>Discount Applied</span><span className="text-green-500 font-bold">-₱{discountAmount.toFixed(2)}</span></div>
              <div className="flex justify-between text-sm text-zinc-600"><span>VAT ({storeSettings.vatRate}% Included)</span><span>₱{vatAmount.toFixed(2)}</span></div>
              <div className="flex justify-between font-bold text-lg text-zinc-900 border-t border-zinc-200 pt-2 mt-2"><span>TOTAL TO PAY</span><span>₱{total.toFixed(2)}</span></div>
            </div>
            <p className="text-sm font-bold text-gray-700 mb-2">Select Payment Method</p>
            <div className="grid grid-cols-3 gap-3 mb-6">
              <button onClick={() => setPaymentMethod('CASH')} className={`p-3 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${paymentMethod === 'CASH' ? 'border-black bg-zinc-50' : 'border-zinc-100'}`}><div className="w-6 h-6 rounded-full bg-green-100 flex items-center justify-center text-green-600 font-bold text-xs">₱</div><span className="font-semibold text-xs">Cash</span></button>
              <button onClick={() => setPaymentMethod('GCASH')} className={`p-3 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${paymentMethod === 'GCASH' ? 'border-blue-500 bg-blue-50' : 'border-zinc-100'}`}><div className="w-6 h-6 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-xs">G</div><span className="font-semibold text-xs">GCash</span></button>
              <button onClick={() => setPaymentMethod('SPLIT')} className={`p-3 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${paymentMethod === 'SPLIT' ? 'border-purple-500 bg-purple-50' : 'border-zinc-100'}`}><div className="w-6 h-6 rounded-full bg-purple-100 flex items-center justify-center text-purple-600 font-bold text-xs">S</div><span className="font-semibold text-xs">Split</span></button>
            </div>
            {paymentMethod === 'GCASH' && (
               <div className="mb-6 animate-fade-in">
                 {storeSettings.gcashQr ? (
                    <div className="flex flex-col items-center mb-4 p-4 bg-blue-50 rounded-xl border-2 border-dashed border-blue-200">
                        <p className="text-xs font-bold text-blue-600 uppercase mb-2">Scan to Pay</p>
                        <button onClick={() => setIsQrZoomed(true)} className="w-40 h-40 bg-white p-2 rounded-lg shadow-sm cursor-zoom-in hover:scale-105 transition-transform" title="Click to enlarge"><img src={storeSettings.gcashQr} alt="GCash QR" className="w-full h-full object-contain" /></button>
                    </div>
                 ) : (
                    <div className="flex flex-col items-center mb-4 p-4 bg-gray-50 rounded-xl border-2 border-dashed border-gray-200 text-center"><CreditCard className="w-8 h-8 text-gray-400 mb-2" /><p className="text-xs font-bold text-gray-500 uppercase">No QR Code Available</p></div>
                 )}
                 <label className="text-xs font-bold text-gray-500 uppercase">Reference Number</label>
                 <input type="text" className="w-full border-b-2 border-zinc-200 py-2 focus:outline-none focus:border-blue-500 font-mono text-lg bg-white text-zinc-900 placeholder-zinc-300" placeholder="000 000 000" value={gcashRef} onChange={e => setGcashRef(e.target.value)} />
               </div>
            )}
            {paymentMethod === 'SPLIT' && (
                <div className="mb-6 animate-fade-in bg-purple-50 p-4 rounded-xl border border-purple-100">
                    <p className="text-xs font-bold text-purple-700 uppercase mb-3 text-center">Split Breakdown</p>
                    <div className="mb-3"><label className="text-xs font-bold text-gray-500 uppercase block mb-1">Cash</label><div className="relative"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 font-bold">₱</span><input type="number" className="w-full pl-8 pr-4 py-2 border border-zinc-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 font-mono text-lg bg-white text-zinc-900" placeholder="0.00" value={splitCashAmount} onChange={e => setSplitCashAmount(e.target.value)} /></div></div>
                    <div className="mb-3"><label className="text-xs font-bold text-gray-500 uppercase block mb-1">GCash</label><div className="w-full pl-4 pr-4 py-2 bg-purple-100 rounded-lg border border-purple-200 text-purple-800 font-mono text-lg font-bold">₱{Math.max(0, total - Number(splitCashAmount || 0)).toFixed(2)}</div></div>
                    <div><label className="text-xs font-bold text-gray-500 uppercase block mb-1">GCash Reference</label><input type="text" className="w-full py-2 border-b-2 border-zinc-300 bg-transparent focus:outline-none focus:border-purple-500 font-mono text-sm text-zinc-900 placeholder-zinc-400" placeholder="GCash Ref No." value={gcashRef} onChange={e => setGcashRef(e.target.value)} /></div>
                </div>
