import { GroomingAppointment, Role, Client, Pet } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User, Scissors, History, Clock, CheckCircle, ArrowRight, Pencil, Trash2, Smartphone, Scale, Palette, Check, MessageSquare, Mail, ChevronUp, ChevronDown, Search, X, RotateCcw } from '../components/ui/Icons';
