// --- TEXTBEE.DEV SMS ---

export const sendSMS = async (settings: StoreSettings, recipients: string[], message: string) => {
    if (!settings.smsEnabled || !settings.textBeeApiKey || !settings.textBeeDeviceId) {
        console.warn("SMS Sending Disabled or Missing Config");
        return { success: false, error: 'Configuration Missing' };
    }

    // Auto-Sanitize Recipients here to ensure 100% success rate
    const cleanRecipients = recipients.map(sanitizeForSms).filter(num => num.length >= 10);

    if (cleanRecipients.length === 0) {
        console.warn("No valid recipients after sanitization.");
        return { success: false, error: 'Invalid Numbers' };
    }

    const payload = {
        recipients: cleanRecipients,
        message: message,
    };

    try {
        const response = await fetch(`https://api.textbee.dev/api/v1/gateway/devices/${settings.textBeeDeviceId}/sendSMS`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': settings.textBeeApiKey
            },
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            const err = await response.text();
            throw new Error(`TextBee API Error: ${err}`);
        }

        const data = await response.json();
        return { success: true, data };
    } catch (error: any) {
        console.error("SMS Send Failed:", error);
        return { success: false, error: error.message };
    }
};

// --- GMAIL API DIRECT (System-Generated) ---

const refreshAccessToken = async (settings: StoreSettings) => {
    const clientId = settings.googleClientId?.trim();
    const clientSecret = settings.googleClientSecret?.trim();
    const refreshToken = settings.googleRefreshToken?.trim();

    if (!clientId || !clientSecret || !refreshToken) {
        throw new Error("Missing Google credentials");
    }

    const params = new URLSearchParams();
    params.append('client_id', clientId);
    params.append('client_secret', clientSecret);
    params.append('refresh_token', refreshToken);
    params.append('grant_type', 'refresh_token');

    try {
        const response = await fetch('https://oauth2.googleapis.com/token', {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: params
        });

        const rawText = await response.text();
        let data: any;

        try {
            data = JSON.parse(rawText);
        } catch (e) {
            if (!response.ok) {
                throw new Error(`Token endpoint returned ${response.status}: ${rawText}`);
            }
            throw new Error("Invalid response from Google Token Endpoint");
        }

        if (!response.ok) {
            // Improved logging to prevent [object Object]
            console.error("Google Token Refresh Error:", JSON.stringify(data, null, 2));

            if (data.error === 'invalid_grant') throw new Error("Refresh Token Invalid/Expired. Please re-authenticate in Settings.");
            if (data.error === 'invalid_client') throw new Error("Invalid Client ID or Client Secret. Please check Settings.");
            if (data.error === 'deleted_client') throw new Error("The OAuth Client ID was deleted in Google Cloud. Please create a new one.");

            const errorDescription = data.error_description || data.error || JSON.stringify(data);

            // Check specifically for "deleted" text in description
            if (String(errorDescription).toLowerCase().includes('client was deleted')) {
                 throw new Error("The Google OAuth Client has been deleted. Please update your Client ID and Secret in Settings.");
            }

            throw new Error(`Token Refresh Failed: ${errorDescription}`);
        }

        return data.access_token;

    } catch (error: any) {
        console.error("Token Refresh Exception:", error);
        if (error.message === 'Failed to fetch' || error.name === 'TypeError') {
             throw new Error("Network/CORS Error. Check internet.");
        }
        throw error;
    }
};

// Helper: Strip HTML tags to create a Plain Text version (Anti-Spam requirement)
const stripHtml = (html: string) => {
   return html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '') // Remove style blocks
              .replace(/<br\s*\/?>/gi, '\n') // Replace br with newline
              .replace(/<\/p>/gi, '\n\n') // Paragraphs
              .replace(/<b>(.*?)<\/b>/gi, '*$1*') // Bold to Markdown
              .replace(/<strong>(.*?)<\/strong>/gi, '*$1*') // Bold to Markdown
              .replace(/<[^>]+>/g, '') // Remove all other tags
              .replace(/&nbsp;/g, ' ')
              .trim();
};

const sendGmailDirect = async (settings: StoreSettings, to: string, subject: string, messageContent: string, title: string) => {
    try {
        const accessToken = await refreshAccessToken(settings);

        // Clean MIME Structure: multipart/alternative (Text + HTML)
        const boundaryAlt = "pawfriends_alt_" + Date.now();

        // 1. Generate Content
        const finalHtml = generateGroomingEmailHtml(settings, messageContent, title);
        const plainText = stripHtml(finalHtml);

        // 2. Construct the MIME Message Tree
        // Adding Message-ID and Date is CRITICAL for Spam filters (especially for "Ready for Pickup" type emails)
        const messageParts: string[] = [];
        const messageId = `<${Date.now()}.${Math.random().toString(36).substring(2)}@pawfriends.app>`;

        // Headers
        messageParts.push(`MIME-Version: 1.0`);
        messageParts.push(`To: ${to}`);
        // Google overwrites sender address but keeps the name. Using a dummy domain helps MIME parsers.
        messageParts.push(`From: "${settings.emailSenderName || settings.name}" <notifications@pawfriends.app>`);
        messageParts.push(`Subject: ${subject}`);
        messageParts.push(`Date: ${new Date().toUTCString()}`);
        messageParts.push(`Message-ID: ${messageId}`);
        messageParts.push(`Content-Type: multipart/alternative; boundary="${boundaryAlt}"`);
        messageParts.push(``); // Blank line between headers and body

        // Text Part
        messageParts.push(`--${boundaryAlt}`);
        messageParts.push(`Content-Type: text/plain; charset="UTF-8"`);
        messageParts.push(``);
        messageParts.push(plainText);
        messageParts.push(``);

        // HTML Part
        messageParts.push(`--${boundaryAlt}`);
        messageParts.push(`Content-Type: text/html; charset="UTF-8"`);
        messageParts.push(``);
        messageParts.push(finalHtml);
        messageParts.push(``);

        // End Alternative
        messageParts.push(`--${boundaryAlt}--`);

        // Join with CRLF
        const rawMessage = messageParts.join("\r\n");

        // Base64URL Encode
        const encodedEmail = btoa(unescape(encodeURIComponent(rawMessage)))
            .replace(/\+/g, '-')
            .replace(/\//g, '_')
            .replace(/=+$/, '');

        const response = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/send', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${accessToken}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                raw: encodedEmail
            })
        });

        if (!response.ok) {
            let err;
            try {
                err = await response.json();
            } catch {
                err = { message: response.statusText };
            }
            console.error("Gmail API Send Error:", err);

            if (response.status === 401 || response.status === 403) {
                 throw new Error("Unauthorized: Token valid but permission denied. Check scopes.");
            }

            const errMsg = err.error?.message || JSON.stringify(err);
            throw new Error(`Gmail API Error: ${errMsg}`);
        }

        return { success: true };

    } catch (error: any) {
        console.error("Gmail Direct Send Failed:", error);
        return { success: false, error: error.message || String(error) };
    }
};

// --- EMAIL SENDING WRAPPER ---

export const sendEmail = async (settings: StoreSettings, to: string, subject: string, messageContent: string, title: string = "Notification") => {
    if (!settings.emailEnabled) {
        return { success: false, error: 'Email Disabled' };
    }

    // PRIORITY: Use Google Direct if configured
    if (settings.googleRefreshToken && settings.googleClientId) {
        return sendGmailDirect(settings, to, subject, messageContent, title);
    }

    return { success: false, error: 'No Email Service Configured' };
};

// --- COMPOSITE FUNCTION ---

export const sendCompletionNotifications = async (
    settings: StoreSettings, 
    apt: GroomingAppointment, 
    service: Product | undefined
) => {
    const results = { sms: false, email: false };
    const serviceName = service ? service.name : "Grooming Service";
    const price = service ? service.price : 0;

    const content = getNotificationContent(settings, 'COMPLETED', apt, serviceName, price);

    // 1. Send SMS
    if (settings.smsEnabled && apt.contactNumber) {
        const smsRes = await sendSMS(settings, [apt.contactNumber], content.sms);
        results.sms = smsRes.success;
    }

    // 2. Send Email
    // PASS CONTENT DIRECTLY, do not generate HTML here. The sender function handles generation.
    if (settings.emailEnabled && apt.email) {
        const emailRes = await sendEmail(settings, apt.email, content.emailSubject, content.emailBody, "Ready for Pickup!");
        results.email = emailRes.success;
    }

    return results;
};

import React, { useEffect, useState, useRef } from 'react';
import { useStore } from '../context/StoreContext';
import { useNavigate, useLocation } from 'react-router-dom';
import { ShieldCheck, Lock, Cloud, CheckCircle, ArrowRight, RotateCcw } from './ui/Icons';
import { getDeviceName } from '../services/device';
import Button from './ui/Button';
import { fetchTable } from '../services/supabase';

export const DeviceGuard: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isLoading, isSystemSetup, currentDeviceStatus, registerDevice, storeSettings, devices, currentDeviceId, updateStoreSettings } = useStore();
  const navigate = useNavigate();
  const location = useLocation();

  // Track state transitions to show Welcome Modal
  const [showWelcome, setShowWelcome] = useState(false);
  const [wasPending, setWasPending] = useState(false);
  const [isPolling, setIsPolling] = useState(false);
  // Use any to avoid NodeJS namespace issues in browser environment
  const pollInterval = useRef<any>(null);

  // Force re-check logic
  const [lastCheck, setLastCheck] = useState(Date.now());

  useEffect(() => {
    if (!isLoading) {
      if (!isSystemSetup && location.pathname !== '/setup') {
        navigate('/setup');
      } else if (isSystemSetup) {
          // Prevent spamming / infinite loop
          const alreadyRegistered = devices.some(d => d.id === currentDeviceId);
          if (!alreadyRegistered) {
              registerDevice();
          }
      }
    }
  }, [isLoading, isSystemSetup, location.pathname, registerDevice, devices, currentDeviceId]);

  // Monitor status changes for the Welcome Modal & Polling
  useEffect(() => {
      if (isLoading) return;

      if (currentDeviceStatus === 'PENDING') {
          setWasPending(true);
          // Start polling if not already
          if (!pollInterval.current) {
              setIsPolling(true);
              pollInterval.current = setInterval(async () => {
                  // Direct fetch to bypass potential socket issues
                  const data = await fetchTable('devices');
                  if (data) {
                      const myDevice = data.find((d: any) => d.id === currentDeviceId);
                      if (myDevice && myDevice.status === 'APPROVED') {
                          // Force a window reload or state update if Context didn't catch it
                          // But ideally, we just update a local trigger to re-sync
                          // Since we can't easily force-update Context from here without exposing a method,
                          // we rely on the fact that if we see Approved, we can set local state to unblock visually
                          // However, context needs to be in sync for the rest of the app.
                          // Triggering a 'soft' reload of context would be best, but window.location.reload() is nuclear.

                          // Let's assume the subscription WILL pick it up, but if it's stuck,
                          // we can manually force a reload if we detect a mismatch.
                          // Actually, we can just reload the page if we detect approval but context is stale.
                          window.location.reload(); 
                      }
                  }
              }, 3000); // Check every 3 seconds
          }
      } else if (currentDeviceStatus === 'APPROVED') {
          // Stop polling
          if (pollInterval.current) {
              clearInterval(pollInterval.current);
              pollInterval.current = null;
              setIsPolling(false);
          }

          if (wasPending) {
              setShowWelcome(true);
              setWasPending(false);
          }
      } else if (currentDeviceStatus === 'BLOCKED') {
          if (pollInterval.current) {
              clearInterval(pollInterval.current);
              pollInterval.current = null;
          }
      }

      return () => {
          if (pollInterval.current) clearInterval(pollInterval.current);
      };
  }, [currentDeviceStatus, isLoading, wasPending, currentDeviceId]);

  const handleEnterSystem = () => {
      setShowWelcome(false);
  };

  if (isLoading) {
    return (
        <div className="min-h-screen bg-zinc-50 flex flex-col items-center justify-center gap-4">
            <div className="w-16 h-16 border-4 border-zinc-200 border-t-black rounded-full animate-spin"></div>
            <p className="font-bold text-zinc-500 animate-pulse">Checking Security...</p>
        </div>
    );
  }

  // Allow pass-through for Setup page
  if (location.pathname === '/setup') {
      return <>{children}</>;
  }

  // Handle Device Status for Normal Usage
  if (currentDeviceStatus === 'BLOCKED') {
      return (
          <div className="min-h-screen bg-red-50 flex items-center justify-center p-4">
              <div className="bg-white p-8 rounded-3xl shadow-2xl max-w-md text-center border-2 border-red-100">
                  <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                      <Lock className="w-8 h-8 text-red-600" />
                  </div>
                  <h1 className="text-2xl font-bold text-red-900 mb-2">Access Denied</h1>
                  <p className="text-gray-500 mb-6">This device has been blocked by the administrator.</p>
                  <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-200">
                      <p className="text-xs font-bold text-gray-400 uppercase">Device ID</p>
                      <p className="font-mono text-xs text-zinc-600 mt-1">{localStorage.getItem('pawfriends_device_id')}</p>
                  </div>
              </div>
          </div>
      );
  }

  // Welcome / Approval Notification Modal
  if (showWelcome) {
      return (
        <div className="min-h-screen bg-green-50 flex items-center justify-center p-4 animate-fade-in">
            <div className="bg-white p-8 rounded-3xl shadow-2xl max-w-md text-center border-2 border-green-100 relative overflow-hidden">
                {/* Confetti Background Effect (CSS only) */}
                <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none" 
                     style={{backgroundImage: 'radial-gradient(circle, #22c55e 2px, transparent 2.5px)', backgroundSize: '20px 20px'}}>
                </div>

                <div className="relative z-10">
                    <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6 animate-bounce">
                        <CheckCircle className="w-10 h-10 text-green-600" />
                    </div>
                    <h1 className="text-2xl font-bold text-zinc-900 mb-2">Device Approved!</h1>
                    <p className="text-gray-500 mb-6">
                        Welcome to <strong>{storeSettings.name}</strong>. Your device has been successfully registered and authorized by the admin.
                    </p>
                    <Button onClick={handleEnterSystem} className="w-full bg-green-600 hover:bg-green-700 shadow-green-200 text-white py-4 text-lg">
