                                <span className="text-[10px] text-zinc-500 font-mono">({discountPercentage.toFixed(1)}%)</span>
                            )}
                        </div>
                    </div>
                    <div className="flex justify-between text-white font-bold text-lg pt-2 border-t border-zinc-700">
                        <span>Total</span>
                        <span>₱{total.toFixed(2)}</span>
                    </div>
                </div>

                <Button
                    variant="secondary"
                    className="w-full font-bold text-lg py-3 border-none hover:bg-zinc-200"
                    disabled={cart.length === 0}
                    onClick={onCheckout}
                >
                    Checkout
                </Button>
            </div>
        </div>
    );
}

const POS: React.FC = () => {
  const { products, discounts, addTransaction, addAppointment, currentUser, productCategories, serviceCategories, storeSettings, clients, users } = useStore();
