                                    title="Remove Item"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        )
                    })
                )}
            </div>

            <div className="p-5 bg-zinc-900 text-white lg:rounded-b-3xl mt-auto shadow-inner z-20 relative">
