       {/* --- PAYMENT MODAL (NEW) --- */}
       <Dialog open={isPaymentModalOpen} onClose={() => setIsPaymentModalOpen(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
