import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext';
import { useBroadcast } from '../context/BroadcastContext'; 
import { GroomingAppointment, Role, Client, Pet, Transaction } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User, Scissors, History, Clock, CheckCircle, ArrowRight, Pencil, Trash2, Smartphone, Scale, Palette, Check, MessageSquare, Mail, ChevronUp, ChevronDown, Search, X, RotateCcw, CreditCard, Printer, Settings } from '../components/ui/Icons';
