                </Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Hidden Print Layout */}
      {printingTransaction && (
        <div id="printable-content" className="hidden print:block fixed inset-0 bg-white z-[9999] p-2">
            <ReceiptTemplate transaction={printingTransaction} settings={storeSettings} paperSize={paperSize} />
        </div>
      )}
    </div>
  );
};

