          return appointments.filter(a => a.status === 'COMPLETED' && a.date === today).length;
      }
      return 0;
  };

  // Helper for Payment Modal Display
  const getPaymentServiceDetails = () => {
      if (!paymentApt) return { name: '', price: 0 };
