            : selectedDiscount.value;
      }

      return { 
          name: s?.name || 'Unknown Service', 
          price: basePrice,
          discount: discountValue,
          finalTotal: Math.max(0, basePrice - discountValue)
      };
  };
  const paymentDetails = getPaymentServiceDetails();

