Here is the **Complete Database Schema** (since you mentioned you deleted it) and the updated code to implement the **Facebook Messenger-style design**, **Unread Counts**, **Read Status**, and **Timestamps**.

### **⚠️ 1. Run this "Whole Database" SQL Script**
Go to **Supabase > SQL Editor**, paste this, and run it. This creates all tables (including the updated `messages` table with the `read` column) and enables security.

```sql
-- 1. CLEANUP (Only if you want to start fresh, otherwise skip drops)
drop table if exists public.messages;
drop table if exists public.template_history;
drop table if exists public.service_categories;
drop table if exists public.product_categories;
drop table if exists public.sms_tracker;
drop table if exists public.devices;
drop table if exists public.logs;
drop table if exists public.discounts;
drop table if exists public.appointments;
drop table if exists public.transactions;
drop table if exists public.products;
drop table if exists public.clients;
drop table if exists public.users;
drop table if exists public.store_settings;

-- 2. CREATE TABLES

-- Store Settings
create table public.store_settings (
  id text not null primary key,
  name text,
  address text,
  contact_number text,
  vat_rate numeric default 12,
  gcash_number text,
  gcash_qr text,
  receipt_header text,
  receipt_footer text,
  logo text,
  sms_enabled boolean default false,
  text_bee_api_key text,
  text_bee_device_id text,
  email_enabled boolean default false,
  email_service_id text,
  email_template_id text,
  email_public_key text,
  email_sender_name text,
  email_footer_text text,
  sms_template_upcoming text,
  email_subject_upcoming text,
  email_body_upcoming text,
  sms_template_waiting text,
  email_subject_waiting text,
  email_body_waiting text,
  sms_template_ongoing text,
  email_subject_ongoing text,
  email_body_ongoing text,
  sms_template_completed text,
  email_subject_completed text,
  email_body_completed text,
  sms_template_promo text,
  email_subject_promo text,
  email_body_promo text
);

-- Users
create table public.users (
  id text not null primary key,
  name text not null,
  pin text not null,
  role text not null,
  salt text
);

-- Clients
create table public.clients (
  id text not null primary key,
  name text not null,
  contact_number text,
  email text,
  address text,
  notes text,
  first_seen timestamptz default now(),
  pets jsonb default '[]'::jsonb
);

-- Products
create table public.products (
  id text not null primary key,
  name text not null,
  price numeric not null default 0,
  cost numeric not null default 0,
  category text,
  stock numeric default 0,
  is_service boolean default false
);

-- Transactions
create table public.transactions (
  id text not null primary key,
  items jsonb default '[]'::jsonb,
  subtotal numeric default 0,
  vat numeric default 0,
  total numeric default 0,
  discount numeric default 0,
  payment_method text,
  gcash_ref text,
  cash_received numeric,
  date timestamptz default now(),
  cashier_id text
);

-- Appointments
create table public.appointments (
  id text not null primary key,
  pet_name text,
  pet_breed text,
  pet_color text,
  weight_size text,
  owner_name text,
  contact_number text,
  email text,
  service_id text,
  hair_cut text,
  date text,
  time text,
  status text,
  groomer_id text
);

-- Discounts
create table public.discounts (
  id text not null primary key,
  name text not null,
  type text not null,
  value numeric not null,
  active boolean default true,
  trigger_type text default 'MANUAL',
  trigger_value text,
  is_permanent boolean default true,
  start_date text,
  end_date text
);

-- Logs
create table public.logs (
  id text not null primary key,
  action text,
  details text,
  timestamp timestamptz default now(),
  user_id text,
  reference_id text
);

-- Devices
create table public.devices (
  id text not null primary key,
  name text,
  custom_name text,
  os text,
  browser text,
  device_type text,
  status text default 'PENDING',
  last_active timestamptz default now(),
  ip text,
  location text
);

-- SMS Tracker
create table public.sms_tracker (
  hour_key text not null primary key,
  count int default 0,
  updated_at timestamptz default now()
);

-- Categories
create table public.product_categories (name text primary key);
create table public.service_categories (name text primary key);

-- Template History
create table public.template_history (
  id text not null primary key,
  category text,
  channel text,
  content text,
  created_at timestamptz default now()
);

-- Messages (Updated for Chat V2)
create table public.messages (
  id text not null primary key,
  client_id text not null references public.clients(id) on delete cascade,
  direction text not null check (direction in ('INBOUND', 'OUTBOUND')),
  channel text not null check (channel in ('SMS', 'EMAIL')),
  content text not null,
  timestamp timestamptz default now(),
  status text default 'SENT',
  read boolean default false
);

-- 3. ENABLE SECURITY (RLS)
alter table public.store_settings enable row level security;
alter table public.users enable row level security;
alter table public.clients enable row level security;
alter table public.products enable row level security;
alter table public.transactions enable row level security;
alter table public.appointments enable row level security;
alter table public.discounts enable row level security;
alter table public.logs enable row level security;
alter table public.devices enable row level security;
alter table public.sms_tracker enable row level security;
alter table public.product_categories enable row level security;
alter table public.service_categories enable row level security;
alter table public.template_history enable row level security;
alter table public.messages enable row level security;

-- 4. CREATE POLICIES (Allow all logged in users)
create policy "Allow auth access" on public.store_settings for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.users for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.clients for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.products for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.transactions for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.appointments for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.discounts for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.logs for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.devices for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.sms_tracker for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.product_categories for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.service_categories for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.template_history for all to authenticated using (true) with check (true);
create policy "Allow auth access" on public.messages for all to authenticated using (true) with check (true);

-- 5. ENABLE REALTIME
alter publication supabase_realtime add table public.store_settings;
alter publication supabase_realtime add table public.users;
alter publication supabase_realtime add table public.clients;
alter publication supabase_realtime add table public.products;
alter publication supabase_realtime add table public.transactions;
alter publication supabase_realtime add table public.appointments;
alter publication supabase_realtime add table public.discounts;
alter publication supabase_realtime add table public.logs;
alter publication supabase_realtime add table public.devices;
alter publication supabase_realtime add table public.sms_tracker;
alter publication supabase_realtime add table public.template_history;
alter publication supabase_realtime add table public.messages;
```

