interface StoreContextType {
  isLoading: boolean;
  isSystemSetup: boolean; // False if no users exist
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  clients: Client[];
  discounts: Discount[];
  logs: Log[];
  devices: Device[];
  templateHistory: TemplateHistory[];
  messages: Message[];
  currentDeviceId: string;
  currentDeviceStatus: 'PENDING' | 'APPROVED' | 'BLOCKED';

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // SMS Usage Tracking
  smsUsage: SmsUsage;
  checkAndIncrementSms: () => boolean; // Returns true if allowed, false if blocked

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => Promise<boolean>;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Device Management
  registerDevice: () => Promise<void>;
  updateDeviceStatus: (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => void;
  deleteDevice: (deviceId: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  adjustStock: (id: string, amount: number) => void;

  addTransaction: (transaction: Transaction) => void;
  deleteTransaction: (id: string) => void;
  updateTransaction: (oldTx: Transaction, newTx: Transaction) => void;

  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Client Actions
  addClient: (client: Client) => void;
  updateClient: (client: Client) => void;
  deleteClient: (id: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;

  // Template History Actions
  saveTemplateHistory: (category: 'GROOMING' | 'PROMO', channel: 'SMS' | 'EMAIL_SUBJECT' | 'EMAIL_BODY' | 'EMAIL_FOOTER', content: string) => void;
  deleteTemplateHistory: (id: string) => void;

  // Chat Actions
  sendChatMessage: (clientId: string, content: string, channel: 'SMS' | 'EMAIL') => Promise<boolean>;
  markMessagesAsRead: (clientId: string, channel: 'SMS' | 'EMAIL') => Promise<void>;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [isSystemSetup, setIsSystemSetup] = useState(true);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentDeviceId] = useState(getDeviceId());

  // Data States
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);
  const [devices, setDevices] = useState<Device[]>([]);
  const [templateHistory, setTemplateHistory] = useState<TemplateHistory[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);

  // Initialize with Empty Arrays (Connect strictly to DB)
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // SMS Tracking State (Synced with DB)
  const [smsUsage, setSmsUsage] = useState<SmsUsage>({ 
      count: 0, 
      lastSentHour: new Date().getHours(), 
      lastSentDate: new Date().toISOString().split('T')[0] 
  });

  // Derived Device Status
  const currentDevice = devices.find(d => d.id === currentDeviceId);
  const currentDeviceStatus = currentDevice ? currentDevice.status : 'PENDING';

  // 1. Fetch Initial Data from Supabase
  useEffect(() => {
    const initData = async () => {
        setIsLoading(true);
        try {
            const [
                fetchedSettings, 
                fetchedUsers, 
                fetchedProducts, 
                fetchedTrx, 
                fetchedApts, 
                fetchedClients, 
                fetchedDiscounts, 
                fetchedLogs,
                fetchedProdCats,
                fetchedServCats,
                fetchedDevices,
                fetchedHistory,
                fetchedMessages
            ] = await Promise.all([
                fetchTable('store_settings'),
                fetchTable('users'),
                fetchTable('products'),
                fetchTable('transactions'),
                fetchTable('appointments'),
                fetchTable('clients'),
                fetchTable('discounts'),
                fetchTable('logs'),
                fetchTable('product_categories'),
                fetchTable('service_categories'),
                fetchTable('devices'),
                fetchTable('template_history'),
                fetchTable('messages')
            ]);

            // Fetch SMS Usage for Current Hour
            const now = new Date();
            const hourKey = `${now.toISOString().split('T')[0]}-${now.getHours()}`;
            const { data: smsData } = await supabase.from('sms_tracker').select('*').eq('hour_key', hourKey).single();
            if (smsData) {
                setSmsUsage({
                    count: smsData.count,
                    lastSentHour: now.getHours(),
                    lastSentDate: now.toISOString().split('T')[0] 
                });
            }

            // Set Data (Only override if data exists)
            if (fetchedSettings && fetchedSettings.length > 0) {
                const cloudSettings = fetchedSettings.find((s: any) => s.id === 'global_settings') || fetchedSettings[0];
                const mappedCloudSettings = mapSettingsFromDb(cloudSettings);
                setStoreSettings({ ...INITIAL_STORE_SETTINGS, ...mappedCloudSettings });
            } else {
                // Seed database if empty
                const { supabaseUrl, supabaseKey, ...initialDbSettings } = INITIAL_STORE_SETTINGS;
                // Use mapper to ensure snake_case initial seed
                const payload = mapSettingsPayload(INITIAL_STORE_SETTINGS);
                await upsertData('store_settings', payload);
            }

            if (fetchedUsers && fetchedUsers.length > 0) {
               setUsers(fetchedUsers);
               setIsSystemSetup(true);

               // --- SESSION RESTORE LOGIC ---
               // Check if user was previously logged in
               const persistedUserId = localStorage.getItem('pawfriends_active_user');
               if (persistedUserId) {
                   const foundUser = fetchedUsers.find((u: any) => u.id === persistedUserId);
                   if (foundUser) {
                       setCurrentUser(foundUser);
                   }
               }
               // -----------------------------

            } else {
               setUsers([]);
               setIsSystemSetup(false);
            }

            // Sanitized Product Load (Default cost to 0 if missing)
            if (fetchedProducts) {
                setProducts(fetchedProducts.map((p: any) => ({ ...p, cost: p.cost ?? 0 })));
            }

            // Apply Mappers to normalized DB columns to App Types
            if (fetchedTrx) setTransactions(fetchedTrx.map(mapTransaction));
            if (fetchedApts) setAppointments(fetchedApts.map(mapAppointment));
            if (fetchedClients) setClients(fetchedClients.map(mapClient));

            if (fetchedDiscounts) setDiscounts(fetchedDiscounts.map(mapDiscount));
            if (fetchedLogs) setLogs(fetchedLogs);

            // Map Devices from DB (snake_case) to App (camelCase)
            if (fetchedDevices) {
                const mappedDevices = fetchedDevices.map((d: any) => ({
                    id: d.id,
                    name: d.name,
                    custom_name: d.custom_name,
                    os: d.os,
                    browser: d.browser,
                    device_type: d.device_type,
                    status: d.status,
                    lastActive: d.last_active, // Map from DB
                    ip: d.ip,
                    location: d.location
                }));
                setDevices(mappedDevices);
            }

            if (fetchedHistory) setTemplateHistory(fetchedHistory);
            if (fetchedMessages) setMessages(fetchedMessages);

            // --- AUTO DETECT CATEGORIES ---
            let finalProdCats = fetchedProdCats ? fetchedProdCats.map((c: any) => c.name) : [];
            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
                }
                if (finalServCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalServCats = Array.from(detected);
                }
            }

            setProductCategories(finalProdCats);
            setServiceCategories(finalServCats);

        } catch (error) {
            console.error("Critical Error fetching initial data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initData();
  }, [currentDeviceId]);

  // 2. Setup Realtime Listeners
  useEffect(() => {
    // Helper to update state based on payload with Optional Mapper
    const handleUpdate = (
        payload: any, 
        setter: React.Dispatch<React.SetStateAction<any[]>>, 
        idField = 'id', 
        mapper?: (item: any) => any,
        isProduct = false
    ) => {
        const { eventType, new: rawNewRecord, old: oldRecord } = payload;

        // Apply mapper if provided
        const newRecord = (eventType === 'INSERT' || eventType === 'UPDATE') && mapper 
            ? mapper(rawNewRecord) 
            : rawNewRecord;

        setter(prev => {
            if (eventType === 'INSERT') {
                if (isProduct && newRecord.cost === undefined) newRecord.cost = 0;
                const exists = prev.find(item => item[idField] === newRecord[idField]);
                if (exists) {
                     return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
                }
                return [newRecord, ...prev];
            }
            if (eventType === 'UPDATE') {
                 if (isProduct && newRecord.cost === undefined) newRecord.cost = 0;
                 return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
            }
            if (eventType === 'DELETE') {
                const deleteId = oldRecord?.[idField] || oldRecord?.id;
                if (!deleteId) return prev;
                return prev.filter(item => item[idField] !== deleteId);
            }
            return prev;
        });
    };

    // Device Mapper for Realtime
    const mapDeviceFromRealtime = (d: any) => ({
        id: d.id,
        name: d.name,
        custom_name: d.custom_name,
        os: d.os,
        browser: d.browser,
        device_type: d.device_type,
        status: d.status,
        lastActive: d.last_active,
        ip: d.ip,
        location: d.location
    });

    const subs = [
        subscribeToTable('users', (p) => handleUpdate(p, setUsers)),
        subscribeToTable('products', (p) => handleUpdate(p, setProducts, 'id', undefined, true)), // isProduct=true

        // Use Mappers for tables with potential snake_case columns
        subscribeToTable('transactions', (p) => handleUpdate(p, setTransactions, 'id', mapTransaction)),
        subscribeToTable('appointments', (p) => handleUpdate(p, setAppointments, 'id', mapAppointment)),
        subscribeToTable('clients', (p) => handleUpdate(p, setClients, 'id', mapClient)),

        subscribeToTable('discounts', (p) => handleUpdate(p, setDiscounts, 'id', mapDiscount)),
        subscribeToTable('logs', (p) => handleUpdate(p, setLogs)), // logs mapper handled in addLog, but realtime needs explicit mapping if we care about realtime logs from other devices (optional)
        subscribeToTable('devices', (p) => handleUpdate(p, setDevices, 'id', mapDeviceFromRealtime)),
        subscribeToTable('template_history', (p) => handleUpdate(p, setTemplateHistory)),
        subscribeToTable('messages', (p) => handleUpdate(p, setMessages)),

        subscribeToTable('store_settings', (payload) => {
             if (payload.new) {
                 const mapped = mapSettingsFromDb(payload.new);
                 setStoreSettings(prev => ({ ...prev, ...mapped }));
             }
        }),

        // SMS TRACKER SYNC
        subscribeToTable('sms_tracker', (payload) => {
            const now = new Date();
            const hourKey = `${now.toISOString().split('T')[0]}-${now.getHours()}`;

            // Only update if it matches current hour
            if (payload.new && payload.new.hour_key === hourKey) {
                setSmsUsage({
                    count: payload.new.count,
                    lastSentHour: now.getHours(),
                    lastSentDate: now.toISOString().split('T')[0]
                });
            } else if (payload.new && payload.new.hour_key !== hourKey) {
                // If update is for a different hour (e.g. roll over), it implies current hour is likely 0 if not exist
                // We rely on checkAndIncrementSms to create the new row if it doesn't exist
            }
        }),

        subscribeToTable('product_categories', () => {
            fetchTable('product_categories').then(data => {
                if(data) setProductCategories(data.map((c: any) => c.name));
            });
        }),
        subscribeToTable('service_categories', () => {
            fetchTable('service_categories').then(data => {
                if(data) setServiceCategories(data.map((c: any) => c.name));
            });
        })
    ];

    return () => {
        subs.forEach(sub => supabase.removeChannel(sub));
    };
  }, []);

  useEffect(() => {
    // Sync current user object if it changes in DB (e.g. role update)
    if (!isLoading && currentUser && users.length > 0) {
        const userExists = users.find(u => u.id === currentUser.id);
        if (!userExists) {
            setCurrentUser(null);
            localStorage.removeItem('pawfriends_active_user');
        } else {
             // If properties changed (like role), update local state
             if (JSON.stringify(userExists) !== JSON.stringify(currentUser)) {
                 setCurrentUser(userExists);
             }
        }
    }
  }, [users, currentUser, isLoading]);

  useEffect(() => {
     if (users.length > 0 && !isSystemSetup) {
         setIsSystemSetup(true);
     }
  }, [users, isSystemSetup]);

  // ------------------------------------------------------------------
  // Helper: Save Appointment with Fallback
  // ------------------------------------------------------------------
  const saveAppointmentToDb = async (apt: GroomingAppointment) => {
      const payload = mapAppointmentPayload(apt);
      const { error } = await upsertData('appointments', payload);

      if (error && (error.code === '42703' || error.message.includes('column'))) {
          console.warn("Appointments DB Schema mismatch. Retrying with alternative format.");
          const snakePayload = {
              id: apt.id,
              pet_name: apt.petName,
              owner_name: apt.ownerName,
              contact_number: apt.contactNumber,
              service_id: apt.serviceId,
              groomer_id: apt.groomerId,
              pet_breed: apt.petBreed,
              pet_color: apt.petColor,
              weight_size: apt.weightSize,
              hair_cut: apt.hairCut,
              date: apt.date,
              time: apt.time,
              status: apt.status,
              email: apt.email
          };
          await upsertData('appointments', snakePayload);
      }
  };

  const saveClientToDb = async (client: Client) => {
      const payload = mapClientPayload(client);
      const { error } = await upsertData('clients', payload);

      if (error && (error.code === '42703' || error.message.includes('column'))) {
          console.warn("Clients DB Schema mismatch. Retrying with Camel Case.");
          await upsertData('clients', client);
      }
  };

  // ------------------------------------------------------------------
  // Actions
  // ------------------------------------------------------------------

  // --- SMS Tracking (Database Synced) ---
  const checkAndIncrementSms = (): boolean => {
      const MAX_PER_HOUR = 30;
      const now = new Date();
      const currentHour = now.getHours();
      const currentDate = now.toISOString().split('T')[0];
      const hourKey = `${currentDate}-${currentHour}`;

      let newCount = smsUsage.count;

      // Handle Hour Rollover Logic locally for immediate check
      if (smsUsage.lastSentHour !== currentHour || smsUsage.lastSentDate !== currentDate) {
          newCount = 0;
      }

      if (newCount >= MAX_PER_HOUR) {
          return false; // Block
      }

      // Optimistic Update Local State
      newCount++;
      setSmsUsage({
          count: newCount,
          lastSentHour: currentHour,
          lastSentDate: currentDate
      });

      // Update Database asynchronously
      const updateDb = async () => {
          // Check if row exists, if not create, if yes increment
          // Supabase doesn't have a simple atomic increment without RPC, but we can do a fetch-then-update or upsert with assumption

          // 1. Fetch specific row to ensure we have latest (optional but safer)
          // For simplicity in this POS context, we assume the subscription keeps us relatively up to date

          // Using raw SQL via RPC is best for atomic increment, but sticking to client library:
          // We will upsert. To avoid race conditions perfectly we need RPC, but here last-write-wins is acceptable for a soft limit.

          // Fetch current DB count to be safe against race conditions from other devices
          const { data } = await supabase.from('sms_tracker').select('count').eq('hour_key', hourKey).single();

          let dbCount = data ? data.count : 0;
          dbCount++;

          await supabase.from('sms_tracker').upsert({
              hour_key: hourKey,
              count: dbCount,
              updated_at: new Date().toISOString()
          });
      };

      updateDb();
      return true;
  };

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);

    // Fix log upsert (Map to snake_case)
    const payload = mapLogPayload(newLog);
    upsertData('logs', payload);
  };

  const registerDevice = useCallback(async () => {
     const networkInfo = await getNetworkInfo();
     const deviceInfo = getDeviceInfo();

     setDevices(prev => {
         const existing = prev.find(d => d.id === currentDeviceId);
         const currentStatus = existing ? existing.status : 'PENDING';
         const currentCustomName = existing ? existing.custom_name : undefined;

         const device: Device = {
             id: currentDeviceId,
             name: deviceInfo.name,
             custom_name: currentCustomName,
             os: deviceInfo.os,
             browser: deviceInfo.browser,
             device_type: deviceInfo.device_type,
             ip: networkInfo.ip,
             location: networkInfo.location,
             status: currentStatus, 
             lastActive: new Date().toISOString()
         };

         // Fix Device upsert (Map to snake_case)
         const saveToDb = async () => {
             const payload = mapDevicePayload(device);
             const { error } = await upsertData('devices', payload);
             if (error && (error.message.includes('column') || error.code === '42703')) {
                 console.warn("Database schema mismatch. Attempting legacy save.");
                 const { device_type, custom_name, ...legacyDevice } = device;
                 upsertData('devices', legacyDevice);
             }
         };
         saveToDb();

         if (existing) {
             return prev.map(d => d.id === currentDeviceId ? device : d);
         }
         return [...prev, device];
     });

  }, [currentDeviceId]);

  const updateDeviceStatus = async (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => {
      const dev = devices.find(d => d.id === deviceId);
      if (dev) {
          const updated = { ...dev, status, custom_name: customName || dev.custom_name };
          setDevices(prev => prev.map(d => d.id === deviceId ? updated : d));

          // Fix upsert (Map to snake_case)
          const payload = mapDevicePayload(updated);
          const { error } = await upsertData('devices', payload);

          if (error && (error.message.includes('column') || error.code === '42703')) {
               const { custom_name, ...legacy } = updated;
               await upsertData('devices', legacy);
          }

          const details = customName ? `${status} device: ${dev.name} as "${customName}"` : `${status} device: ${dev.name}`;
          addLog('SETTINGS', details);
      }
