-- 1. Fix DEVICES table (Rename "lastActive" to last_active for consistency)
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_name = 'devices' AND column_name = 'lastActive'
    ) THEN
        ALTER TABLE public.devices RENAME COLUMN "lastActive" TO last_active;
    END IF;
END
$$;

