DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_name = 'messages' AND column_name = 'read'
    ) THEN
        ALTER TABLE public.messages ADD COLUMN read boolean DEFAULT false;
    END IF;
END
