                        ip: networkInfo.ip,
                        location: networkInfo.location
                    };
                    // Fix upsert (Map to snake_case)
                    const payload = mapDevicePayload(updatedDevice);
                    upsertData('devices', payload);
                }
                return true;
             }
        }
    }
    return false;
  };

