    const petDetails: Pet = {
        id: Date.now().toString(),
        name: apt.petName,
        breed: apt.petBreed,
        color: apt.petColor,
        weightSize: apt.weightSize
    };

    if (!existingClient) {
        const newClient: Client = {
            id: Date.now().toString(),
            name: apt.ownerName,
            contactNumber: apt.contactNumber || '',
            email: apt.email || '',
            address: '',
            notes: `Auto-created from Grooming.`,
            firstSeen: new Date().toISOString(),
            pets: [petDetails]
        };
        addClient(newClient);
    } else {
        const currentPets = existingClient.pets || [];
        const existingPetIndex = currentPets.findIndex(p => p.name.toLowerCase() === apt.petName.toLowerCase());

        let updatedPets = [...currentPets];

        if (existingPetIndex >= 0) {
            updatedPets[existingPetIndex] = {
                ...updatedPets[existingPetIndex],
                breed: apt.petBreed || updatedPets[existingPetIndex].breed,
                color: apt.petColor || updatedPets[existingPetIndex].color,
                weightSize: apt.weightSize || updatedPets[existingPetIndex].weightSize
            };
        } else {
            updatedPets.push(petDetails);
        }

        const updatedClient: Client = { 
            ...existingClient, 
            contactNumber: apt.contactNumber || existingClient.contactNumber,
            email: apt.email || existingClient.email,
            pets: updatedPets
        };
        updateClient(updatedClient);
    }
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    saveAppointmentToDb(apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = async (id: string) => {
    const prev = [...appointments];
    const apt = appointments.find(a => a.id === id);
    if (!apt) return;

    setAppointments(current => current.filter(a => a.id !== id));

    const { error } = await deleteData('appointments', id);
    if (error) {
        setAppointments(prev);
        alert("Failed to cancel appointment.");
    } else {
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        setAppointments(prev => prev.map(a => a.id === id ? updatedApt : a));
        saveAppointmentToDb(updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    const payload = mapDiscountPayload(discount);
    upsertData('discounts', payload);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        setDiscounts(prev => prev.map(d => d.id === id ? updated : d));
        const payload = mapDiscountPayload(updated);
        upsertData('discounts', payload);
    }
  };

  const deleteDiscount = async (id: string) => {
    const prev = [...discounts];
    setDiscounts(current => current.filter(d => d.id !== id));

    const { error } = await deleteData('discounts', id);
    if (error) {
        setDiscounts(prev);
        alert("Failed to delete discount.");
    } else {
        addLog('PROMO', `Deleted discount: ${id}`);
    }
  };

  // CATEGORY ACTIONS

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = async (category: string) => {
     const prev = [...productCategories];
     setProductCategories(current => current.filter(c => c !== category));

     const { error } = await supabase.from('product_categories').delete().eq('name', category);
     if (error) {
         setProductCategories(prev);
         alert("Failed to delete category.");
     } else {
         addLog('SETTINGS', `Deleted product category: ${category}`);
     }
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = async (category: string) => {
    const prev = [...serviceCategories];
    setServiceCategories(current => current.filter(c => c !== category));

    const { error } = await supabase.from('service_categories').delete().eq('name', category);
    if (error) {
        setServiceCategories(prev);
        alert("Failed to delete category.");
    } else {
        addLog('SETTINGS', `Deleted service category: ${category}`);
    }
  };

  // --- TEMPLATE HISTORY ACTIONS ---
  const saveTemplateHistory = (
      category: 'GROOMING' | 'PROMO', 
      channel: 'SMS' | 'EMAIL_SUBJECT' | 'EMAIL_BODY' | 'EMAIL_FOOTER', 
      content: string
  ) => {
      if (!content.trim()) return;

      const existing = templateHistory
          .filter(h => h.category === category && h.channel === channel)
          .sort((a,b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())[0];

      if (existing && existing.content === content) return;

      const newHistory: TemplateHistory = {
          id: crypto.randomUUID(),
          category,
          channel,
          content,
          created_at: new Date().toISOString()
      };

      setTemplateHistory(prev => [newHistory, ...prev]);
      upsertData('template_history', newHistory);
  };

  const deleteTemplateHistory = async (id: string) => {
      setTemplateHistory(prev => prev.filter(h => h.id !== id));
      await deleteData('template_history', id);
  };

  // --- CHAT ACTIONS ---
  const sendChatMessage = async (clientId: string, content: string, channel: 'SMS' | 'EMAIL'): Promise<boolean> => {
      const client = clients.find(c => c.id === clientId);
      if (!client) return false;

      let success = false;

      // 1. Send via API (TextBee or Gmail)
      if (channel === 'SMS' && client.contactNumber) {
          if (checkAndIncrementSms()) {
              const res = await sendSMS(storeSettings, [client.contactNumber], content);
              success = res.success;
          } else {
              console.warn("SMS Limit reached");
              return false;
          }
      } else if (channel === 'EMAIL' && client.email) {
          const res = await sendEmail(storeSettings, client.email, "Message from PawFriends", content, "Message");
          success = res.success;
      }

      // 2. Save to Database (if sent or attempted, store as Outbound)
      if (success) {
          const newMessage: Message = {
              id: crypto.randomUUID(),
              client_id: clientId,
              direction: 'OUTBOUND',
              channel: channel,
              content: content,
              timestamp: new Date().toISOString(),
              status: 'SENT',
              read: true // Outbound messages are implicitly read by sender
          };

          setMessages(prev => [...prev, newMessage]);
          upsertData('messages', newMessage);
      }

      return success;
  };

  const markMessagesAsRead = async (clientId: string, channel: 'SMS' | 'EMAIL') => {
      // Optimistic Update
      setMessages(prev => prev.map(m => 
          (m.client_id === clientId && m.channel === channel && m.direction === 'INBOUND' && !m.read)
          ? { ...m, read: true }
          : m
      ));

      // DB Update
      await supabase.from('messages')
          .update({ read: true })
          .eq('client_id', clientId)
          .eq('channel', channel)
          .eq('direction', 'INBOUND')
          .eq('read', false);
  };

  return (
    <StoreContext.Provider value={{
      isLoading, isSystemSetup,
      currentUser, users, products, transactions, appointments, clients, discounts, logs, 
      devices, currentDeviceId, currentDeviceStatus,
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      smsUsage, checkAndIncrementSms,
      login, logout, addUser, editUser, deleteUser,
      registerDevice, updateDeviceStatus, deleteDevice,
      addProduct, updateProduct, deleteProduct,
      adjustStock, 
      addTransaction, deleteTransaction, updateTransaction,
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addClient, updateClient, deleteClient,
      addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory,
      templateHistory, saveTemplateHistory, deleteTemplateHistory,
      messages, sendChatMessage, markMessagesAsRead
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useEffect, useRef } from 'react';
import { Settings as SettingsIcon, Dog, Upload, CreditCard, Cloud, Trash2, HardDrive, AlertCircle, Database, Bell, MessageSquare, Mail, CheckCircle, ExternalLink, Pencil, Smartphone, Monitor, Tag, Scissors, RotateCcw, History, ArrowRight, Info } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { supabase } from '../services/supabase';
import Button from '../components/ui/Button';
import { StoreSettings, TemplateHistory } from '../types';
import { generateGroomingEmailHtml } from '../services/notifications';
import { Dialog } from '@headlessui/react';

type ChannelView = 'SMS' | 'EMAIL';
type TemplateCategory = 'GROOMING' | 'PROMO';
type PromoScenario = 'PERCENTAGE' | 'FIXED' | 'MIN_SPEND' | 'ITEM_COUNT';

const Settings: React.FC = () => {
  const { storeSettings, updateStoreSettings, templateHistory, saveTemplateHistory, deleteTemplateHistory } = useStore();
  // formData tracks text fields for the "Edit" mode
  const [formData, setFormData] = useState<StoreSettings>(storeSettings);
  const [isEditingGeneral, setIsEditingGeneral] = useState(false);
  const [isEditingNotify, setIsEditingNotify] = useState(false);

  // New State for Channel & Template Toggle
  const [activeChannel, setActiveChannel] = useState<ChannelView>('SMS');
  const [activeTemplateCategory, setActiveTemplateCategory] = useState<TemplateCategory>('GROOMING');
  const [promoPreviewScenario, setPromoPreviewScenario] = useState<PromoScenario>('PERCENTAGE');

  // Storage Usage States
  const [dbUsageBytes, setDbUsageBytes] = useState<number>(0);
  const [isCheckingUsage, setIsCheckingUsage] = useState(false);
  const [usageError, setUsageError] = useState(false);

  // History Modal State
  const [historyModalOpen, setHistoryModalOpen] = useState(false);
  const [activeHistoryType, setActiveHistoryType] = useState<'SMS' | 'EMAIL_SUBJECT' | 'EMAIL_BODY' | 'EMAIL_FOOTER'>('SMS');

  // Delete Confirmation State for History
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null}>({
    isOpen: false, id: null
  });

  // Refs for file inputs to clear them on remove/change
  const logoInputRef = useRef<HTMLInputElement>(null);
  const qrInputRef = useRef<HTMLInputElement>(null);

  const FREE_TIER_LIMIT = 500 * 1024 * 1024; // 500 MB in Bytes

  // Sync formData with storeSettings when not editing
  useEffect(() => {
    if (!isEditingGeneral && !isEditingNotify) {
        setFormData(storeSettings);
    }
  }, [storeSettings, isEditingGeneral, isEditingNotify]);

  // Fetch Database Size on Mount
  useEffect(() => {
    const fetchUsage = async () => {
        setIsCheckingUsage(true);
        // Call the RPC function we asked the user to create
        const { data, error } = await supabase.rpc('get_database_size_bytes');

        if (error) {
            console.warn("Storage tracking unavailable. SQL function might be missing.", error);
            setUsageError(true);
        } else {
            setDbUsageBytes(Number(data));
            setUsageError(false);
        }
        setIsCheckingUsage(false);
    };

    fetchUsage();
  }, []);

  const handleSaveGeneral = () => {
    const mergedSettings = {
        ...storeSettings,
        name: formData.name,
        address: formData.address,
        contactNumber: formData.contactNumber,
        vatRate: formData.vatRate,
        gcashNumber: formData.gcashNumber,
        receiptHeader: formData.receiptHeader,
        receiptFooter: formData.receiptFooter
    };
    updateStoreSettings(mergedSettings);
    setIsEditingGeneral(false);
  };

  const handleSaveNotify = () => {
    // 1. Save Current Inputs to History BEFORE updating (ONLY IF CHANGED)

    const hasChanged = (newVal: string | undefined, oldVal: string | undefined) => {
        return (newVal || '').trim() !== (oldVal || '').trim();
    };

    if (activeTemplateCategory === 'GROOMING') {
        if (hasChanged(formData.smsTemplateCompleted, storeSettings.smsTemplateCompleted)) {
             saveTemplateHistory('GROOMING', 'SMS', formData.smsTemplateCompleted || '');
        }
        if (hasChanged(formData.emailSubjectCompleted, storeSettings.emailSubjectCompleted)) {
             saveTemplateHistory('GROOMING', 'EMAIL_SUBJECT', formData.emailSubjectCompleted || '');
        }
        if (hasChanged(formData.emailBodyCompleted, storeSettings.emailBodyCompleted)) {
             saveTemplateHistory('GROOMING', 'EMAIL_BODY', formData.emailBodyCompleted || '');
        }
    } else {
        // PROMO
        if (hasChanged(formData.smsTemplatePromo, storeSettings.smsTemplatePromo)) {
             saveTemplateHistory('PROMO', 'SMS', formData.smsTemplatePromo || '');
        }
        if (hasChanged(formData.emailSubjectPromo, storeSettings.emailSubjectPromo)) {
             saveTemplateHistory('PROMO', 'EMAIL_SUBJECT', formData.emailSubjectPromo || '');
        }
        if (hasChanged(formData.emailBodyPromo, storeSettings.emailBodyPromo)) {
             saveTemplateHistory('PROMO', 'EMAIL_BODY', formData.emailBodyPromo || '');
        }
    }

    if (hasChanged(formData.emailFooterText, storeSettings.emailFooterText)) {
        saveTemplateHistory(activeTemplateCategory, 'EMAIL_FOOTER', formData.emailFooterText || '');
    }

    // 2. Merge and Save to DB
    const mergedSettings = { ...storeSettings, ...formData };
    updateStoreSettings(mergedSettings);
    setIsEditingNotify(false);
  };

  const handleCancelGeneral = () => {
      setFormData(storeSettings); // Revert to current store state
      setIsEditingGeneral(false);
  }

  const handleCancelNotify = () => {
    setFormData(storeSettings);
    setIsEditingNotify(false);
  }

  // --- HISTORY LOGIC ---
  const openHistory = (type: 'SMS' | 'EMAIL_SUBJECT' | 'EMAIL_BODY' | 'EMAIL_FOOTER') => {
      setActiveHistoryType(type);
      setHistoryModalOpen(true);
  };

  const restoreFromHistory = (item: TemplateHistory) => {
      setFormData(prev => {
          const updates = { ...prev };
          if (item.channel === 'EMAIL_FOOTER') {
              updates.emailFooterText = item.content;
          } else if (item.category === 'GROOMING') {
              if (item.channel === 'SMS') updates.smsTemplateCompleted = item.content;
              if (item.channel === 'EMAIL_SUBJECT') updates.emailSubjectCompleted = item.content;
              if (item.channel === 'EMAIL_BODY') updates.emailBodyCompleted = item.content;
          } else {
              // PROMO
              if (item.channel === 'SMS') updates.smsTemplatePromo = item.content;
              if (item.channel === 'EMAIL_SUBJECT') updates.emailSubjectPromo = item.content;
              if (item.channel === 'EMAIL_BODY') updates.emailBodyPromo = item.content;
          }
          return updates;
      });
      setHistoryModalOpen(false);
  };

  const confirmDeleteHistory = () => {
      if (deleteConfirmation.id) {
          deleteTemplateHistory(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null });
      }
  };

  const currentHistoryLogs = templateHistory
      .filter(h => {
          if (activeHistoryType === 'EMAIL_FOOTER') {
              return h.channel === 'EMAIL_FOOTER';
          }
          return h.category === activeTemplateCategory && h.channel === activeHistoryType;
      })
      .sort((a,b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());


  // --- MOCK PREVIEW LOGIC ---
  const getPreviewData = () => {
      const replace = (text: string = "", data: Record<string, string>) => {
          let result = text;
          for (const key in data) {
              result = result.replace(new RegExp(`{${key}}`, 'g'), data[key]);
          }
          return result;
      };

      if (activeTemplateCategory === 'GROOMING') {
          const mockGroomingData = {
              petName: "Buddy",
              ownerName: "John Doe",
              shopName: formData.name || "PawFriends",
              date: new Date().toLocaleDateString(),
              time: "10:00 AM",
              serviceName: "Full Groom",
              price: "500"
          };
          const rawSms = formData.smsTemplateCompleted || "";
          const rawEmailSubject = formData.emailSubjectCompleted || "";
          const rawEmailBody = formData.emailBodyCompleted || "";
          const title = "Ready for Pickup";

          return {
              sms: replace(rawSms, mockGroomingData),
              emailSubject: replace(rawEmailSubject, mockGroomingData),
              emailHtml: generateGroomingEmailHtml(formData, replace(rawEmailBody, mockGroomingData), title)
          };
      } else {
          // PROMO PREVIEW - Dynamic Scenarios
          let mockPromoData;
          switch (promoPreviewScenario) {
              case 'FIXED':
                  mockPromoData = {
                      promoName: "Welcome Gift",
                      discountValue: "₱100 OFF",
                      rules: "Valid for first-time customers.",
                      endDate: "No Expiry",
                      shopName: formData.name || "PawFriends",
                      address: formData.address || "123 Main St",
                  };
                  break;
              case 'MIN_SPEND':
                  mockPromoData = {
                      promoName: "Big Spender Event",
                      discountValue: "₱500 OFF",
                      rules: "Min. spend of ₱3,000 required.",
                      endDate: "Next Sunday",
                      shopName: formData.name || "PawFriends",
                      address: formData.address || "123 Main St",
                  };
                  break;
              case 'ITEM_COUNT':
                  mockPromoData = {
                      promoName: "Treats Bundle",
                      discountValue: "15% OFF",
                      rules: "Buy at least 3 items.",
                      endDate: "While stocks last",
                      shopName: formData.name || "PawFriends",
                      address: formData.address || "123 Main St",
                  };
                  break;
              case 'PERCENTAGE':
              default:
                  mockPromoData = {
                      promoName: "Summer Sale",
                      discountValue: "20% OFF",
                      rules: "Valid on all grooming services.",
                      endDate: "Dec 31, 2024",
                      shopName: formData.name || "PawFriends",
                      address: formData.address || "123 Main St",
                  };
                  break;
          }

          const rawSms = formData.smsTemplatePromo || "";
          const rawEmailSubject = formData.emailSubjectPromo || "";
          const rawEmailBody = formData.emailBodyPromo || "";
