        const product = products.find(p => p.id === item.id);
        if (product) {
           const updated = { ...product, stock: product.stock + item.quantity };
           upsertData('products', updated); // DB
           setProducts(prev => prev.map(p => p.id === product.id ? updated : p)); // Local
        }
      }
    }

    const { error } = await deleteData('transactions', id);
    if (!error) {
        setTransactions(prev => prev.filter(t => t.id !== id));
        addLog('POS', `Deleted Transaction #${id.slice(-4)}`);
    } else {
        alert("Failed to delete transaction");
    }
  };

  const updateTransaction = async (oldTx: Transaction, newTx: Transaction) => {
      // Calculate Stock Differences
      const adjustments = new Map<string, number>();

      // Revert old items (add back to stock)
      oldTx.items.forEach(item => {
          if (!item.isService) {
              const current = adjustments.get(item.id) || 0;
              adjustments.set(item.id, current + item.quantity);
          }
      });

      // Apply new items (subtract from stock)
      newTx.items.forEach(item => {
          if (!item.isService) {
              const current = adjustments.get(item.id) || 0;
              adjustments.set(item.id, current - item.quantity);
          }
      });

      // Execute Adjustments
      for (const [pid, delta] of adjustments.entries()) {
          if (delta !== 0) {
              const product = products.find(p => p.id === pid);
              if (product) {
                  const updated = { ...product, stock: product.stock + delta };
                  upsertData('products', updated);
                  setProducts(prev => prev.map(p => p.id === pid ? updated : p));
              }
          }
      }

      const payload = mapTransactionPayload(newTx);
      const { error } = await upsertData('transactions', payload);

      if (!error) {
          setTransactions(prev => prev.map(t => t.id === newTx.id ? newTx : t));
          addLog('POS', `Updated Transaction #${newTx.id.slice(-4)}`);
      } else {
          alert("Failed to update transaction");
      }
  };

  // --- CLIENT MANAGEMENT ---

  const addClient = (client: Client) => {
    setClients(prev => [client, ...prev]);
    saveClientToDb(client);
    addLog('CLIENTS', `Added new client: ${client.name}`);
  };

  const updateClient = (client: Client) => {
    setClients(prev => prev.map(c => c.id === client.id ? client : c));
    saveClientToDb(client);
  };

  const deleteClient = async (id: string) => {
    const prev = [...clients];
    const client = clients.find(c => c.id === id);
    if (!client) return;

    setClients(current => current.filter(c => c.id !== id));

    const { error } = await deleteData('clients', id);
    if (error) {
        setClients(prev);
        alert(`Failed to delete client. Database error: ${error.message}`);
    } else {
        addLog('CLIENTS', `Deleted client: ${client.name}`);
    }
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [apt, ...prev]);
    saveAppointmentToDb(apt);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);

    const existingClient = clients.find(c => c.name.toLowerCase() === apt.ownerName.toLowerCase());

    const petDetails: Pet = {
        id: Date.now().toString(),
        name: apt.petName,
        breed: apt.petBreed,
        color: apt.petColor,
        weightSize: apt.weightSize
    };

    if (!existingClient) {
        const newClient: Client = {
            id: Date.now().toString(),
            name: apt.ownerName,
            contactNumber: apt.contactNumber || '',
            email: apt.email || '',
            address: '',
            notes: `Auto-created from Grooming.`,
            firstSeen: new Date().toISOString(),
            pets: [petDetails]
        };
        addClient(newClient);
    } else {
        const currentPets = existingClient.pets || [];
        const existingPetIndex = currentPets.findIndex(p => p.name.toLowerCase() === apt.petName.toLowerCase());

        let updatedPets = [...currentPets];

        if (existingPetIndex >= 0) {
            updatedPets[existingPetIndex] = {
                ...updatedPets[existingPetIndex],
                breed: apt.petBreed || updatedPets[existingPetIndex].breed,
                color: apt.petColor || updatedPets[existingPetIndex].color,
                weightSize: apt.weightSize || updatedPets[existingPetIndex].weightSize
            };
        } else {
            updatedPets.push(petDetails);
        }

        const updatedClient: Client = { 
            ...existingClient, 
            contactNumber: apt.contactNumber || existingClient.contactNumber,
            email: apt.email || existingClient.email,
            pets: updatedPets
        };
        updateClient(updatedClient);
    }
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    saveAppointmentToDb(apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = async (id: string) => {
    const prev = [...appointments];
    const apt = appointments.find(a => a.id === id);
    if (!apt) return;

    setAppointments(current => current.filter(a => a.id !== id));

    const { error } = await deleteData('appointments', id);
    if (error) {
        setAppointments(prev);
        alert("Failed to cancel appointment.");
    } else {
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        setAppointments(prev => prev.map(a => a.id === id ? updatedApt : a));
        saveAppointmentToDb(updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    const payload = mapDiscountPayload(discount);
    upsertData('discounts', payload);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        setDiscounts(prev => prev.map(d => d.id === id ? updated : d));
        const payload = mapDiscountPayload(updated);
        upsertData('discounts', payload);
    }
  };

  const deleteDiscount = async (id: string) => {
    const prev = [...discounts];
    setDiscounts(current => current.filter(d => d.id !== id));

    const { error } = await deleteData('discounts', id);
    if (error) {
        setDiscounts(prev);
        alert("Failed to delete discount.");
    } else {
        addLog('PROMO', `Deleted discount: ${id}`);
    }
  };

  // CATEGORY ACTIONS

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = async (category: string) => {
     const prev = [...productCategories];
     setProductCategories(current => current.filter(c => c !== category));

     const { error } = await supabase.from('product_categories').delete().eq('name', category);
     if (error) {
         setProductCategories(prev);
         alert("Failed to delete category.");
     } else {
         addLog('SETTINGS', `Deleted product category: ${category}`);
     }
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = async (category: string) => {
    const prev = [...serviceCategories];
    setServiceCategories(current => current.filter(c => c !== category));

    const { error } = await supabase.from('service_categories').delete().eq('name', category);
    if (error) {
        setServiceCategories(prev);
        alert("Failed to delete category.");
    } else {
        addLog('SETTINGS', `Deleted service category: ${category}`);
    }
  };

  // --- TEMPLATE HISTORY ACTIONS ---
  const saveTemplateHistory = (
      category: 'GROOMING' | 'PROMO', 
      channel: 'SMS' | 'EMAIL_SUBJECT' | 'EMAIL_BODY' | 'EMAIL_FOOTER', 
      content: string
  ) => {
      if (!content.trim()) return;

      const existing = templateHistory
          .filter(h => h.category === category && h.channel === channel)
          .sort((a,b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime())[0];

      if (existing && existing.content === content) return;

      const newHistory: TemplateHistory = {
          id: crypto.randomUUID(),
          category,
          channel,
          content,
          created_at: new Date().toISOString()
      };

      setTemplateHistory(prev => [newHistory, ...prev]);
      upsertData('template_history', newHistory);
  };

  const deleteTemplateHistory = async (id: string) => {
      setTemplateHistory(prev => prev.filter(h => h.id !== id));
      await deleteData('template_history', id);
  };

  // --- CHAT ACTIONS ---
  const sendChatMessage = async (clientId: string, content: string, channel: 'SMS' | 'EMAIL'): Promise<boolean> => {
      const client = clients.find(c => c.id === clientId);
      if (!client) return false;

      let success = false;

      // 1. Send via API (TextBee or Gmail)
      if (channel === 'SMS' && client.contactNumber) {
          if (checkAndIncrementSms()) {
              const res = await sendSMS(storeSettings, [client.contactNumber], content);
              success = res.success;
          } else {
              console.warn("SMS Limit reached");
              return false;
          }
      } else if (channel === 'EMAIL' && client.email) {
          const res = await sendEmail(storeSettings, client.email, "Message from PawFriends", content, "Message");
          success = res.success;
      }

      // 2. Save to Database (if sent or attempted, store as Outbound)
      if (success) {
          const newMessage: Message = {
              id: crypto.randomUUID(),
              client_id: clientId,
              direction: 'OUTBOUND',
              channel: channel,
              content: content,
              timestamp: new Date().toISOString(),
              status: 'SENT',
              read: true // Outbound messages are implicitly read by sender
          };

          setMessages(prev => [...prev, newMessage]);
          upsertData('messages', newMessage);
      }

      return success;
  };

  const markMessagesAsRead = async (clientId: string, channel: 'SMS' | 'EMAIL') => {
      // Optimistic Update
      setMessages(prev => prev.map(m => 
          (m.client_id === clientId && m.channel === channel && m.direction === 'INBOUND' && !m.read)
          ? { ...m, read: true }
          : m
      ));

      // DB Update
      await supabase.from('messages')
          .update({ read: true })
          .eq('client_id', clientId)
          .eq('channel', channel)
          .eq('direction', 'INBOUND')
          .eq('read', false);
  };

  return (
    <StoreContext.Provider value={{
      isLoading, isSystemSetup,
      currentUser, users, products, transactions, appointments, clients, discounts, logs, 
      devices, currentDeviceId, currentDeviceStatus,
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      smsUsage, checkAndIncrementSms,
      login, logout, addUser, editUser, deleteUser,
      registerDevice, updateDeviceStatus, deleteDevice,
      addProduct, updateProduct, deleteProduct,
      adjustStock, 
      addTransaction, deleteTransaction, updateTransaction,
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addClient, updateClient, deleteClient,
      addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory,
      templateHistory, saveTemplateHistory, deleteTemplateHistory,
      messages, sendChatMessage, markMessagesAsRead
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext';
import { Message, Client } from '../types';
import { MessageSquare, Mail, X, Send, ChevronDown, User, Smartphone, Search, Loader2, ArrowRight, Check, CheckCircle, RotateCcw } from './ui/Icons';

type Tab = 'SMS' | 'EMAIL';
type View = 'LIST' | 'CHAT';

const ChatWidget: React.FC = () => {
    const { clients, messages, sendChatMessage, markMessagesAsRead } = useStore();

    // UI State
    const [isOpen, setIsOpen] = useState(false);
    const [view, setView] = useState<View>('LIST');
    const [activeTab, setActiveTab] = useState<Tab>('SMS');
    const [selectedClientId, setSelectedClientId] = useState<string | null>(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [inputValue, setInputValue] = useState('');
    const [isSending, setIsSending] = useState(false);

    const messagesEndRef = useRef<HTMLDivElement>(null);

    const selectedClient = useMemo(() => 
        clients.find(c => c.id === selectedClientId), 
    [clients, selectedClientId]);

    // Format Relative Time (Facebook Style)
    const formatTimeAgo = (dateStr: string) => {
        const date = new Date(dateStr);
        const now = new Date();
        const diff = Math.floor((now.getTime() - date.getTime()) / 1000); // seconds

        if (diff < 60) return 'Just now';
        if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
        if (diff < 86400) {
            const hrs = Math.floor(diff / 3600);
            return hrs === 1 ? '1h ago' : `${hrs}h ago`;
        }
        if (diff < 604800) { // < 7 days
            return date.toLocaleDateString('en-US', { weekday: 'short' });
        }
        return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
    };

    const formatMessageTime = (dateStr: string) => {
        const date = new Date(dateStr);
        const now = new Date();
        const isToday = date.toDateString() === now.toDateString();

        // Time string e.g. "10:30 AM"
        const time = date.toLocaleTimeString([], {hour: 'numeric', minute:'2-digit'});

        if (isToday) return time;

        // Check if yesterday
        const yesterday = new Date(now);
        yesterday.setDate(now.getDate() - 1);
        if (date.toDateString() === yesterday.toDateString()) {
            return `Yesterday at ${time}`;
        }

        // Older
        return `${date.toLocaleDateString(undefined, {weekday: 'short'})} at ${time}`;
    };

    // Filter & Sort Clients Logic
    const sortedClients = useMemo(() => {
        return clients
            .filter(c => {
                // Must have contact info for current tab
                const hasContact = activeTab === 'SMS' ? !!c.contactNumber : !!c.email;
                if (!hasContact) return false;

                // Search Filter
                const searchLower = searchTerm.toLowerCase();
                if (!searchLower) return true;
                return (
                    c.name.toLowerCase().includes(searchLower) || 
                    (c.contactNumber && c.contactNumber.includes(searchLower)) || 
                    (c.email && c.email.toLowerCase().includes(searchLower))
                );
            })
            .map(client => {
                // Attach metadata for sorting
                const clientMessages = messages.filter(m => m.client_id === client.id && m.channel === activeTab);
                const lastMsg = clientMessages.sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())[0];
                const unreadCount = clientMessages.filter(m => m.direction === 'INBOUND' && !m.read).length;

                return {
                    ...client,
                    lastMsg,
                    lastMsgTime: lastMsg ? new Date(lastMsg.timestamp).getTime() : 0,
                    unreadCount
                };
            })
            .sort((a, b) => {
                // Sort by most recent message first
                if (a.lastMsgTime !== b.lastMsgTime) return b.lastMsgTime - a.lastMsgTime;
                return a.name.localeCompare(b.name);
            });
    }, [clients, messages, searchTerm, activeTab]);

    const activeConversation = useMemo(() => {
        if (!selectedClientId) return [];
        return messages
            .filter(m => m.client_id === selectedClientId && m.channel === activeTab)
            .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
    }, [messages, selectedClientId, activeTab]);

    // Scroll to bottom on new message
    useEffect(() => {
        if (view === 'CHAT' && messagesEndRef.current) {
            messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [activeConversation, view]);

    // Handle Marking as Read when entering chat
    useEffect(() => {
        if (view === 'CHAT' && selectedClientId) {
            markMessagesAsRead(selectedClientId, activeTab);
        }
    }, [view, selectedClientId, activeTab, markMessagesAsRead, messages]);

    const handleClientSelect = (clientId: string) => {
        setSelectedClientId(clientId);
        setView('CHAT');
        markMessagesAsRead(clientId, activeTab);
    };

    const handleBackToList = () => {
        setView('LIST');
        setSelectedClientId(null);
    };

    const handleSend = async () => {
        if (!inputValue.trim() || !selectedClientId) return;

        setIsSending(true);
        const success = await sendChatMessage(selectedClientId, inputValue, activeTab);
        setIsSending(false);

        if (success) {
            setInputValue('');
        } else {
            alert(`Failed to send ${activeTab}. Check settings.`);
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSend();
        }
    };

    if (!isOpen) {
        return (
            <button 
                onClick={() => setIsOpen(true)}
                className="fixed bottom-4 right-4 bg-blue-600 hover:bg-blue-700 text-white rounded-full p-4 shadow-2xl z-[500] transition-all hover:scale-110 flex items-center justify-center animate-bounce-in"
                title="Open Messages"
            >
                <div className="relative">
                    <MessageSquare className="w-7 h-7" />
                    {/* Global Unread Count Badge */}
                    {sortedClients.reduce((acc, c) => acc + c.unreadCount, 0) > 0 && (
                        <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold w-4 h-4 rounded-full flex items-center justify-center border-2 border-blue-600">
                            {sortedClients.reduce((acc, c) => acc + c.unreadCount, 0)}
                        </span>
                    )}
                </div>
            </button>
        );
    }

    return (
        <div className={`fixed bottom-4 right-4 bg-white rounded-2xl shadow-2xl z-[500] flex flex-col border border-zinc-200 overflow-hidden font-sans transition-all duration-300 w-[380px] h-[600px]`}>

            {/* Header */}
            <div className="bg-blue-600 p-3 text-white shrink-0 shadow-sm flex justify-between items-center">
                <div className="flex items-center gap-2">
                    {view === 'CHAT' && (
                        <button onClick={handleBackToList} className="p-1 hover:bg-white/10 rounded-full mr-1">
                            <ArrowRight className="w-5 h-5 rotate-180" />
                        </button>
                    )}
                    <h3 className="font-bold text-sm">
                        {view === 'CHAT' && selectedClient ? selectedClient.name : 'PawFriends Messenger'}
                    </h3>
                </div>
                <button onClick={() => setIsOpen(false)} className="p-1 hover:bg-white/10 rounded">
                    <ChevronDown className="w-5 h-5" />
                </button>
            </div>

            {/* LIST VIEW */}
            {view === 'LIST' && (
                <div className="flex flex-col flex-1 overflow-hidden bg-zinc-50">
                    {/* Tabs */}
                    <div className="flex p-2 gap-2 bg-white border-b border-zinc-200">
                        <button 
                            onClick={() => setActiveTab('SMS')}
                            className={`flex-1 py-2 text-xs font-bold rounded-lg flex items-center justify-center gap-1 transition-colors ${activeTab === 'SMS' ? 'bg-blue-50 text-blue-700 border border-blue-100' : 'text-zinc-500 hover:bg-zinc-50'}`}
                        >
                            <Smartphone className="w-3 h-3" /> SMS
                        </button>
                        <button 
                            onClick={() => setActiveTab('EMAIL')}
                            className={`flex-1 py-2 text-xs font-bold rounded-lg flex items-center justify-center gap-1 transition-colors ${activeTab === 'EMAIL' ? 'bg-orange-50 text-orange-700 border border-orange-100' : 'text-zinc-500 hover:bg-zinc-50'}`}
                        >
                            <Mail className="w-3 h-3" /> Email
                        </button>
                    </div>

                    {/* Search */}
                    <div className="px-3 py-2 bg-white border-b border-zinc-100">
                        <div className="relative">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-zinc-400" />
                            <input 
                                type="text" 
                                placeholder="Search clients..."
                                className="w-full pl-9 pr-3 py-2 text-xs bg-zinc-100 rounded-full border-none focus:ring-1 focus:ring-blue-500 text-zinc-900 placeholder-zinc-400"
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                            />
                        </div>
                    </div>

                    {/* Client List */}
                    <div className="flex-1 overflow-y-auto custom-scrollbar">
                        {sortedClients.length === 0 ? (
                            <div className="flex flex-col items-center justify-center h-40 text-zinc-400">
                                <User className="w-8 h-8 opacity-20 mb-2" />
                                <p className="text-xs">No clients found.</p>
                            </div>
                        ) : (
                            sortedClients.map(client => (
                                <div 
                                    key={client.id}
                                    onClick={() => handleClientSelect(client.id)}
                                    className="px-4 py-3 bg-white border-b border-zinc-50 hover:bg-zinc-50 cursor-pointer flex gap-3 transition-colors relative"
                                >
                                    {/* Avatar */}
                                    <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold text-white shrink-0 relative ${activeTab === 'SMS' ? 'bg-blue-500' : 'bg-orange-500'}`}>
                                        {client.name.charAt(0).toUpperCase()}
                                        {/* Status Dot (Fake for now, implies contact available) */}
                                        <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 border-2 border-white rounded-full"></div>
                                    </div>

                                    {/* Content */}
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between items-baseline mb-0.5">
                                            <h4 className={`text-sm truncate pr-2 ${client.unreadCount > 0 ? 'font-bold text-black' : 'font-semibold text-zinc-800'}`}>
                                                {client.name}
                                            </h4>
                                            {client.lastMsgTime > 0 && (
                                                <span className={`text-[10px] shrink-0 ${client.unreadCount > 0 ? 'text-blue-600 font-bold' : 'text-zinc-400'}`}>
                                                    {formatTimeAgo(client.lastMsg!.timestamp)}
                                                </span>
                                            )}
                                        </div>
                                        <div className="flex justify-between items-center">
                                            <p className={`text-xs truncate max-w-[180px] ${client.unreadCount > 0 ? 'font-bold text-zinc-900' : 'text-zinc-500'}`}>
                                                {client.lastMsg ? (
                                                    client.lastMsg.direction === 'OUTBOUND' 
                                                    ? `You: ${client.lastMsg.content}` 
                                                    : client.lastMsg.content
                                                ) : <span className="italic text-zinc-300">No messages yet</span>}
                                            </p>

                                            {client.unreadCount > 0 && (
                                                <div className="bg-red-500 text-white text-[10px] font-bold h-4 min-w-[16px] px-1 rounded-full flex items-center justify-center ml-2">
                                                    {client.unreadCount}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            )}

            {/* CHAT VIEW */}
            {view === 'CHAT' && selectedClient && (
                <div className="flex flex-col flex-1 overflow-hidden bg-white">
