                                const isSameSender = prevMsg && prevMsg.direction === msg.direction;

                                // Group timestamp logic
                                const showGroupTimestamp = !prevMsg || (new Date(msg.timestamp).getTime() - new Date(prevMsg.timestamp).getTime() > 600000); // 10 mins

