DROP TABLE IF EXISTS messages CASCADE;
DROP TABLE IF EXISTS template_history CASCADE;
DROP TABLE IF EXISTS sms_tracker CASCADE;
DROP TABLE IF EXISTS devices CASCADE;
DROP TABLE IF EXISTS logs CASCADE;
DROP TABLE IF EXISTS discounts CASCADE;
DROP TABLE IF EXISTS transactions CASCADE;
DROP TABLE IF EXISTS appointments CASCADE;
DROP TABLE IF EXISTS clients CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS product_categories CASCADE;
DROP TABLE IF EXISTS service_categories CASCADE;
DROP TABLE IF EXISTS store_settings CASCADE;

-- 2. CREATE TABLES

-- Store Settings
CREATE TABLE store_settings (
    id TEXT PRIMARY KEY,
    name TEXT,
    address TEXT,
    contact_number TEXT,
    vat_rate NUMERIC DEFAULT 0,
    gcash_number TEXT,
    gcash_qr TEXT, -- Base64
    receipt_header TEXT,
    receipt_footer TEXT,
    logo TEXT, -- Base64

    -- Feature Flags
    sms_enabled BOOLEAN DEFAULT FALSE,
    email_enabled BOOLEAN DEFAULT FALSE,

    -- TextBee
    text_bee_api_key TEXT,
    text_bee_device_id TEXT,

    -- Google/Gmail
    google_client_id TEXT,
    google_client_secret TEXT,
    google_refresh_token TEXT,
    email_sender_name TEXT,
    email_footer_text TEXT,

    -- Templates
    sms_template_upcoming TEXT,
    email_subject_upcoming TEXT,
    email_body_upcoming TEXT,

    sms_template_waiting TEXT,
    email_subject_waiting TEXT,
    email_body_waiting TEXT,

    sms_template_ongoing TEXT,
    email_subject_ongoing TEXT,
    email_body_ongoing TEXT,

    sms_template_completed TEXT,
    email_subject_completed TEXT,
    email_body_completed TEXT,

    sms_template_promo TEXT,
    email_subject_promo TEXT,
    email_body_promo TEXT,

    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Users
CREATE TABLE users (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    pin TEXT, -- Stores "SALT:HASH"
    role TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Categories
CREATE TABLE product_categories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT UNIQUE NOT NULL
);

CREATE TABLE service_categories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT UNIQUE NOT NULL
);

-- Products & Services
CREATE TABLE products (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    price NUMERIC DEFAULT 0,
    cost NUMERIC DEFAULT 0,
    stock NUMERIC DEFAULT 0,
    category TEXT,
    is_service BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Clients
CREATE TABLE clients (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    contact_number TEXT,
    email TEXT,
    address TEXT,
    notes TEXT,
    first_seen TIMESTAMPTZ DEFAULT NOW(),
    pets JSONB DEFAULT '[]'::jsonb -- Array of Pet Objects
);

-- Appointments
CREATE TABLE appointments (
    id TEXT PRIMARY KEY,
    pet_name TEXT,
    pet_breed TEXT,
    pet_color TEXT,
    weight_size TEXT,

    owner_name TEXT,
    contact_number TEXT,
    email TEXT,

    service_id TEXT,
    hair_cut TEXT, -- Instructions
    groomer_id TEXT,

    date TEXT, -- YYYY-MM-DD
    time TEXT, -- HH:MM
    status TEXT, -- SCHEDULED, ONGOING, COMPLETED

    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Transactions
CREATE TABLE transactions (
    id TEXT PRIMARY KEY,
    items JSONB DEFAULT '[]'::jsonb, -- Array of CartItems
    subtotal NUMERIC DEFAULT 0,
    vat NUMERIC DEFAULT 0,
    total NUMERIC DEFAULT 0,
    discount NUMERIC DEFAULT 0,

    payment_method TEXT, -- CASH, GCASH, SPLIT
    gcash_ref TEXT,
    cash_received NUMERIC DEFAULT 0,
    cashier_id TEXT,

    date TIMESTAMPTZ DEFAULT NOW()
);

-- Discounts
CREATE TABLE discounts (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    type TEXT, -- PERCENTAGE, FIXED
    value NUMERIC DEFAULT 0,
    active BOOLEAN DEFAULT TRUE,

    trigger_type TEXT DEFAULT 'MANUAL',
    trigger_value TEXT,

    is_permanent BOOLEAN DEFAULT TRUE,
    start_date TEXT,
    end_date TEXT,

    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Logs
CREATE TABLE logs (
    id TEXT PRIMARY KEY,
    action TEXT,
    details TEXT,
    user_id TEXT,
    reference_id TEXT,
    timestamp TIMESTAMPTZ DEFAULT NOW()
);

-- Devices
CREATE TABLE devices (
    id TEXT PRIMARY KEY,
    name TEXT,
    custom_name TEXT,
    os TEXT,
    browser TEXT,
    device_type TEXT,
    status TEXT DEFAULT 'PENDING',
    last_active TIMESTAMPTZ DEFAULT NOW(),
    ip TEXT,
    location TEXT
);

-- SMS Tracker (Hourly limits)
CREATE TABLE sms_tracker (
    hour_key TEXT PRIMARY KEY, -- Format "YYYY-MM-DD-HH"
    count NUMERIC DEFAULT 0,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Template History
CREATE TABLE template_history (
    id TEXT PRIMARY KEY,
    category TEXT,
    channel TEXT,
    content TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Messages (Chat)
CREATE TABLE messages (
    id TEXT PRIMARY KEY,
    client_id TEXT NOT NULL,
    direction TEXT NOT NULL, -- INBOUND, OUTBOUND
    channel TEXT NOT NULL,   -- SMS, EMAIL
    content TEXT,
    status TEXT,             -- SENT, RECEIVED, FAILED
    read BOOLEAN DEFAULT FALSE,
    timestamp TIMESTAMPTZ DEFAULT NOW()
);

