CREATE POLICY "Enable all access" ON devices FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Enable all access" ON sms_tracker FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Enable all access" ON product_categories FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Enable all access" ON service_categories FOR ALL USING (true) WITH CHECK (true);
